import { useEffect, useRef, useState, useCallback } from "react";
import { Bell, ChevronRight, Loader2 } from "lucide-react";
import { useNavigate } from "react-router-dom";
import { Skeleton } from "../Skeleton";
import "./NotificationDropdown.css";

const API_BASE_URL = import.meta.env.VITE_API_BASE_URL || "http://localhost:8080";

const formatMinioUrl = (url) => {
  if (!url || typeof url !== "string") return null;
  const trimmed = url.trim();
  if (!trimmed) return null;
  let formatted = trimmed;
  if (formatted.includes("http://minio:9000")) {
    formatted = formatted.replace("http://minio:9000", "http://localhost:9000");
  }
  if (formatted.startsWith("/")) {
    formatted = `http://localhost:9000${formatted}`;
  }
  return formatted;
};

const AVATAR_PALETTE = [
  "#F472B6", "#A78BFA", "#60A5FA", "#34D399",
  "#FBBF24", "#FB7185", "#38BDF8", "#C084FC"
];

const getAvatarColor = (name) => {
  let hash = 0;
  for (let i = 0; i < (name || "").length; i++) {
    hash = (hash << 5) - hash + name.charCodeAt(i);
    hash |= 0;
  }
  return AVATAR_PALETTE[Math.abs(hash) % AVATAR_PALETTE.length];
};

const NOTIFICATION_TYPE_LABEL = {
  system: "ระบบ",
  novel_update: "นิยาย",
  comment: "คอมเมนต์",
  like: "ถูกใจ",
  follower: "ผู้ติดตาม",
};

const normalizeNotification = (item = {}) => {
  const currentUser = (() => {
    try {
      return JSON.parse(localStorage.getItem("user") || "null");
    } catch {
      return null;
    }
  })();

  const rawType = item.type || item.notification_type || "system";
  const type = rawType === "follow" ? "follower" : rawType;
  const isSystem = type === "system";

  const actorName = isSystem
    ? "StoryVerse ระบบ"
    : (item.actor_name || item.actor?.name || "StoryVerse");

  let actorAvatar = item.actor_avatar || item.actor?.avatar || null;
  // หากเป็นคอมเมนต์/การกระทำของผู้ใช้ปัจจุบัน ดึงรูปโปรไฟล์ของ currentUser มาแสดง
  if (!actorAvatar && !isSystem && currentUser) {
    if (
      (item.actor_id && Number(item.actor_id) === Number(currentUser.id || currentUser.user_id)) ||
      (actorName && currentUser.username && actorName.toLowerCase() === currentUser.username.toLowerCase())
    ) {
      actorAvatar = currentUser.pic_profile || null;
    }
  }

  // แยกชื่อเรื่องและข้อความคอมเมนต์
  let title = item.title || "";
  let body = item.body || item.message || "";
  if (type === "comment" && item.message && item.message.includes("|")) {
    const parts = item.message.split("|");
    if (parts.length >= 2) {
      body = parts.slice(1).join("|").trim();
    }
  }

  return {
    id: item.id ?? item.notification_id,
    type,
    isSystem,
    read: Boolean(item.is_read ?? item.read),
    actorId: item.actor_id ?? item.actor?.id ?? 0,
    actorName,
    actorAvatar: formatMinioUrl(actorAvatar),
    title: title || (type === "comment" ? "นิยาย" : "มีการแจ้งเตือนใหม่"),
    body,
    referenceId: item.reference_id ?? item.referenceId ?? null,
    referenceType: item.reference_type ?? item.referenceType ?? "system",
    createdAt: item.created_at ?? item.createdAt ?? new Date().toISOString(),
    typeLabel: NOTIFICATION_TYPE_LABEL[type] || "ระบบ",
  };
};

const formatTime = (date) => {
  const diff = (Date.now() - new Date(date)) / 1000;
  if (diff < 60) return "เมื่อกี้";
  if (diff < 3600) return `${Math.floor(diff / 60)} นาทีที่แล้ว`;
  if (diff < 86400) return `${Math.floor(diff / 3600)} ชั่วโมงที่แล้ว`;
  return `${Math.floor(diff / 86400)} วันที่แล้ว`;
};

export default function NotificationDropdown({ unreadCount = 0 }) {
  const navigate = useNavigate();
  const dropdownRef = useRef(null);
  const [open, setOpen] = useState(false);
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(false);
  const [failedAvatars, setFailedAvatars] = useState(new Set());

  useEffect(() => {
    const handleOutsideClick = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setOpen(false);
      }
    };
    const handleEscape = (event) => {
      if (event.key === "Escape") setOpen(false);
    };

    document.addEventListener("mousedown", handleOutsideClick);
    document.addEventListener("keydown", handleEscape);
    return () => {
      document.removeEventListener("mousedown", handleOutsideClick);
      document.removeEventListener("keydown", handleEscape);
    };
  }, []);

  const loadRecentNotifications = useCallback(async () => {
    setLoading(true);
    try {
      const token = localStorage.getItem("token");
      const response = await fetch(`${API_BASE_URL}/notifications?limit=5`, {
        credentials: "include",
        headers: token ? { Authorization: `Bearer ${token}` } : {},
      });
      if (!response.ok) throw new Error(`Request failed: ${response.status}`);

      const payload = await response.json();
      const data = payload?.data ?? payload;
      const list = Array.isArray(data)
        ? data
        : Array.isArray(data?.notifications)
          ? data.notifications
          : [];
      setItems(list.map(normalizeNotification).slice(0, 5));
    } catch (error) {
      console.warn("โหลดแจ้งเตือนใน dropdown ไม่สำเร็จ", error);
      setItems([]);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    if (open) {
      loadRecentNotifications();
    }
  }, [open, loadRecentNotifications]);

  // ซิงค์ข้อมูลเมื่อมีการอัปเดตแจ้งเตือนจากหน้าอื่น
  useEffect(() => {
    const handleUpdate = () => {
      if (open) {
        loadRecentNotifications();
      }
    };
    window.addEventListener("notifications-updated", handleUpdate);
    return () => window.removeEventListener("notifications-updated", handleUpdate);
  }, [open, loadRecentNotifications]);

  const markReadAndNavigate = async (notification) => {
    if (!notification.read && notification.id) {
      const token = localStorage.getItem("token");
      await fetch(`${API_BASE_URL}/notifications/${notification.id}/read`, {
        method: "PATCH",
        credentials: "include",
        headers: token ? { Authorization: `Bearer ${token}` } : {},
      }).catch(() => {});
      window.dispatchEvent(new Event("notifications-updated"));
    }

    setOpen(false);

    const refId = notification.referenceId;
    const refType = notification.referenceType;

    // ถ้าเป็นการแจ้งเตือนคอมเมนต์ นำทางไปที่หน้ารายละเอียดนิยายพร้อมเลื่อนไปที่ส่วนคอมเมนต์
    if (notification.type === "comment" && refId) {
      navigate(`/novel/${refId}#comments`);
      return;
    }

    if (refType === "novel" && refId) {
      navigate(`/novel/${refId}`);
      return;
    }

    if (refType === "chapter" && refId) {
      navigate(`/novel/${refId}`);
      return;
    }

    if (refType === "user" && refId) {
      navigate(`/writer/${refId}/profile`);
      return;
    }

    if (notification.type === "follower" && (refId || notification.actorId)) {
      navigate(`/writer/${refId || notification.actorId}/profile`);
      return;
    }

    if (refId) {
      navigate(`/novel/${refId}`);
    }
  };

  const handleAvatarError = (id) => {
    setFailedAvatars((prev) => new Set(prev).add(id));
  };

  return (
    <div className="notification-dropdown" ref={dropdownRef}>
      <button
        type="button"
        className="navbar__notification-btn"
        onClick={() => setOpen((previous) => !previous)}
        aria-label="การแจ้งเตือน"
        aria-expanded={open}
        aria-haspopup="menu"
      >
        <Bell size={20} strokeWidth={2.2} />
        {unreadCount > 0 && (
          <span className="navbar__notification-badge">
            {unreadCount > 99 ? "99+" : unreadCount}
          </span>
        )}
      </button>

      {open && (
        <div className="notification-dropdown__panel" role="menu" aria-label="การแจ้งเตือนล่าสุด">
          <div className="notification-dropdown__header">
            <div>
              <span className="notification-dropdown__eyebrow">อัปเดตล่าสุด</span>
              <h2>การแจ้งเตือน</h2>
            </div>
            {unreadCount > 0 && <span className="notification-dropdown__count">{unreadCount} ใหม่</span>}
          </div>

          <div className="notification-dropdown__list">
            {loading && items.length === 0 ? (
              <div style={{ padding: "12px 16px", display: "flex", flexDirection: "column", gap: "12px" }}>
                {Array.from({ length: 3 }).map((_, idx) => (
                  <div key={idx} style={{ display: "flex", gap: "10px", alignItems: "center" }}>
                    <Skeleton variant="circular" width="36px" height="36px" />
                    <div style={{ flex: 1, display: "flex", flexDirection: "column", gap: "6px" }}>
                      <Skeleton width="50%" height="13px" />
                      <Skeleton width="80%" height="11px" />
                    </div>
                  </div>
                ))}
              </div>
            ) : items.length === 0 ? (
              <div className="notification-dropdown__state">
                <Bell size={22} />
                ยังไม่มีการแจ้งเตือน
              </div>
            ) : (
              items.map((notification) => {
                const hasCustomPhoto = notification.actorAvatar && !failedAvatars.has(notification.id);

                return (
                  <button
                    type="button"
                    role="menuitem"
                    className={`notification-dropdown__item ${notification.read ? "" : "is-unread"}`}
                    key={notification.id}
                    onClick={() => markReadAndNavigate(notification)}
                  >
                    {notification.isSystem ? (
                      <span className="notification-dropdown__avatar notification-dropdown__avatar--system" title="StoryVerse">
                        <img src="/logo192.png" alt="StoryVerse" className="notification-dropdown__logo-img" />
                      </span>
                    ) : hasCustomPhoto ? (
                      <span className="notification-dropdown__avatar">
                        <img
                          src={notification.actorAvatar}
                          alt={notification.actorName}
                          className="notification-dropdown__avatar-img"
                          onError={() => handleAvatarError(notification.id)}
                        />
                      </span>
                    ) : (
                      <span
                        className="notification-dropdown__avatar"
                        style={{ backgroundColor: getAvatarColor(notification.actorName) }}
                      >
                        {notification.actorName.charAt(0).toUpperCase()}
                      </span>
                    )}

                    <span className="notification-dropdown__copy">
                      <span className="notification-dropdown__meta-row">
                        <strong title={notification.actorName}>{notification.actorName}</strong>
                        <span className="notification-dropdown__tag">{notification.typeLabel}</span>
                      </span>

                      {notification.type === "comment" ? (
                        <>
                          <span className="notification-dropdown__title" title={`เรื่อง : ${notification.title}`}>
                            เรื่อง : {notification.title}
                          </span>
                          {notification.body && (
                            <small title={`แสดงความคิดเห็นว่า : ${notification.body}`}>
                              แสดงความคิดเห็นว่า : {notification.body}
                            </small>
                          )}
                        </>
                      ) : (
                        <>
                          <span className="notification-dropdown__title">{notification.title}</span>
                          {notification.body && <small>{notification.body}</small>}
                        </>
                      )}

                      <time>{formatTime(notification.createdAt)}</time>
                    </span>

                    {!notification.read && <span className="notification-dropdown__dot" aria-label="ยังไม่ได้อ่าน" />}
                  </button>
                );
              })
            )}
          </div>

          <button
            type="button"
            className="notification-dropdown__all-button"
            onClick={() => {
              setOpen(false);
              navigate("/notifications");
            }}
          >
            ดูการแจ้งเตือนทั้งหมด <ChevronRight size={16} />
          </button>
        </div>
      )}
    </div>
  );
}

import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "./NovelCard.css";
import { getNovelStatusInfo } from "../../utils/novelStatus";

/**
 * NovelCard — การ์ดนิยายมาตรฐาน
 *
 * ขนาด cover จะสม่ำเสมอทุกหน้า เพราะใช้ aspect-ratio: 2/3
 * ความสูงของ cover = column width × (3/2) โดยอัตโนมัติ
 *
 * ✅ วิธีใช้งานใน grid — ต้องเหมือนกันทุกหน้าเพื่อให้การ์ดดูสม่ำเสมอ:
 *
 *   <div style={{
 *     display: "grid",
 *     gridTemplateColumns: "repeat(auto-fill, minmax(180px, 1fr))",
 *     gap: "20px",
 *   }}>
 *     {novels.map(n => <NovelCard key={n.id} novel={n} onClick={...} />)}
 *   </div>
 *
 * Props:
 *   novel  — object (required)
 *   onClick — function (optional)
 */
const NovelCard = ({ novel, onClick, showLike = true }) => {
  const navigate = useNavigate();
  const [liked, setLiked] = useState(novel?.isLiked || false);
  const authorId = novel?.author?.id || novel?.author_id || novel?.author?.writer_id || novel?.author?.user_id;

  const handleAuthorClick = (e) => {
    if (authorId) {
      e.stopPropagation();
      navigate(`/writer/profile/${authorId}`);
    }
  };

  const authorDisplayName =
    novel?.author?.penName ||
    novel?.author?.pen_name ||
    novel?.author?.displayName ||
    novel?.author?.name ||
    novel?.pen_name ||
    novel?.penName ||
    novel?.author_name ||
    novel?.authorName ||
    "ไม่ระบุ";

  // รองรับ field name หลายรูปแบบจาก API
  const views = novel?.views ?? novel?.view_count ?? novel?.stats?.views ?? 0;
  const likes = novel?.like_count ?? novel?.total_likes ?? novel?.stats?.likes ?? 0;
  const bookmarks = novel?.bookshelf_count ?? novel?.bookmark_count ?? novel?.total_bookmarks ?? novel?.stats?.bookmarks ?? 0;

  const fmt = (v = 0) =>
    v >= 1_000_000 ? `${(v / 1_000_000).toFixed(1)}M`
      : v >= 1_000 ? `${(v / 1_000).toFixed(1)}K`
        : String(v);

  const statusInfo = getNovelStatusInfo(novel);
  const shouldShowBadge = statusInfo.isCompleted;

  const handleLike = (e) => {
    e.stopPropagation();
    setLiked(p => !p);
    // TODO: POST /api/novels/:id/like
  };

  const handleKey = (e) => {
    if (e.key === "Enter" || e.key === " ") onClick?.();
  };

  return (
    <article
      className="novel-card"
      onClick={onClick}
      onKeyDown={handleKey}
      role="button"
      tabIndex={0}
      aria-label={`อ่านนิยาย ${novel.title}`}
    >

      {/* ── Cover ── */}
      <div
        className="novel-card__cover"
        style={{ background: novel.coverBg || "var(--pink-50, #fdf2f8)" }}
      >
        {novel.coverImage
          ? (
            <img
              src={novel.coverImage}
              alt={novel.title}
              className="novel-card__cover-img"
              loading="lazy"
            />
          ) : (
            <span className="novel-card__cover-emoji" aria-hidden="true">
              {novel.coverEmoji || "📘"}
            </span>
          )
        }

        {shouldShowBadge && (
          <span className={`novel-card__status novel-card__status--${statusInfo.variant || "completed"}`}>
            {statusInfo.badgeLabel}
          </span>
        )}
      </div>

      {/* ── Body ── */}
      <div className="novel-card__body">

        {/* Categories */}
        <div className="novel-card__categories">
          {(novel.categories || []).slice(0, 2).map((cat, i) => (
            <span key={i} className="novel-card__tag">{typeof cat === "object" ? cat.name : cat}</span>
          ))}
        </div>

        {/* Title (clamp 2 lines) */}
        <h3 className="novel-card__title">{novel.title}</h3>

        {/* Synopsis (clamp 2 lines) */}
        {novel.synopsis && (
          <p className="novel-card__synopsis">
            {novel.synopsis || "\u00A0"}
          </p>
        )}

        {/* Stats */}
        <div className="novel-card__stats-bar">
          <div className="novel-card__stat">
            <div className="novel-card__stat-value">{fmt(views)}</div>
            <div className="novel-card__stat-label">ยอดชม</div>
          </div>
          <div className="novel-card__stat">
            <div className="novel-card__stat-value">{fmt(likes)}</div>
            <div className="novel-card__stat-label">ถูกใจ</div>
          </div>
          <div className="novel-card__stat">
            <div className="novel-card__stat-value">{fmt(bookmarks)}</div>
            <div className="novel-card__stat-label">ชั้นหนังสือ</div>
          </div>
        </div>

        {/* Footer */}
        <div className="novel-card__footer">
          <div className="novel-card__author">
            <span className="novel-card__author-avatar" aria-hidden="true">
              {novel.author?.avatarEmoji || "✍️"}
            </span>
            <span className="novel-card__author-name">
              {authorDisplayName}
            </span>
          </div>

          {showLike && (
            <button
              className={`novel-card__like-btn ${liked ? "novel-card__like-btn--on" : ""}`}
              onClick={handleLike}
              aria-label={liked ? "ยกเลิกถูกใจ" : "กดถูกใจ"}
              aria-pressed={liked}
            >
              <svg width="14" height="14" viewBox="0 0 14 14" fill="none" aria-hidden="true">
                <path
                  d="M7 12S2 8.5 2 5.5A2.5 2.5 0 017 4a2.5 2.5 0 015 1.5C12 8.5 7 12 7 12z"
                  stroke="currentColor"
                  strokeWidth="1.4"
                  fill={liked ? "currentColor" : "none"}
                />
              </svg>
            </button>
          )}
        </div>

      </div>
    </article>
  );
};

export default NovelCard;

