import React from "react";
import "./StatBadge.css";

/**
 * StatBadge — แสดงตัวเลขสถิติ (ยอดอ่าน, เส้นทาง, จุดเลือก, ตอนจบ)
 * @param {string|number} value - ค่าตัวเลข
 * @param {string} label - ป้ายกำกับ
 */
const StatBadge = ({ value, label }) => {
  // Format large numbers (e.g. 5900 → 5.9K)
  const formatValue = (val) => {
    if (typeof val === "number") {
      if (val >= 1000) return `${(val / 1000).toFixed(1)}K`;
    }
    return val;
  };

  return (
    <div className="stat-badge" role="figure" aria-label={`${label}: ${value}`}>
      <span className="stat-badge__value">{formatValue(value)}</span>
      <span className="stat-badge__label">{label}</span>
    </div>
  );
};

export default StatBadge;

// src/components/Toggle/Toggle.jsx
import React from "react";
import "./Toggle.css";

/**
 * Toggle — สวิตช์ on/off
 * @param {boolean}  checked   - สถานะ
 * @param {function} onChange  - callback(newValue)
 * @param {string}   label     - ป้ายกำกับ (optional)
 * @param {string}   id        - id สำหรับ accessibility
 */
const Toggle = ({ checked = false, onChange, label, id, disabled = false }) => {
  const handleClick = () => {
    if (disabled) return;
    onChange?.(!checked);
  };

  return (
    <label className="toggle-wrap" htmlFor={id}>
      <button
        id={id}
        type="button"
        role="switch"
        aria-checked={checked}
        aria-disabled={disabled}
        aria-label={label}
        disabled={disabled}
        className={`toggle ${checked ? "toggle--on" : "toggle--off"} ${disabled ? "toggle--disabled" : ""}`}
        onClick={handleClick}
      >
        <span className="toggle__thumb" />
      </button>
      {label ? (
        <span className={`toggle__label ${checked ? "toggle__label--on" : ""}`}>
          {label}
        </span>
      ) : null}
    </label>
  );
};

export default Toggle;

