const THAI_MONTHS_SHORT = [
  "ม.ค.", "ก.พ.", "มี.ค.", "เม.ย.", "พ.ค.", "มิ.ย.",
  "ก.ค.", "ส.ค.", "ก.ย.", "ต.ค.", "พ.ย.", "ธ.ค."
];

const THAI_MONTHS_FULL = [
  "มกราคม", "กุมภาพันธ์", "มีนาคม", "เมษายน", "พฤษภาคม", "มิถุนายน",
  "กรกฎาคม", "สิงหาคม", "กันยายน", "ตุลาคม", "พฤศจิกายน", "ธันวาคม"
];

// แปลงเป็นวันที่แบบย่อไทย เช่น 22 ส.ค. 2569 15:30 น.
const formatShortThaiDateTime = (dateString) => {
  if (!dateString) return "-";
  try {
    const d = new Date(dateString);
    if (isNaN(d.getTime())) return dateString;
    const day = d.getDate();
    const month = THAI_MONTHS_SHORT[d.getMonth()];
    const year = d.getFullYear() + 543;
    const hours = String(d.getHours()).padStart(2, "0");
    const minutes = String(d.getMinutes()).padStart(2, "0");
    return `${day} ${month} ${year} ${hours}:${minutes} น.`;
  } catch {
    return dateString;
  }
};

// แปลงเป็นวันที่แบบเต็มไทย เช่น 22 สิงหาคม 2569 15:30:00 น.
const formatFullThaiDateTime = (dateString) => {
  if (!dateString) return "-";
  try {
    const d = new Date(dateString);
    if (isNaN(d.getTime())) return dateString;
    const day = d.getDate();
    const month = THAI_MONTHS_FULL[d.getMonth()];
    const year = d.getFullYear() + 543;
    const hours = String(d.getHours()).padStart(2, "0");
    const minutes = String(d.getMinutes()).padStart(2, "0");
    const seconds = String(d.getSeconds()).padStart(2, "0");
    return `${day} ${month} ${year} ${hours}:${minutes}:${seconds} น.`;
  } catch {
    return dateString;
  }
};

// แปลงค่า Value ให้อ่านง่ายเป็นภาษาไทย
const formatMetadataValue = (key, val, allMetadata = {}) => {
  if (val === null || val === undefined || (typeof val === "string" && val.trim() === "")) return "-";
  if (typeof val === "boolean") return val ? "ใช่" : "ไม่ใช่";
  // choices_diff เป็น object สรุปจำนวนตัวเลือกที่สร้าง/แก้/ลบตอนแก้ไขฉาก
  // (มาจาก SyncSceneChoices) แสดงเป็นข้อความไทยแทนการโชว์ JSON ดิบให้แอดมินอ่านเอง
  if (key === "choices_diff" && typeof val === "object") {
    const { created_count = 0, updated_count = 0, deleted_count = 0 } = val;
    const parts = [];
    if (created_count > 0) parts.push(`สร้างใหม่ ${created_count} รายการ`);
    if (updated_count > 0) parts.push(`แก้ไข ${updated_count} รายการ`);
    if (deleted_count > 0) parts.push(`ลบ ${deleted_count} รายการ`);
    return parts.length > 0 ? parts.join(", ") : "ไม่มีการเปลี่ยนแปลง";
  }
  if (typeof val === "object") {
    try {
      return JSON.stringify(val);
    } catch {
      return String(val);
    }
  }

  // ถ้าเป็น novel_id และมี novel_title ให้แสดงคู่กัน
  if (key === "novel_id" && allMetadata.novel_title) {
    return `${allMetadata.novel_title} (รหัส: ${val})`;
  }
  // ถ้าเป็น chapter_id และมี chapter_title ให้แสดงคู่กัน
  if (key === "chapter_id" && allMetadata.chapter_title) {
    return `${allMetadata.chapter_title} (รหัส: ${val})`;
  }

  const strVal = String(val).trim();
  const lowerVal = strVal.toLowerCase();

  if (VALUE_MAP[lowerVal]) {
    return VALUE_MAP[lowerVal];
  }

  return strVal;
};

// แสดงชื่อผู้กระทำ เช่น แอดมิน (admin_user) หรือ แอดมิน #5 หรือ ระบบ
const renderActorName = (actorUserId, actorRole, actorUsername) => {
  if (!actorUserId) return "ระบบ";
  const roleName = ROLE_MAP[actorRole?.toLowerCase()] || actorRole || "ผู้ใช้";
  if (actorUsername && actorUsername.trim() !== "") {
    return `${roleName} (${actorUsername})`;
  }
  return `${roleName} #${actorUserId}`;
};

// แสดงเป้าหมาย เช่น นิยาย (ชื่อเรื่อง) หรือ นิยาย #88
const renderTargetName = (targetType, targetId, targetName) => {
  if (!targetType && !targetId) return "-";
  const typeLabel = TARGET_TYPE_MAP[targetType?.toLowerCase()] || targetType || "เป้าหมาย";
  if (targetName && targetName.trim() !== "") {
    return `${typeLabel} (${targetName})`;
  }
  if (targetId !== null && targetId !== undefined && targetId !== "") {
    return `${typeLabel} #${targetId}`;
  }
  return typeLabel;
};

// แสดง Badge สถานะ (SUCCESS = เขียว, FAILURE = แดง, อื่นๆ = ส้ม/เทา)
const renderStatusBadge = (status) => {
  const upper = (status || "").toUpperCase();
  if (upper === "SUCCESS") {
    return (
      <span className="admin-audit-status-badge admin-audit-status-badge--success">
        <CheckCircle2 size={13} />
        <span>สำเร็จ</span>
      </span>
    );
  }
  if (upper === "FAILURE" || upper === "FAILED" || upper === "ERROR") {
    return (
      <span className="admin-audit-status-badge admin-audit-status-badge--failure">
        <AlertCircle size={13} />
        <span>ไม่สำเร็จ</span>
      </span>
    );
  }
  return (
    <span className="admin-audit-status-badge admin-audit-status-badge--other">
      {status || "-"}
    </span>
  );
};

// =========================================================================
// 3. Main Adminauditlog Component
// =========================================================================

export default function Adminauditlog() {
  // Main Data States
  const [logs, setLogs] = useState([]);
  const [allLogs, setAllLogs] = useState([]);
  const [logView, setLogView] = useState("all"); // "all" | "content" | "security"
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [accessDenied, setAccessDenied] = useState(false);
  const [metadata, setMetadata] = useState({ actions: [], target_types: [], statuses: [] });
  const [autoRefresh, setAutoRefresh] = useState(false);
  const [isExportingCSV, setIsExportingCSV] = useState(false);
  const [isExportingExcel, setIsExportingExcel] = useState(false);

  // Pagination States
  const [page, setPage] = useState(1);
  const [limit, setLimit] = useState(20);

  // Filter States
  const [actionFilter, setActionFilter] = useState("");
  const [actorUserIdInput, setActorUserIdInput] = useState("");
  const [actorUserIdFilter, setActorUserIdFilter] = useState("");
  const [targetTypeFilter, setTargetTypeFilter] = useState("");
  const [statusFilter, setStatusFilter] = useState("");
  const [dateFromFilter, setDateFromFilter] = useState("");
  const [dateToFilter, setDateToFilter] = useState("");
  const [filterValidationMsg, setFilterValidationMsg] = useState("");

  // Debounce Actor User ID Input (400ms)
  useEffect(() => {
    const timer = setTimeout(() => {
      setActorUserIdFilter(actorUserIdInput.trim());
      setPage(1);
    }, 400);
    return () => clearTimeout(timer);
  }, [actorUserIdInput]);

  // Mobile Filter Drawer State
  const [isMobileFilterOpen, setIsMobileFilterOpen] = useState(false);
  // ซ่อน/แสดงกลุ่มตัวกรองที่ใช้ไม่บ่อย (การกระทำแบบละเอียด, ประเภทเป้าหมาย, สถานะ)
  // เพื่อลดความรกของแถบเครื่องมือ — ค่าเริ่มต้นเปิดอัตโนมัติถ้ามีการเลือกฟิลเตอร์กลุ่มนี้ไว้อยู่แล้ว (เช่น มาจาก URL หรือรีเฟรชหน้า)
  const [showAdvancedFilters, setShowAdvancedFilters] = useState(false);
  // เปิด/ปิดเมนู dropdown ของปุ่ม "ส่งออก" ที่รวม CSV + Excel ไว้ในปุ่มเดียว
  const [isExportMenuOpen, setIsExportMenuOpen] = useState(false);

  // Detail Modal States
  const [selectedLogId, setSelectedLogId] = useState(null);
  const [detailModalOpen, setDetailModalOpen] = useState(false);
  const [detailData, setDetailData] = useState(null);
  const [detailLoading, setDetailLoading] = useState(false);
  const [detailError, setDetailError] = useState("");

  // ตรวจสอบว่ามี Filter ที่กำลังใช้งานอยู่หรือไม่
  const hasActiveFilters = Boolean(
    actionFilter ||
    actorUserIdInput ||
    targetTypeFilter ||
    statusFilter ||
    dateFromFilter ||
    dateToFilter
  );

  // นับจำนวนตัวกรอง "ขั้นสูง" (การกระทำ, ประเภทเป้าหมาย, สถานะ) ที่กำลังใช้งานอยู่
  // ใช้โชว์เป็นตัวเลขบนปุ่ม "ตัวกรองเพิ่มเติม" เพื่อให้รู้ทันทีว่ามีฟิลเตอร์ซ่อนอยู่กี่ตัวโดยไม่ต้องกดเปิดดู
  const advancedFilterCount = [actionFilter, targetTypeFilter, statusFilter].filter(Boolean).length;

  // ถ้าหน้าโหลดมาพร้อมตัวกรองขั้นสูงที่ถูกตั้งค่าไว้แล้ว (เช่น รีเฟรชหน้าค้าง filter เดิม)
  // ให้เปิด panel นี้ให้อัตโนมัติ ผู้ใช้จะได้ไม่งงว่าทำไมผลลัพธ์ถูกกรองอยู่ทั้งที่มองไม่เห็นตัวกรอง
  useEffect(() => {
    if (advancedFilterCount > 0) {
      setShowAdvancedFilters(true);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // action กลุ่ม "security" (เข้า/ออกระบบ, สมัครสมาชิก, พยายามเข้าถึงโดยไม่มีสิทธิ์) — ใช้แยกออกจาก content activity
  const SECURITY_ACTIONS = useMemo(
    () => new Set(["LOGIN", "LOGOUT", "LOGIN_FAILED", "UNAUTHORIZED_ACCESS", "REGISTER", "SUSPEND_OWN_ACCOUNT"]),
    []
  );

  // Helper: ดึงรายการ log ทั้งหมดตามตัวกรองปัจจุบันเพื่อใช้แยกแยะจำนวนและกรอง client-side แบบข้ามทุกหน้า
  const fetchAllLogsForCurrentFilters = useCallback(async () => {
    const token = localStorage.getItem("token");
    if (!token) return [];

    let allItems = [];
    let currentPage = 1;
    let hasMore = true;

    while (hasMore && allItems.length < 5000) {
      const params = new URLSearchParams();
      params.set("page", String(currentPage));
      params.set("limit", "100");
      if (actionFilter) params.set("action", actionFilter);
      if (actorUserIdFilter) params.set("actor", actorUserIdFilter);
      if (targetTypeFilter) params.set("target_type", targetTypeFilter);
      if (statusFilter) params.set("status", statusFilter);
      if (dateFromFilter) params.set("date_from", new Date(dateFromFilter).toISOString());
      if (dateToFilter) params.set("date_to", new Date(dateToFilter).toISOString());

      const res = await fetch(`${API_BASE_URL}/api/admin/audit-logs?${params.toString()}`, {
        headers: { Authorization: `Bearer ${token}` },
      }).catch(() => null);

      if (!res || !res.ok) break;

      const json = await res.json().catch(() => null);
      const pageItems = json?.data?.items || [];
      const totalItems = json?.data?.total || pageItems.length;

      allItems = [...allItems, ...pageItems];
      if (allItems.length >= totalItems || pageItems.length === 0) {
        hasMore = false;
      } else {
        currentPage++;
      }
    }
    return allItems;
  }, [actionFilter, actorUserIdFilter, targetTypeFilter, statusFilter, dateFromFilter, dateToFilter]);

  // คำนวณชุดข้อมูลเมื่อมีการสลับมุมมอง "ทั้งหมด" / "เนื้อหา" / "security"
  const activeDataset = useMemo(() => {
    const source = allLogs.length > 0 ? allLogs : logs;
    if (logView === "content") {
      return source.filter((l) => !SECURITY_ACTIONS.has(l.action));
    }
    if (logView === "security") {
      return source.filter((l) => SECURITY_ACTIONS.has(l.action));
    }
    return null; // "all"
  }, [logView, allLogs, logs, SECURITY_ACTIONS]);

  const displayTotal = useMemo(() => {
    if (logView === "all") return total;
    return activeDataset ? activeDataset.length : 0;
  }, [logView, total, activeDataset]);

  const displayTotalPages = useMemo(() => {
    return Math.ceil(displayTotal / limit) || 1;
  }, [displayTotal, limit]);

  const visibleLogs = useMemo(() => {
    if (logView === "all") return logs;
    if (!activeDataset) return [];
    const start = (page - 1) * limit;
    return activeDataset.slice(start, start + limit);
  }, [logView, logs, activeDataset, page, limit]);

  const allCount = total || (allLogs.length > 0 ? allLogs.length : logs.length);

  const contentCount = useMemo(() => {
    const source = allLogs.length > 0 ? allLogs : logs;
    return source.filter((l) => !SECURITY_ACTIONS.has(l.action)).length;
  }, [allLogs, logs, SECURITY_ACTIONS]);

  const securityCount = useMemo(() => {
    const source = allLogs.length > 0 ? allLogs : logs;
    return source.filter((l) => SECURITY_ACTIONS.has(l.action)).length;
  }, [allLogs, logs, SECURITY_ACTIONS]);

  const handleLogViewChange = (newView) => {
    setLogView(newView);
    setPage(1);
  };

  // 🟢 Fetch List Audit Logs
  const fetchAuditLogs = useCallback(async (isSilent = false) => {
    // Validate filters before calling API
    setFilterValidationMsg("");
    setError("");

    if (dateFromFilter && dateToFilter) {
      const fromD = new Date(dateFromFilter);
      const toD = new Date(dateToFilter);
      if (fromD >= toD) {
        setFilterValidationMsg("วันที่เริ่มต้นต้องมาก่อนวันที่สิ้นสุด");
        return;
      }
    }

    const token = localStorage.getItem("token");
    if (!token) {
      window.location.href = "/login-register";
      return;
    }

    if (!isSilent) setLoading(true);

    try {
      const params = new URLSearchParams();
      params.set("page", String(page));
      params.set("limit", String(limit));

      if (actionFilter) params.set("action", actionFilter);
      if (actorUserIdFilter) params.set("actor", actorUserIdFilter);
      if (targetTypeFilter) params.set("target_type", targetTypeFilter);
      if (statusFilter) params.set("status", statusFilter);

      if (dateFromFilter) {
        const isoFrom = new Date(dateFromFilter).toISOString();
        params.set("date_from", isoFrom);
      }
      if (dateToFilter) {
        const isoTo = new Date(dateToFilter).toISOString();
        params.set("date_to", isoTo);
      }

      const res = await fetch(`${API_BASE_URL}/api/admin/audit-logs?${params.toString()}`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (res.status === 401) {
        localStorage.removeItem("token");
        window.location.href = "/login-register";
        return;
      }

      if (res.status === 403) {
        setAccessDenied(true);
        setLoading(false);
        return;
      }

      const text = await res.text();
      let resJson;
      try {
        resJson = JSON.parse(text);
      } catch {
        throw new Error(text || "เกิดข้อผิดพลาด กรุณาลองใหม่อีกครั้ง");
      }

      if (!res.ok) {
        const rawMsg = (typeof resJson?.error === "object" ? resJson.error?.message : resJson?.error) || resJson?.message || "";
        const thaiMsg = ERROR_MESSAGE_MAP[rawMsg] || rawMsg || "เกิดข้อผิดพลาด กรุณาลองใหม่อีกครั้ง";
        throw new Error(thaiMsg);
      }

      const data = resJson.data || {};
      const pageItems = data.items || [];
      setLogs(pageItems);
      setTotal(data.total || 0);

      // ดึงชุดข้อมูลเต็มแบบ async เบื้องหลังเพื่อคำนวณสถิติจำนวนรวมและการกรองแยกมุมมองได้ครบทุกหน้า
      fetchAllLogsForCurrentFilters().then((fetchedAll) => {
        if (fetchedAll && fetchedAll.length > 0) {
          setAllLogs(fetchedAll);
        } else {
          setAllLogs(pageItems);
        }
      });
    } catch (err) {
      console.error("Fetch audit logs error:", err);
      setError(err.message || "เกิดข้อผิดพลาด กรุณาลองใหม่อีกครั้ง");
    } finally {
      setLoading(false);
    }
  }, [page, limit, actionFilter, actorUserIdFilter, targetTypeFilter, statusFilter, dateFromFilter, dateToFilter, fetchAllLogsForCurrentFilters]);

  // จุดที่ 6: Auto-refresh / Polling ทุก 30 วินาที
  useEffect(() => {
    if (!autoRefresh) return;
    const interval = setInterval(() => {
      fetchAuditLogs(true);
    }, 30000);
    return () => clearInterval(interval);
  }, [autoRefresh, fetchAuditLogs]);

  // 🟢 Fetch Filter Metadata
  const fetchMetadata = useCallback(async () => {
    const token = localStorage.getItem("token");
    if (!token) return;
    try {
      const res = await fetch(`${API_BASE_URL}/api/admin/audit-logs/metadata`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (res.ok) {
        const json = await res.json();
        if (json.data) {
          setMetadata(json.data);
        }
      }
    } catch (err) {
      console.error("Fetch audit metadata error:", err);
    }
  }, []);

  useEffect(() => {
    fetchMetadata();
  }, [fetchMetadata]);

  // Initial and reactive fetch
  useEffect(() => {
    fetchAuditLogs();
  }, [fetchAuditLogs]);

  // Helper: ดึงข้อมูลทั้งหมดตามตัวกรองที่เลือกไว้ (ดึงทีละ 100 รายการจนครบ)
  const fetchFilteredLogsForExport = async () => {
    const token = localStorage.getItem("token");
    if (!token) {
      window.location.href = "/login-register";
      return null;
    }

    let allItems = [];
    let currentPage = 1;
    let hasMore = true;

    while (hasMore && allItems.length < 5000) {
      const params = new URLSearchParams();
      params.set("page", String(currentPage));
      params.set("limit", "100");
      if (actionFilter) params.set("action", actionFilter);
      if (actorUserIdFilter) params.set("actor", actorUserIdFilter);
      if (targetTypeFilter) params.set("target_type", targetTypeFilter);
      if (statusFilter) params.set("status", statusFilter);
      if (dateFromFilter) params.set("date_from", new Date(dateFromFilter).toISOString());
      if (dateToFilter) params.set("date_to", new Date(dateToFilter).toISOString());

      const res = await fetch(`${API_BASE_URL}/api/admin/audit-logs?${params.toString()}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!res.ok) throw new Error("ไม่สามารถดึงข้อมูลเพื่อส่งออกได้");

      const json = await res.json();
      const pageItems = json.data?.items || [];
      const totalItems = json.data?.total || pageItems.length;

      allItems = [...allItems, ...pageItems];
      if (allItems.length >= totalItems || pageItems.length === 0) {
        hasMore = false;
      } else {
        currentPage++;
      }
    }

    return allItems.length > 0 ? allItems : logs;
  };

  // 1. Export CSV (พร้อม BOM UTF-8 สำหรับภาษาไทย)
  const handleExportCSV = async () => {
    setIsExportingCSV(true);
    try {
      const items = await fetchFilteredLogsForExport();
      if (!items) return;

      const headers = ["รหัสรายการ", "เวลา", "ผู้กระทำ", "การกระทำ", "เป้าหมาย", "สถานะ", "ไอพี"];
      const csvRows = [headers.join(",")];

      items.forEach((item) => {
        const timeStr = `"${formatFullThaiDateTime(item.created_at)}"`;
        const actorStr = `"${renderActorName(item.actor_user_id, item.actor_role, item.actor_username)}"`;
        const actionStr = `"${ACTION_MAP[item.action]?.label || item.action}"`;
        const targetStr = `"${renderTargetName(item.target_type, item.target_id, item.target_name)}"`;
        const statusStr = `"${item.status === "SUCCESS" ? "สำเร็จ" : (item.status === "FAILURE" ? "ไม่สำเร็จ" : item.status || "-")}"`;
        const ipStr = `"${item.ip_address || "-"}"`;

        csvRows.push([item.log_id, timeStr, actorStr, actionStr, targetStr, statusStr, ipStr].join(","));
      });

      // ใส่ \uFEFF (UTF-8 BOM) เพื่อให้ Microsoft Excel และ WPS Office รองรับภาษาไทยได้สมบูรณ์
      const blob = new Blob(["\uFEFF" + csvRows.join("\r\n")], { type: "text/csv;charset=utf-8;" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.setAttribute("download", `audit_logs_${new Date().toISOString().slice(0, 10)}.csv`);
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
    } catch (err) {
      console.error("Export CSV error:", err);
      alert(err.message || "เกิดข้อผิดพลาดในการส่งออกไฟล์ CSV");
    } finally {
      setIsExportingCSV(false);
    }
  };

  // 2. Export Excel (.xlsx) ด้วย ExcelJS พร้อม formatting, column widths, wrap text, auto-filter, freeze header
  const handleExportExcel = async () => {
    setIsExportingExcel(true);
    try {
      const items = await fetchFilteredLogsForExport();
      if (!items) return;

      const workbook = new ExcelJS.Workbook();
      workbook.creator = "StoryVerse Admin";
      workbook.created = new Date();

      const worksheet = workbook.addWorksheet("ประวัติการใช้งาน", {
        views: [{ state: "frozen", xSplit: 0, ySplit: 1, activeCell: "A2" }]
      });

      // กำหนดคอลัมน์พร้อมความกว้างที่เหมาะสมและอ่านง่ายทันที
      worksheet.columns = [
        { header: "รหัสรายการ", key: "log_id", width: 14 },
        { header: "เวลา", key: "created_at", width: 28 },
        { header: "ผู้กระทำ", key: "actor", width: 32 },
        { header: "การกระทำ", key: "action", width: 26 },
        { header: "เป้าหมาย", key: "target", width: 34 },
        { header: "สถานะ", key: "status", width: 16 },
        { header: "ไอพี", key: "ip_address", width: 18 },
      ];

      // จัดรูปแบบ Header (แถวที่ 1)
      const headerRow = worksheet.getRow(1);
      headerRow.height = 30;
      headerRow.eachCell((cell, colNumber) => {
        cell.font = {
          name: "Sarabun",
          size: 11,
          bold: true,
          color: { argb: "FFFFFFFF" }
        };
        cell.fill = {
          type: "pattern",
          pattern: "solid",
          fgColor: { argb: "FFDB2777" } // StoryVerse signature theme pink (#DB2777)
        };
        cell.alignment = {
          vertical: "middle",
          horizontal: colNumber === 1 || colNumber === 6 || colNumber === 7 ? "center" : "left",
          wrapText: true
        };
        cell.border = {
          top: { style: "thin", color: { argb: "FFBE185D" } },
          left: { style: "thin", color: { argb: "FFBE185D" } },
          bottom: { style: "medium", color: { argb: "FF9D174D" } },
          right: { style: "thin", color: { argb: "FFBE185D" } },
        };
      });

      // ใส่ข้อมูลแถว
      items.forEach((item, index) => {
        const row = worksheet.addRow({
          log_id: item.log_id,
          created_at: formatFullThaiDateTime(item.created_at),
          actor: renderActorName(item.actor_user_id, item.actor_role, item.actor_username),
          action: ACTION_MAP[item.action]?.label || item.action,
          target: renderTargetName(item.target_type, item.target_id, item.target_name),
          status: item.status === "SUCCESS" ? "สำเร็จ" : (item.status === "FAILURE" ? "ไม่สำเร็จ" : item.status || "-"),
          ip_address: item.ip_address || "-",
        });

        // จัดความสูงและจัด alignment ของแถวข้อมูล
        row.height = 26;
        const isEven = index % 2 === 1;

        row.eachCell({ includeEmpty: true }, (cell, colNumber) => {
          cell.font = {
            name: "Sarabun",
            size: 10.5,
            color: { argb: "FF1E293B" }
          };
          if (isEven) {
            cell.fill = {
              type: "pattern",
              pattern: "solid",
              fgColor: { argb: "FFFAFBFC" } // Zebra striping
            };
          }
          cell.alignment = {
            vertical: "middle",
            horizontal: colNumber === 1 || colNumber === 6 || colNumber === 7 ? "center" : "left",
            wrapText: true
          };
          cell.border = {
            top: { style: "thin", color: { argb: "FFE2E8F0" } },
            left: { style: "thin", color: { argb: "FFE2E8F0" } },
            bottom: { style: "thin", color: { argb: "FFE2E8F0" } },
            right: { style: "thin", color: { argb: "FFE2E8F0" } },
          };

          // ปรับสีตัวหนังสือสถานะ
          if (colNumber === 6) {
            if (item.status === "SUCCESS") {
              cell.font = { name: "Sarabun", size: 10.5, bold: true, color: { argb: "FF059669" } };
            } else if (item.status === "FAILURE") {
              cell.font = { name: "Sarabun", size: 10.5, bold: true, color: { argb: "FFE11D48" } };
            }
          }
        });
      });

      // เปิดใช้งาน Auto Filter ที่หัวตาราง
      worksheet.autoFilter = {
        from: { row: 1, column: 1 },
        to: { row: 1, column: 7 }
      };

      // เขียน Buffer และดาวน์โหลดไฟล์ .xlsx
      const buffer = await workbook.xlsx.writeBuffer();
      const blob = new Blob([buffer], {
        type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
      });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.setAttribute("download", `audit_logs_${new Date().toISOString().slice(0, 10)}.xlsx`);
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
    } catch (err) {
      console.error("Export Excel error:", err);
      alert(err.message || "เกิดข้อผิดพลาดในการส่งออกไฟล์ Excel (.xlsx)");
    } finally {
      setIsExportingExcel(false);
    }
  };

  // 🟢 Fetch Single Audit Log Detail
  const fetchLogDetail = async (id) => {
    setSelectedLogId(id);
    setDetailModalOpen(true);
    setDetailLoading(true);
    setDetailError("");
    setDetailData(null);

    const token = localStorage.getItem("token");
    if (!token) {
      window.location.href = "/login-register";
      return;
    }
    try {
      const res = await fetch(`${API_BASE_URL}/api/admin/audit-logs/${id}`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (res.status === 401) {
        localStorage.removeItem("token");
        window.location.href = "/login-register";
        return;
      }

      if (res.status === 403) {
        setDetailError("คุณไม่มีสิทธิ์เข้าถึงหน้านี้");
        return;
      }

      if (res.status === 404) {
        setDetailError("ไม่พบรายการนี้");
        return;
      }

      const text = await res.text();
      let resJson;
      try {
        resJson = JSON.parse(text);
      } catch {
        throw new Error("เกิดข้อผิดพลาด กรุณาลองใหม่");
      }

      if (!res.ok) {
        const rawMsg = (typeof resJson?.error === "object" ? resJson.error?.message : resJson?.error) || resJson?.message || "";
        const thaiMsg = ERROR_MESSAGE_MAP[rawMsg] || (res.status === 404 ? "ไม่พบรายการนี้" : "เกิดข้อผิดพลาด กรุณาลองใหม่");
        throw new Error(thaiMsg);
      }

      setDetailData(resJson.data);
    } catch (err) {
      console.error("Fetch log detail error:", err);
      setDetailError(err.message || "เกิดข้อผิดพลาด กรุณาลองใหม่");
    } finally {
      setDetailLoading(false);
    }
  };

  // Filter change handlers (always resets page to 1)
  const handleActionChange = (e) => {
    setActionFilter(e.target.value);
    setPage(1);
  };

  const handleActorUserIdChange = (e) => {
    setActorUserIdInput(e.target.value);
  };

  const handleTargetTypeChange = (e) => {
    setTargetTypeFilter(e.target.value);
    setPage(1);
  };

  const handleStatusChange = (e) => {
    setStatusFilter(e.target.value);
    setPage(1);
  };

  const handleDateFromChange = (e) => {
    setDateFromFilter(e.target.value);
    setPage(1);
  };

  const handleDateToChange = (e) => {
    setDateToFilter(e.target.value);
    setPage(1);
  };

  const handleClearFilters = () => {
    setActionFilter("");
    setActorUserIdInput("");
    setActorUserIdFilter("");
    setTargetTypeFilter("");
    setStatusFilter("");
    setDateFromFilter("");
    setDateToFilter("");
    setFilterValidationMsg("");
    setShowAdvancedFilters(false);
    setPage(1);
  };

  const handleLimitChange = (e) => {
    setLimit(Number(e.target.value));
    setPage(1);
  };

  // 🟢 จุดที่ 5: Handle 403 Forbidden Screen พร้อมปุ่มกลับหน้าแรก
  if (accessDenied) {
    return (
      <div className="admin-audit-container">
        <div className="admin-audit-access-denied">
          <Shield size={56} className="access-denied-icon" />
          <h2>คุณไม่มีสิทธิ์เข้าถึงหน้านี้</h2>
          <p>หน้านี้สงวนไว้สำหรับผู้ดูแลระบบ (Admin) เท่านั้น</p>
          <a href="/" className="btn-back-home" style={{ marginTop: "16px", display: "inline-flex", alignItems: "center", gap: "8px", padding: "10px 20px", borderRadius: "8px", backgroundColor: "#0284c7", color: "#ffffff", textDecoration: "none", fontWeight: "600" }}>
            <Home size={18} />
            <span>กลับสู่หน้าหลัก</span>
          </a>
        </div>
      </div>
    );
  }

  return (
    <div className="admin-audit-container">
      <div className="admin-audit-content">
        
        {/* =======================================================
            1. Header
           ======================================================= */}
        <header className="admin-audit-header">
          <div className="admin-audit-header__left">
            <div className="admin-audit-title-wrap">
              <h1 className="admin-audit-title">ประวัติการใช้งานระบบ</h1>
              <span className="admin-audit-badge-total">
                ทั้งหมด {total.toLocaleString()} รายการ
              </span>
            </div>
            <p className="admin-audit-subtitle">ตรวจสอบและติดตามกิจกรรมต่าง ๆ ที่เกิดขึ้นภายในระบบ</p>
            <svg className="header-branch-accent" viewBox="0 0 200 16" preserveAspectRatio="none" aria-hidden="true">
              <path d="M0 8 H70 M70 8 C 78 8, 78 2, 86 2 H130 M70 8 C 78 8, 78 14, 86 14 H130 M130 2 H200 M130 14 H160" />
            </svg>
          </div>
          <div className="admin-audit-header__actions">
            {/* ปุ่ม "ส่งออก" เดียว รวม CSV + Excel ไว้เป็นเมนู dropdown
                แทนที่จะโชว์ 2 ปุ่มแยกกันเต็มพื้นที่แถวบนสุด ลดความรกของ toolbar */}
            <div className="admin-audit-export-group">
              <button
                type="button"
                className="admin-audit-btn admin-audit-btn--export"
                onClick={() => setIsExportMenuOpen((open) => !open)}
                disabled={isExportingExcel || isExportingCSV || loading}
                aria-haspopup="true"
                aria-expanded={isExportMenuOpen}
                title="ส่งออกรายการ Log เป็นไฟล์"
              >
                <Download size={15} className={(isExportingCSV || isExportingExcel) ? "spin" : ""} />
                <span>
                  {isExportingCSV ? "กำลังส่งออก CSV..." : isExportingExcel ? "กำลังส่งออก Excel..." : "ส่งออก"}
                </span>
              </button>

              {isExportMenuOpen && (
                <>
                  {/* คลิกนอกเมนูเพื่อปิด */}
                  <div
                    className="admin-audit-export-menu-backdrop"
                    onClick={() => setIsExportMenuOpen(false)}
                  />
                  <div className="admin-audit-export-menu" role="menu">
                    <button
                      type="button"
                      role="menuitem"
                      className="admin-audit-export-menu-item"
                      onClick={() => {
                        setIsExportMenuOpen(false);
                        handleExportCSV();
                      }}
                      disabled={isExportingExcel || isExportingCSV || loading}
                    >
                      <FileText size={14} />
                      <span>ไฟล์ CSV</span>
                    </button>
                    <button
                      type="button"
                      role="menuitem"
                      className="admin-audit-export-menu-item"
                      onClick={() => {
                        setIsExportMenuOpen(false);
                        handleExportExcel();
                      }}
                      disabled={isExportingExcel || isExportingCSV || loading}
                    >
                      <FileSpreadsheet size={14} />
                      <span>ไฟล์ Excel (.xlsx)</span>
                    </button>
                  </div>
                </>
              )}
            </div>

            {/* Refresh Button (Ghost / Light Neutral) */}
            <button
              type="button"
              className="admin-audit-btn admin-audit-btn--refresh"
              onClick={() => fetchAuditLogs()}
              disabled={loading}
              title="รีเฟรชข้อมูลปัจจุบัน"
            >
              <RotateCw size={15} className={loading ? "spin" : ""} />
              <span>รีเฟรช</span>
            </button>
          </div>
        </header>

        {/* =======================================================
            1.5 Quick View Toggle — ซ่อน login/logout ที่ท่วม log ได้ในคลิกเดียว
            client-side เท่านั้น กรองภายในหน้าที่โหลดอยู่ (ไม่ใช่ query แยกไป backend)
           ======================================================= */}
        <div className="admin-audit-view-toggle" role="tablist" aria-label="มุมมอง Log">
          <button
            type="button"
            role="tab"
            aria-selected={logView === "all"}
            className={`admin-audit-view-btn ${logView === "all" ? "active" : ""}`}
            onClick={() => handleLogViewChange("all")}
          >
            ทั้งหมด {allCount > 0 && `(${allCount})`}
          </button>
          <button
            type="button"
            role="tab"
            aria-selected={logView === "content"}
            className={`admin-audit-view-btn ${logView === "content" ? "active" : ""}`}
            onClick={() => handleLogViewChange("content")}
            title="ซ่อนรายการ เข้าสู่ระบบ / ออกจากระบบ / สมัครสมาชิก"
          >
            เฉพาะกิจกรรมเนื้อหา ({contentCount})
          </button>
          <button
            type="button"
            role="tab"
            aria-selected={logView === "security"}
            className={`admin-audit-view-btn ${logView === "security" ? "active" : ""}`}
            onClick={() => handleLogViewChange("security")}
            title="ดูเฉพาะ เข้าสู่ระบบ / ออกจากระบบ / พยายามเข้าถึงโดยไม่มีสิทธิ์"
          >
            เฉพาะ Security ({securityCount})
          </button>
        </div>

        {/* =======================================================
            2. Filter Bar
           ======================================================= */}
        <div className="admin-audit-filter-card">
          {/* Mobile Filter Trigger Button */}
          <div className="admin-audit-mobile-filter-trigger">
            <button
              type="button"
              className="btn-open-mobile-filter"
              onClick={() => setIsMobileFilterOpen(!isMobileFilterOpen)}
            >
              <Filter size={16} />
              <span>ตัวกรองข้อมูล {hasActiveFilters && "(กำลังใช้งาน)"}</span>
            </button>
            {hasActiveFilters && (
              <button
                type="button"
                className="btn-clear-filter-text"
                onClick={handleClearFilters}
              >
                ล้างตัวกรอง
              </button>
            )}
          </div>

          <div className={`admin-audit-filter-grid ${isMobileFilterOpen ? "open" : ""}`}>
            {/* ตัวกรองหลักที่ใช้บ่อยสุด แสดงตลอดเวลา: ผู้กระทำ + ช่วงวันที่ */}

            {/* 1. Actor Filter (Debounced) */}
            <div className="admin-audit-filter-item">
              <label htmlFor="filter-actor" className="admin-audit-filter-label">ผู้กระทำ (ชื่อผู้ใช้ / ID)</label>
              <input
                id="filter-actor"
                type="text"
                className="admin-audit-input"
                placeholder="ชื่อผู้ใช้ หรือ ID เช่น jane_writer"
                value={actorUserIdInput}
                onChange={handleActorUserIdChange}
              />
            </div>

            {/* 2. Date Range Filter */}
            <div className="admin-audit-filter-item admin-audit-filter-item--date">
              <label className="admin-audit-filter-label">ช่วงวันที่</label>
              <div className="admin-audit-date-range-group">
                <input
                  type="datetime-local"
                  className="admin-audit-input admin-audit-input--date"
                  value={dateFromFilter}
                  onChange={handleDateFromChange}
                  title="จากวันที่"
                />
                <span className="admin-audit-date-sep">ถึง</span>
                <input
                  type="datetime-local"
                  className="admin-audit-input admin-audit-input--date"
                  value={dateToFilter}
                  onChange={handleDateToChange}
                  title="ถึงวันที่"
                />
              </div>
            </div>

            {/* ปุ่มเปิด/ปิดตัวกรองที่ใช้ไม่บ่อย (การกระทำ, ประเภทเป้าหมาย, สถานะ)
                วางแทนที่ตำแหน่งเดิมของฟิลเตอร์เหล่านี้ เพื่อลดจำนวนช่องที่เห็นพร้อมกันตลอดเวลา */}
            <div className="admin-audit-filter-item admin-audit-filter-item--toggle">
              <label className="admin-audit-filter-label">&nbsp;</label>
              <button
                type="button"
                className={`admin-audit-advanced-toggle ${showAdvancedFilters ? "is-open" : ""}`}
                onClick={() => setShowAdvancedFilters((open) => !open)}
                aria-expanded={showAdvancedFilters}
              >
                <Filter size={14} />
                <span>ตัวกรองเพิ่มเติม</span>
                {advancedFilterCount > 0 && (
                  <span className="admin-audit-advanced-toggle-count">{advancedFilterCount}</span>
                )}
                <ChevronDown size={14} className="admin-audit-advanced-toggle-chevron" />
              </button>
            </div>
          </div>

          {/* กลุ่มตัวกรองขั้นสูง: การกระทำแบบละเอียด / ประเภทเป้าหมาย / สถานะ
              ซ่อนไว้เป็นค่าเริ่มต้น กดปุ่ม "ตัวกรองเพิ่มเติม" ด้านบนเพื่อเปิด/ปิด */}
          {showAdvancedFilters && (
            <div className={`admin-audit-filter-grid admin-audit-filter-grid--advanced ${isMobileFilterOpen ? "open" : ""}`}>
              {/* 3. Action Filter */}
              <div className="admin-audit-filter-item">
                <label htmlFor="filter-action" className="admin-audit-filter-label">การกระทำ</label>
                <select
                  id="filter-action"
                  className="admin-audit-select"
                  value={actionFilter}
                  onChange={handleActionChange}
                >
                  <option value="">ทุกการกระทำ</option>
                  {ACTION_GROUPS.map((group) => (
                    <optgroup key={group.label} label={group.label}>
                      {group.keys
                        .filter((actionKey) => ACTION_MAP[actionKey] && !ACTION_MAP[actionKey].hiddenInFilter)
                        .map((actionKey) => (
                          <option key={actionKey} value={actionKey}>
                            {ACTION_MAP[actionKey].label}
                          </option>
                        ))}
                    </optgroup>
                  ))}
                </select>
              </div>

              {/* 4. Target Type Filter */}
              <div className="admin-audit-filter-item">
                <label htmlFor="filter-target" className="admin-audit-filter-label">ประเภทเป้าหมาย</label>
                <select
                  id="filter-target"
                  className="admin-audit-select"
                  value={targetTypeFilter}
                  onChange={handleTargetTypeChange}
                >
                  <option value="">ทุกประเภท</option>
                  {Object.entries(TARGET_TYPE_MAP).map(([typeKey, label]) => (
                    <option key={typeKey} value={typeKey}>
                      {label}
                    </option>
                  ))}
                </select>
              </div>

              {/* 5. Status Filter */}
              <div className="admin-audit-filter-item">
                <label htmlFor="filter-status" className="admin-audit-filter-label">สถานะ</label>
                <select
                  id="filter-status"
                  className="admin-audit-select"
                  value={statusFilter}
                  onChange={handleStatusChange}
                >
                  <option value="">ทุกสถานะ</option>
                  {metadata.statuses && metadata.statuses.length > 0 ? (
                    metadata.statuses.map((st) => (
                      <option key={st} value={st}>
                        {st === "SUCCESS" ? "สำเร็จ" : st === "FAILURE" ? "ไม่สำเร็จ" : st}
                      </option>
                    ))
                  ) : (
                    <>
                      <option value="SUCCESS">สำเร็จ</option>
                      <option value="FAILURE">ไม่สำเร็จ</option>
                    </>
                  )}
                </select>
              </div>
            </div>
          )}

          {/* Clear Filters Action Row */}
          {hasActiveFilters && (
            <div className="admin-audit-filter-actions">
              <button
                type="button"
                className="btn-clear-filter"
                onClick={handleClearFilters}
              >
                <X size={14} />
                <span>ล้างตัวกรองทั้งหมด</span>
              </button>
            </div>
          )}
        </div>

        {/* Validation Error Banner */}
        {filterValidationMsg && (
          <div className="admin-audit-banner admin-audit-banner--warning">
            <AlertCircle size={18} />
            <span>{filterValidationMsg}</span>
          </div>
        )}

        {/* Server/API Error Banner */}
        {error && (
          <div className="admin-audit-banner admin-audit-banner--error">
            <AlertCircle size={18} />
            <div className="admin-audit-banner__content">
              <span>{error}</span>
              <button type="button" className="btn-retry-banner" onClick={fetchAuditLogs}>
                ลองอีกครั้ง
              </button>
            </div>
          </div>
        )}

        {/* =======================================================
            3. Table & Card List
           ======================================================= */}
        <div className="admin-audit-table-card">
          
          {/* Desktop Table View */}
          <div className="admin-audit-table-wrapper">
            <table className="admin-audit-table">
              <thead>
                <tr>
                  <th style={{ width: "14%", minWidth: "130px" }}>เวลา</th>
                  <th style={{ width: "17%", minWidth: "140px" }}>ผู้กระทำ</th>
                  <th style={{ width: "17%", minWidth: "140px" }}>การกระทำ</th>
                  <th style={{ width: "19%", minWidth: "150px" }}>เป้าหมาย</th>
                  <th style={{ width: "10%", minWidth: "95px" }}>สถานะ</th>
                  <th style={{ width: "10%", minWidth: "95px" }}>ไอพี</th>
                  <th style={{ width: "13%", minWidth: "135px", textAlign: "center" }} className="text-center">การจัดการ</th>
                </tr>
              </thead>
              <tbody>
                {loading ? (
                  // Loading Skeleton Rows
                  Array.from({ length: 6 }).map((_, idx) => (
                    <tr key={`skeleton-${idx}`} className="admin-audit-row-skeleton">
                      <td><div className="skeleton-bar" style={{ width: "80%" }} /></td>
                      <td><div className="skeleton-bar" style={{ width: "70%" }} /></td>
                      <td><div className="skeleton-bar" style={{ width: "60%" }} /></td>
                      <td><div className="skeleton-bar" style={{ width: "50%" }} /></td>
                      <td><div className="skeleton-bar" style={{ width: "60%" }} /></td>
                      <td><div className="skeleton-bar" style={{ width: "75%" }} /></td>
                      <td><div className="skeleton-bar" style={{ width: "100%" }} /></td>
                    </tr>
                  ))
                ) : visibleLogs.length === 0 ? (
                  // Empty State Row
                  <tr>
                    <td colSpan={7}>
                      <div className="admin-audit-empty-state">
                        <Inbox size={48} className="empty-icon" />
                        <h3>ไม่พบประวัติการใช้งาน</h3>
                        {hasActiveFilters && <p>ลองปรับตัวกรองใหม่อีกครั้ง</p>}
                      </div>
                    </td>
                  </tr>
                ) : (
                  // Data Rows
                  visibleLogs.map((log) => {
                    const actionInfo = ACTION_MAP[log.action] || {
                      label: log.action,
                      group: "gray",
                      color: "#475569",
                      bg: "#f1f5f9",
                      border: "#cbd5e1",
                    };
                    const actorNameText = renderActorName(log.actor_user_id, log.actor_role, log.actor_username);
                    const targetNameText = renderTargetName(log.target_type, log.target_id, log.target_name);

                    return (
                      <tr
                        key={log.log_id}
                        className="admin-audit-row"
                        onClick={() => fetchLogDetail(log.log_id)}
                      >
                        {/* เวลา */}
                        <td>
                          <span
                            className="admin-audit-time"
                            title={formatFullThaiDateTime(log.created_at)}
                          >
                            {formatShortThaiDateTime(log.created_at)}
                          </span>
                        </td>

                        {/* ผู้กระทำ */}
                        <td>
                          <span className="admin-audit-actor" title={actorNameText}>
                            {actorNameText}
                          </span>
                        </td>

                        {/* การกระทำ */}
                        <td>
                          <span
                            className="admin-audit-action-badge"
                            style={{
                              backgroundColor: actionInfo.bg,
                              color: actionInfo.color,
                              borderColor: actionInfo.border,
                            }}
                            title={actionInfo.label}
                          >
                            {actionInfo.label}
                          </span>
                        </td>

                        {/* เป้าหมาย */}
                        <td>
                          <span className="admin-audit-target" title={targetNameText}>
                            {targetNameText}
                          </span>
                        </td>

                        {/* สถานะ */}
                        <td>
                          {renderStatusBadge(log.status)}
                        </td>

                        {/* ไอพี */}
                        <td>
                          <span className="admin-audit-ip font-mono">
                            {log.ip_address || "-"}
                          </span>
                        </td>

                        {/* ดูรายละเอียด */}
                        <td style={{ textAlign: "center" }} className="text-center">
                          <div className="action-cell-content">
                            <button
                              type="button"
                              className="btn-view-detail"
                              onClick={(e) => {
                                e.stopPropagation();
                                fetchLogDetail(log.log_id);
                              }}
                            >
                              ดูรายละเอียด
                            </button>
                          </div>
                        </td>
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          </div>

          {/* Mobile Card List View */}
          <div className="admin-audit-mobile-card-list">
            {loading ? (
              Array.from({ length: 4 }).map((_, idx) => (
                <div key={`m-skeleton-${idx}`} className="admin-audit-mobile-card skeleton">
                  <div className="skeleton-bar" style={{ width: "40%", height: "16px", marginBottom: "8px" }} />
                  <div className="skeleton-bar" style={{ width: "70%", height: "20px", marginBottom: "8px" }} />
                  <div className="skeleton-bar" style={{ width: "50%", height: "14px" }} />
                </div>
              ))
            ) : visibleLogs.length === 0 ? (
              <div className="admin-audit-empty-state">
                <Inbox size={48} className="empty-icon" />
                <h3>ไม่พบประวัติการใช้งาน</h3>
                {hasActiveFilters && <p>ลองปรับตัวกรองใหม่อีกครั้ง</p>}
              </div>
            ) : (
              visibleLogs.map((log) => {
                const actionInfo = ACTION_MAP[log.action] || {
                  label: log.action,
                  group: "gray",
                  color: "#475569",
                  bg: "#f1f5f9",
                  border: "#cbd5e1",
                };

                return (
                  <div
                    key={`mobile-${log.log_id}`}
                    className="admin-audit-mobile-card"
                    onClick={() => fetchLogDetail(log.log_id)}
                  >
                    <div className="mobile-card-header">
                      <span className="mobile-card-time">
                        {formatShortThaiDateTime(log.created_at)}
                      </span>
                      {renderStatusBadge(log.status)}
                    </div>

                    <div className="mobile-card-body">
                      <span
                        className="admin-audit-action-badge"
                        style={{
                          backgroundColor: actionInfo.bg,
                          color: actionInfo.color,
                          borderColor: actionInfo.border,
                        }}
                      >
                        {actionInfo.label}
                      </span>
                      <div className="mobile-card-row">
                        <span className="mobile-card-label">ผู้กระทำ:</span>
                        <span className="mobile-card-value">
                          {renderActorName(log.actor_user_id, log.actor_role, log.actor_username)}
                        </span>
                      </div>
                      <div className="mobile-card-row">
                        <span className="mobile-card-label">เป้าหมาย:</span>
                        <span className="mobile-card-value">
                          {renderTargetName(log.target_type, log.target_id, log.target_name)}
                        </span>
                      </div>
                    </div>

                    <div className="mobile-card-footer">
                      <span className="mobile-card-ip">IP: {log.ip_address || "-"}</span>
                      <span className="mobile-card-btn-text">แตะเพื่อดูรายละเอียด →</span>
                    </div>
                  </div>
                );
              })
            )}
          </div>

          {/* =======================================================
              4. Pagination
             ======================================================= */}
          {/* Footer Pagination Template (Image 2 style) */}
          <div className="admin-table-footer">
            <div className="admin-table-footer-left">
              <span className="admin-table-info-text">
                แสดง <strong>{displayTotal === 0 ? 0 : (page - 1) * limit + 1}–{Math.min(page * limit, displayTotal)}</strong> จาก <strong>{displayTotal}</strong> รายการ
              </span>

              <div className="admin-table-per-page">
                <span>แสดงต่อหน้า</span>
                <select
                  className="admin-per-page-select"
                  value={limit}
                  onChange={handleLimitChange}
                >
                  <option value={20}>20</option>
                  <option value={50}>50</option>
                  <option value={100}>100</option>
                </select>
              </div>
            </div>

            <div className="admin-pagination-img2">
              <button
                type="button"
                className="page-btn-box"
                disabled={page <= 1 || loading}
                onClick={() => setPage((prev) => Math.max(prev - 1, 1))}
              >
                <ChevronLeft size={16} />
                <span>ก่อนหน้า</span>
              </button>

              <span className="page-indicator-text">
                หน้า <strong>{page}</strong> จาก <strong>{displayTotalPages}</strong>
              </span>

              <button
                type="button"
                className="page-btn-box"
                disabled={page >= displayTotalPages || loading}
                onClick={() => setPage((prev) => Math.min(prev + 1, displayTotalPages))}
              >
                <span>ถัดไป</span>
                <ChevronRight size={16} />
              </button>
            </div>
          </div>
        </div>

      </div>

      {/* =======================================================
          5. Detail Modal / Drawer
         ======================================================= */}
      {detailModalOpen && (
        <div className="admin-audit-modal-backdrop" onClick={() => setDetailModalOpen(false)}>
          <div className="admin-audit-modal-card" onClick={(e) => e.stopPropagation()}>
            {/* Modal Header */}
            <div className="admin-audit-modal-header">
              <div className="modal-header-title-wrap">
                <FileText size={20} className="modal-header-icon" />
                <h3 className="admin-audit-modal-title">
                  รายละเอียดรายการ #{selectedLogId}
                </h3>
              </div>
              <button
                type="button"
                className="btn-close-modal"
                onClick={() => setDetailModalOpen(false)}
                aria-label="ปิดหน้าต่าง"
              >
                <X size={18} />
              </button>
            </div>

            {/* Modal Content */}
            <div className="admin-audit-modal-body">
              {detailLoading ? (
                <div className="admin-audit-modal-loading">
                  <Loader2 size={36} className="spin loading-icon" />
                  <p>กำลังโหลดรายละเอียดประวัติ...</p>
                </div>
              ) : detailError ? (
                <div className="admin-audit-modal-error">
                  <AlertCircle size={36} className="error-icon" />
                  <h4>{detailError}</h4>
                  <button
                    type="button"
                    className="btn-retry-modal"
                    onClick={() => fetchLogDetail(selectedLogId)}
                  >
                    ลองใหม่อีกครั้ง
                  </button>
                </div>
              ) : detailData ? (
                <div className="admin-audit-detail-wrapper">
                  
                  {/* Summary Section */}
                  <div className="detail-section">
                    <h4 className="detail-section-title">สรุปข้อมูล</h4>
                    <table className="admin-audit-detail-table">
                      <tbody>
                        <tr>
                          <td className="detail-label">ผู้กระทำ</td>
                          <td className="detail-value">
                            {renderActorName(detailData.actor_user_id, detailData.actor_role, detailData.actor_username)}
                          </td>
                        </tr>
                        <tr>
                          <td className="detail-label">การกระทำ</td>
                          <td className="detail-value">
                            {ACTION_MAP[detailData.action]?.label || detailData.action}
                          </td>
                        </tr>
                        <tr>
                          <td className="detail-label">เป้าหมาย</td>
                          <td className="detail-value">
                            {renderTargetName(detailData.target_type, detailData.target_id, detailData.target_name)}
                          </td>
                        </tr>
                        {detailData.metadata?.novel_title && (
                          <tr>
                            <td className="detail-label">นิยาย</td>
                            <td className="detail-value" style={{ fontWeight: 600, color: "#0284c7" }}>
                              {detailData.metadata.novel_title} {detailData.metadata.novel_id ? `(#${detailData.metadata.novel_id})` : ""}
                            </td>
                          </tr>
                        )}
                        {detailData.metadata?.chapter_title && (
                          <tr>
                            <td className="detail-label">ตอน</td>
                            <td className="detail-value" style={{ fontWeight: 600, color: "#475569" }}>
                              {detailData.metadata.chapter_title} {detailData.metadata.chapter_id ? `(#${detailData.metadata.chapter_id})` : ""}
                            </td>
                          </tr>
                        )}
                        <tr>
                          <td className="detail-label">สถานะ</td>
                          <td className="detail-value">
                            {renderStatusBadge(detailData.status)}
                          </td>
                        </tr>
                        <tr>
                          <td className="detail-label">ไอพี</td>
                          <td className="detail-value font-mono">
                            {detailData.ip_address || "-"}
                          </td>
                        </tr>
                        <tr>
                          <td className="detail-label">วันที่/เวลา</td>
                          <td className="detail-value">
                            {formatFullThaiDateTime(detailData.created_at)}
                          </td>
                        </tr>
                      </tbody>
                    </table>
                  </div>

                  {/* Metadata Section */}
                  <div className="detail-section">
                    <h4 className="detail-section-title">ข้อมูลเพิ่มเติม</h4>
                    {detailData.metadata && Object.keys(detailData.metadata).length > 0 ? (
                      <table className="admin-audit-detail-table admin-audit-detail-table--metadata">
                        <thead>
                          <tr>
                            <th style={{ width: "40%" }}>ข้อมูล</th>
                            <th>ค่า</th>
                          </tr>
                        </thead>
                        <tbody>
                          {Object.entries(detailData.metadata).map(([metaKey, metaVal]) => {
                            const labelThai = METADATA_KEY_MAP[metaKey] || metaKey;
                            const formattedVal = formatMetadataValue(metaKey, metaVal, detailData.metadata);

                            return (
                              <tr key={metaKey}>
                                <td className="detail-label">{labelThai}</td>
                                <td className="detail-value">{formattedVal}</td>
                              </tr>
                            );
                          })}
                        </tbody>
                      </table>
                    ) : (
                      <div className="admin-audit-metadata-empty">
                        <p>ไม่มีข้อมูลเพิ่มเติม</p>
                      </div>
                    )}
                  </div>

                </div>
              ) : null}
            </div>

            {/* Modal Footer */}
            <div className="admin-audit-modal-footer">
              <button
                type="button"
                className="btn-modal-dismiss"
                onClick={() => setDetailModalOpen(false)}
              >
                ปิด
              </button>
            </div>
          </div>
        </div>
      )}

    </div>
  );
}

import React, { useState, useEffect, useMemo } from 'react';
import { UserCheck, FileClock, Ban, Search, Filter, Edit, Trash2, Eye, Award, Loader2, AlertTriangle, ExternalLink, ChevronLeft, ChevronRight, RotateCcw, Calendar, ArrowDown, ArrowUp } from 'lucide-react';
import axios from 'axios';
import './Manageusers.css';

const Manageusers = () => {
  const [users, setUsers] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);

  // ค้นหาและคัดกรอง
  const [searchQuery, setSearchQuery] = useState("");
  const [roleFilter, setRoleFilter] = useState("all");
  const [statusFilter, setStatusFilter] = useState("all");
  const [writerAppFilter, setWriterAppFilter] = useState("all");
  const [dateSortOrder, setDateSortOrder] = useState("desc"); // 'desc' = ใหม่ไปเก่า, 'asc' = เก่าไปใหม่

  // Pagination
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage, setItemsPerPage] = useState(10);

  // Modals state
  const [viewUserModal, setViewUserModal] = useState({ isOpen: false, user: null });
  const [viewApplicationModal, setViewApplicationModal] = useState({ isOpen: false, user: null });
  const [editUserModal, setEditUserModal] = useState({ isOpen: false, user: null, username: "", role: "reader", status: "active", reason: "" });
  const [deleteConfirmModal, setDeleteConfirmModal] = useState({ isOpen: false, user: null });

  const API_BASE_URL = (import.meta.env.VITE_API_BASE_URL || "").replace(/\/$/, "");

  // 🔑 ดึง token + header มาตรฐานสำหรับทุก request
  const getAuthHeaders = () => {
    const token = localStorage.getItem('token');
    return {
      'Authorization': `Bearer ${token}`,
      'Content-Type': 'application/json'
    };
  };

  // 🙋 อ่าน user_id ของแอดมินที่ล็อกอินอยู่ตอนนี้ จาก JWT payload
  // ใช้กันไม่ให้แอดมินกดจัดการ/ลบ/ระงับบัญชีตัวเอง (ฝั่ง backend ก็เช็คซ้ำอีกชั้นอยู่แล้ว)
  const getCurrentUserId = () => {
    try {
      const token = localStorage.getItem('token');
      if (!token) return null;
      const payload = JSON.parse(atob(token.split('.')[1]));
      return payload.user_id ?? payload.id ?? payload.sub ?? null;
    } catch {
      return null;
    }
  };
  const currentUserId = getCurrentUserId();

  // 🎯 ดึงข้อมูลรายชื่อผู้ใช้งานจาก API จริง (/api/admin/users)
  const loadData = async () => {
    setIsLoading(true);
    setError(null);
    try {
      const headers = getAuthHeaders();
      const res = await axios.get(`${API_BASE_URL}/api/admin/users?limit=1000`, { headers });
      const list = res.data?.users || res.data?.data || res.data;
      setUsers(Array.isArray(list) ? list : []);
    } catch (err) {
      console.error(err);
      setError("เกิดข้อผิดพลาดในการโหลดข้อมูลผู้ใช้งาน กรุณาลองใหม่อีกครั้ง");
      setUsers([]);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  // 1. คำนวณยอดสถิติ
  // หมายเหตุ: users.status มีแค่ active / suspended เท่านั้น (ไม่มี pending อีกต่อไป)
  // ส่วน "คำขอนักเขียนรอตรวจสอบ" มาจาก writer_application_status ของแต่ละ user แทน
  const stats = useMemo(() => {
    const active = users.filter(u => u.status === "active").length;
    const suspended = users.filter(u => u.status === "suspended").length;
    const pendingWriterApps = users.filter(u => u.writer_application_status === "pending").length;
    return { active, suspended, pendingWriterApps, total: users.length };
  }, [users]);

  // 2. กรองและค้นหารายชื่อผู้ใช้
  const filteredUsers = useMemo(() => {
    let list = users.filter(u => {
      const matchSearch = searchQuery.trim() === "" ||
        (u.username && u.username.toLowerCase().includes(searchQuery.toLowerCase())) ||
        (u.email && u.email.toLowerCase().includes(searchQuery.toLowerCase()));

      const matchRole = roleFilter === "all" || u.role === roleFilter;
      const matchStatus = statusFilter === "all" || u.status === statusFilter;
      const matchWriterApp = writerAppFilter === "all" || u.writer_application_status === writerAppFilter;

      return matchSearch && matchRole && matchStatus && matchWriterApp;
    });

    if (dateSortOrder) {
      list = [...list].sort((a, b) => {
        const timeA = a.created_at ? new Date(a.created_at).getTime() : 0;
        const timeB = b.created_at ? new Date(b.created_at).getTime() : 0;
        return dateSortOrder === 'asc' ? timeA - timeB : timeB - timeA;
      });
    }

    return list;
  }, [users, searchQuery, roleFilter, statusFilter, writerAppFilter, dateSortOrder]);

  // 3. จัดการแบ่งหน้า
  const totalPages = Math.max(1, Math.ceil(filteredUsers.length / itemsPerPage));
  const paginatedUsers = useMemo(() => {
    const startIdx = (currentPage - 1) * itemsPerPage;
    return filteredUsers.slice(startIdx, startIdx + itemsPerPage);
  }, [filteredUsers, currentPage]);

  useEffect(() => {
    setCurrentPage(1);
  }, [searchQuery, roleFilter, statusFilter, writerAppFilter, dateSortOrder]);

  // 3.1 ตัดเลขหน้าให้พอดี (แสดงหน้าแรก/หน้าสุดท้าย/หน้าใกล้ปัจจุบัน + จุดไข่ปลา)
  //     ป้องกันแถวปุ่มยาวเกินหน้าจอเมื่อมีผู้ใช้เยอะ
  const pageItems = useMemo(() => {
    const items = [];
    const addNeighborsOf = new Set([1, totalPages, currentPage - 1, currentPage, currentPage + 1]);
    let lastAdded = 0;
    for (let p = 1; p <= totalPages; p++) {
      if (addNeighborsOf.has(p)) {
        if (p - lastAdded > 1) items.push({ type: "ellipsis", key: `e${p}` });
        items.push({ type: "page", value: p });
        lastAdded = p;
      }
    }
    return items;
  }, [totalPages, currentPage]);

  const [isUpdating, setIsUpdating] = useState(false);

  // 4. จัดการอัปเดตผู้ใช้ (Edit) — เรียก backend จริง 2 endpoint แยกกัน
  //    - username: PATCH /api/admin/users/{id}/username
  //    - demote: ใช้เฉพาะกรณี writer -> reader เท่านั้น (ทิศทางเดียว ห้ามตั้งเป็น writer/admin จากหน้านี้)
  //    - status: ใช้เปลี่ยน active <-> suspended เท่านั้น
  const handleUpdateUser = async () => {
    const { user, username, role, status, reason } = editUserModal;
    if (!user || isUpdating) return;

    const trimmedUsername = (username || "").trim();
    if (!trimmedUsername) {
      alert("กรุณากรอกชื่อผู้ใช้");
      return;
    }

    setIsUpdating(true);
    try {
      const headers = getAuthHeaders();

      if (trimmedUsername !== user.username) {
        await axios.patch(
          `${API_BASE_URL}/api/admin/users/${user.id}/username`,
          { username: trimmedUsername },
          { headers }
        );
      }

      if (user.role === "writer" && role === "reader") {
        await axios.patch(`${API_BASE_URL}/api/admin/users/${user.id}/demote`, {}, { headers });
      }

      if (user.role === "reader" && role === "writer" && user.had_writer_history && user.status === "active") {
        await axios.patch(`${API_BASE_URL}/api/admin/users/${user.id}/restore-writer`, {}, { headers });
      }

      if (status !== user.status) {
        await axios.patch(
          `${API_BASE_URL}/api/admin/users/${user.id}/status`,
          { status, reason: status === "suspended" ? reason : undefined },
          { headers }
        );
      }

      await loadData();
      setEditUserModal({ isOpen: false, user: null, username: "", role: "reader", status: "active", reason: "" });
    } catch (err) {
      console.error(err);
      const status = err.response?.status;
      const data = err.response?.data;
      const errMsg = (typeof data?.error === "object" ? data.error?.message : data?.error) || data?.message;
      if (status === 400) {
        alert(errMsg || "username ไม่ถูกต้อง");
      } else if (status === 409) {
        alert(errMsg || "username ซ้ำ");
      } else if (status === 401) {
        alert(errMsg || "token หมดอายุ");
      } else if (status === 403) {
        alert(errMsg || "ไม่มีสิทธิ์ admin");
      } else {
        alert("เกิดข้อผิดพลาดในการบันทึกการเปลี่ยนแปลง กรุณาลองใหม่อีกครั้ง");
      }
    } finally {
      setIsUpdating(false);
    }
  };

  // 5. จัดการลบผู้ใช้ (Delete) — เรียก backend จริง และ handle กรณี 409
  //    (writer ที่มีนิยายอยู่ในระบบ ห้ามลบถาวร ต้องระงับบัญชีแทน)
  const handleDeleteUser = async () => {
    const { user } = deleteConfirmModal;
    if (!user) return;

    try {
      const headers = getAuthHeaders();
      await axios.delete(`${API_BASE_URL}/api/admin/users/${user.id}`, { headers });
      setDeleteConfirmModal({ isOpen: false, user: null });
      await loadData();
    } catch (err) {
      console.error(err);
      if (err.response?.status === 409) {
        alert("ไม่สามารถลบบัญชีนี้ได้ เนื่องจากมีนิยายอยู่ในระบบ\nกรุณาระงับบัญชีแทนการลบ");
      } else if (err.response?.status === 403) {
        alert("ไม่สามารถดำเนินการกับบัญชีของตัวเองได้");
      } else {
        alert("เกิดข้อผิดพลาดในการลบบัญชีผู้ใช้งาน กรุณาลองใหม่อีกครั้ง");
      }
      setDeleteConfirmModal({ isOpen: false, user: null });
    }
  };

  const statusLabel = (status) => (status === "active" ? "ปกติ" : status === "suspended" ? "ระงับแล้ว" : "-");
  const statusClass = (status) => (status === "active" ? "active" : status === "suspended" ? "suspended" : "pending");
  const roleLabel = (role) => {
    if (role === "reader") return "นักอ่าน";
    if (role === "writer") return "นักเขียน";
    if (role === "admin") return "ผู้ดูแลระบบ";
    return role || "นักอ่าน";
  };

  return (
    <div className="admin-manage-users-panel">
      <div className="admin-container">

        {/* ส่วนหัวหน้าจัดการ */}
        <header className="admin-header-sec">
          <h1 className="admin-title">จัดการผู้ใช้งาน</h1>
          <p className="admin-subtitle">จัดการข้อมูลและสถานะของผู้ใช้งานในระบบ</p>
          <svg className="header-branch-accent" viewBox="0 0 200 16" preserveAspectRatio="none" aria-hidden="true">
            <path d="M0 8 H70 M70 8 C 78 8, 78 2, 86 2 H130 M70 8 C 78 8, 78 14, 86 14 H130 M130 2 H200 M130 14 H160" />
          </svg>
        </header>

        {/* 📊 การ์ดสถิติ — กดเพื่อกรองตารางด้านล่างได้เลย */}
        <section className="admin-stats-grid">
          <button
            type="button"
            className={`admin-stat-card card-active ${statusFilter === "active" && writerAppFilter === "all" ? "admin-stat-card--selected admin-stat-card--active" : ""}`}
            onClick={() => {
              setWriterAppFilter("all");
              setStatusFilter(statusFilter === "active" ? "all" : "active");
            }}
            aria-pressed={statusFilter === "active" && writerAppFilter === "all"}
          >
            <div className="stat-card-icon bg-green-light">
              <UserCheck size={20} />
            </div>
            <div className="stat-card-left">
              <span className="stat-card-title">ปกติ</span>
              <span className="stat-card-number">{stats.active.toLocaleString()}</span>
            </div>
          </button>

          <button
            type="button"
            className={`admin-stat-card card-pending ${writerAppFilter === "pending" ? "admin-stat-card--selected admin-stat-card--active" : ""}`}
            onClick={() => {
              setStatusFilter("all");
              setRoleFilter("all");
              setWriterAppFilter(writerAppFilter === "pending" ? "all" : "pending");
            }}
            aria-pressed={writerAppFilter === "pending"}
          >
            <div className="stat-card-icon bg-yellow-light">
              <FileClock size={20} />
            </div>
            <div className="stat-card-left">
              <span className="stat-card-title">คำขอนักเขียนรอตรวจสอบ</span>
              <span className="stat-card-number">{stats.pendingWriterApps.toLocaleString()}</span>
            </div>
          </button>

          <button
            type="button"
            className={`admin-stat-card card-suspended ${statusFilter === "suspended" && writerAppFilter === "all" ? "admin-stat-card--selected admin-stat-card--active" : ""}`}
            onClick={() => {
              setWriterAppFilter("all");
              setStatusFilter(statusFilter === "suspended" ? "all" : "suspended");
            }}
            aria-pressed={statusFilter === "suspended" && writerAppFilter === "all"}
          >
            <div className="stat-card-icon bg-red-light">
              <Ban size={20} />
            </div>
            <div className="stat-card-left">
              <span className="stat-card-title">ระงับแล้ว</span>
              <span className="stat-card-number">{stats.suspended.toLocaleString()}</span>
            </div>
          </button>
        </section>

        {/* 📋 ตารางรายชื่อบัญชีผู้ใช้ */}
        {isLoading ? (
          <div className="admin-loading">
            <Loader2 className="loading-spin" size={22} />
            <span>กำลังดึงข้อมูลรายชื่อบัญชีผู้ใช้งานจากฐานระบบ...</span>
          </div>
        ) : error ? (
          <div className="admin-error">
            <AlertTriangle size={22} />
            <div>
              <strong>โหลดข้อมูลไม่สำเร็จ</strong>
              <p>{error}</p>
              <button type="button" className="retry-btn" onClick={loadData}>ลองใหม่อีกครั้ง</button>
            </div>
          </div>
        ) : (
          <div className="admin-table-container">
            {/* 🔍 Search Bar & Filters อยู่ภายใน Container เดียวกับ Table */}
            {/* 🔍 Search Bar & Filters อยู่ภายใน Container เดียวกับ Table (ตรงตามรูปภาพที่ 1) */}
            <div className="admin-table-top-bar">
              <div className="search-box-wrapper">
                <Search className="search-icon" size={16} />
                <input
                  type="text"
                  className="admin-search-input"
                  placeholder="ค้นหาชื่อผู้ใช้, อีเมล..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
              </div>

              <div className="filter-controls-group">
                <div className="select-filter-item">
                  <span className="filter-label-text">บทบาท:</span>
                  <div className="select-filter-wrapper">
                    <select
                      className="admin-filter-select"
                      value={roleFilter}
                      onChange={(e) => setRoleFilter(e.target.value)}
                    >
                      <option value="all">บทบาททั้งหมด</option>
                      <option value="reader">นักอ่าน</option>
                      <option value="writer">นักเขียน</option>
                      <option value="admin">ผู้ดูแลระบบ</option>
                    </select>
                  </div>
                </div>

                <div className="select-filter-item">
                  <span className="filter-label-text">สถานะ:</span>
                  <div className="select-filter-wrapper">
                    <select
                      className="admin-filter-select"
                      value={statusFilter}
                      onChange={(e) => setStatusFilter(e.target.value)}
                    >
                      <option value="all">สถานะทั้งหมด</option>
                      <option value="active">ปกติ</option>
                      <option value="suspended">ระงับแล้ว</option>
                    </select>
                  </div>
                </div>

                {(searchQuery.trim() !== "" || roleFilter !== "all" || statusFilter !== "all" || writerAppFilter !== "all" || dateSortOrder !== "desc") && (
                  <button
                    type="button"
                    className="clear-filter-btn"
                    onClick={() => {
                      setSearchQuery("");
                      setRoleFilter("all");
                      setStatusFilter("all");
                      setWriterAppFilter("all");
                      setDateSortOrder("desc");
                    }}
                    title="ล้างตัวกรองทั้งหมด"
                  >
                    <RotateCcw size={13} />
                    <span>ล้างตัวกรอง</span>
                  </button>
                )}
              </div>
            </div>

            {filteredUsers.length === 0 ? (
              <div className="admin-empty-state-panel">
                <div className="empty-panel-icon">🔍</div>
                <h3>ไม่พบผู้ใช้งานตรงกับเงื่อนไข</h3>
                <p>กรุณาตรวจสอบการสะกดคำ หรือเปลี่ยนตัวกรองบทบาท/สถานะ</p>
              </div>
            ) : (
              <>
                <div className="admin-table-scroll-wrapper">
                  <table className="users-admin-table">
                    <thead>
                      <tr>
                        <th className="th-col-num" style={{ width: "5%", minWidth: "46px" }}>#</th>
                        <th className="th-col-username" style={{ width: "20%", minWidth: "190px" }}>ชื่อผู้ใช้</th>
                        <th className="th-col-email" style={{ width: "19%", minWidth: "180px" }}>อีเมล</th>
                        <th className="th-col-role" style={{ width: "11%", minWidth: "100px", textAlign: "center" }}>บทบาท</th>
                        <th className="th-col-status" style={{ width: "11%", minWidth: "110px", textAlign: "center" }}>สถานะบัญชี</th>
                        <th className="th-col-writer-app" style={{ width: "11%", minWidth: "115px", textAlign: "center" }}>คำขอนักเขียน</th>
                        <th className="th-col-date" style={{ width: "11%", minWidth: "120px" }}>
                          <div className="th-date-wrapper">
                            <span>สมัครเมื่อ</span>
                            <button
                              type="button"
                              className={`btn-date-sort ${dateSortOrder === 'asc' ? 'asc' : 'desc'}`}
                              onClick={() => setDateSortOrder(prev => prev === 'desc' ? 'asc' : 'desc')}
                              title={dateSortOrder === 'desc' ? "เรียงจากใหม่อยู่บน (คลิกเพื่อสลับเป็นเก่าอยู่บน)" : "เรียงจากเก่าอยู่บน (คลิกเพื่อสลับเป็นใหม่อยู่บน)"}
                            >
                              <Calendar size={12} />
                              {dateSortOrder === 'desc' ? <ArrowDown size={11} /> : <ArrowUp size={11} />}
                            </button>
                          </div>
                        </th>
                        <th className="th-col-actions text-center" style={{ width: "12%", minWidth: "140px", textAlign: "center" }}>จัดการ</th>
                      </tr>
                    </thead>
                    <tbody>
                      {paginatedUsers.map((user, idx) => {
                        const itemIndex = (currentPage - 1) * itemsPerPage + idx + 1;
                        const isSelf = currentUserId != null && String(user.id) === String(currentUserId);
                        return (
                          <tr key={user.id || idx}>
                            <td className="row-num-col">{itemIndex}</td>
                            <td className="row-username-col">
                              {user.pic_profile ? (
                                <img
                                  src={user.pic_profile}
                                  alt={user.username}
                                  className="user-avatar-img"
                                  onError={(e) => { e.target.style.display = "none"; e.target.nextSibling.style.display = "flex"; }}
                                />
                              ) : null}
                              <div className="user-initial-avatar" style={user.pic_profile ? { display: "none" } : undefined}>
                                {user.username ? user.username.charAt(0).toUpperCase() : "U"}
                              </div>
                              <span className="username-strong" title={user.username}>{user.username}</span>
                              {isSelf && <span className="self-tag">คุณ</span>}
                            </td>
                            <td className="row-email-col" title={user.email}>{user.email}</td>
                            <td>
                              <span className={`role-badge role-${(user.role || 'reader').toLowerCase()}`}>
                                {roleLabel(user.role)}
                              </span>
                            </td>
                            <td>
                              <span className={`status-badge status-${statusClass(user.status)}`}>
                                <span className="status-dot"></span>
                                {statusLabel(user.status)}
                              </span>
                            </td>
                            <td>
                              {user.writer_application_status === "pending" ? (
                                <span className="status-badge status-pending">
                                  <span className="status-dot"></span>
                                  รอตรวจสอบ
                                </span>
                              ) : (
                                <span className="cell-muted">-</span>
                              )}
                            </td>
                            <td className="date-col">
                              {user.created_at
                                ? new Date(user.created_at).toLocaleDateString("th-TH", { day: 'numeric', month: 'short', year: 'numeric' })
                                : "-"}
                            </td>
                            <td className="actions-cell text-center align-center">
                              <div className="action-cell-content">
                                <button
                                  className="btn-icon-action btn-detail"
                                  onClick={() => setViewUserModal({ isOpen: true, user })}
                                  title="ดูข้อมูลรายละเอียด"
                                >
                                  <Eye size={15} />
                                </button>

                                <button
                                  className="btn-icon-action btn-edit-user"
                                  onClick={() => setEditUserModal({ isOpen: true, user, username: user.username || "", role: user.role || "reader", status: user.status || "active", reason: "" })}
                                  title={isSelf ? "ไม่สามารถแก้ไขบัญชีของตัวเองได้" : "แก้ไขบัญชี"}
                                  disabled={isSelf}
                                >
                                  <Edit size={15} />
                                </button>

                                <button
                                  className="btn-icon-action btn-delete-user"
                                  onClick={() => setDeleteConfirmModal({ isOpen: true, user })}
                                  title={isSelf ? "ไม่สามารถลบบัญชีของตัวเองได้" : "ลบบัญชีผู้ใช้"}
                                  disabled={isSelf}
                                >
                                  <Trash2 size={15} />
                                </button>
                              </div>
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>

                {/* ── Table Footer & Pagination (ตรงตามรูปภาพที่ 2) ── */}
                <div className="admin-table-footer">
                  <div className="admin-table-footer-left">
                    <span className="admin-table-info-text">
                      แสดง <strong>{filteredUsers.length === 0 ? 0 : (currentPage - 1) * itemsPerPage + 1}–{Math.min(currentPage * itemsPerPage, filteredUsers.length)}</strong> จาก <strong>{filteredUsers.length}</strong> รายการ
                    </span>

                    <div className="admin-table-per-page">
                      <span>แสดงต่อหน้า</span>
                      <select
                        className="admin-per-page-select"
                        value={itemsPerPage}
                        onChange={(e) => {
                          setItemsPerPage(Number(e.target.value));
                          setCurrentPage(1);
                        }}
                      >
                        <option value={10}>10</option>
                        <option value={20}>20</option>
                        <option value={50}>50</option>
                      </select>
                    </div>
                  </div>

                  {/* 🎯 ปุ่มกดหน้าแบบในรูปภาพที่ 2 */}
                  <div className="admin-pagination-img2">
                    <button
                      type="button"
                      className="page-btn-box"
                      onClick={() => setCurrentPage(prev => Math.max(1, prev - 1))}
                      disabled={currentPage === 1}
                    >
                      <ChevronLeft size={16} />
                      <span>ก่อนหน้า</span>
                    </button>

                    <span className="page-indicator-text">
                      หน้า <strong>{currentPage}</strong> จาก <strong>{totalPages}</strong>
                    </span>

                    <button
                      type="button"
                      className="page-btn-box"
                      onClick={() => setCurrentPage(prev => Math.min(totalPages, prev + 1))}
                      disabled={currentPage === totalPages}
                    >
                      <span>ถัดไป</span>
                      <ChevronRight size={16} />
                    </button>
                  </div>
                </div>
              </>
            )}
          </div>
        )}

        {/* ── 1. Modal ดูรายละเอียดผู้ใช้ ── */}
        {viewUserModal.isOpen && viewUserModal.user && (
          <div className="admin-modal-overlay" onClick={() => setViewUserModal({ isOpen: false, user: null })}>
            <div className="admin-modal-content" onClick={e => e.stopPropagation()}>
              <div className="modal-header-sec">
                <h2>รายละเอียดผู้ใช้งาน</h2>
                <button className="close-modal-x" onClick={() => setViewUserModal({ isOpen: false, user: null })}>×</button>
              </div>

              <div className="modal-body-content">
                <div className="modal-profile-header">
                  {viewUserModal.user.pic_profile ? (
                    <img
                      src={viewUserModal.user.pic_profile}
                      alt={viewUserModal.user.username}
                      className="profile-large-avatar-img"
                      onError={(e) => { e.target.style.display = "none"; e.target.nextSibling.style.display = "flex"; }}
                    />
                  ) : null}
                  <div className="profile-large-avatar" style={viewUserModal.user.pic_profile ? { display: "none" } : undefined}>
                    {viewUserModal.user.username ? viewUserModal.user.username.charAt(0).toUpperCase() : "U"}
                  </div>
                  <div className="profile-head-info">
                    <h3>{viewUserModal.user.username}</h3>
                    <span className={`role-badge role-${(viewUserModal.user.role || 'reader').toLowerCase()}`}>
                      {roleLabel(viewUserModal.user.role)}
                    </span>
                  </div>
                </div>

                <div className="modal-info-table">
                  <div className="info-row">
                    <span className="info-lbl">อีเมล:</span>
                    <span className="info-val">{viewUserModal.user.email}</span>
                  </div>
                  <div className="info-row">
                    <span className="info-lbl">สมัครเมื่อ:</span>
                    <span className="info-val">
                      {viewUserModal.user.created_at ? new Date(viewUserModal.user.created_at).toLocaleDateString("th-TH", { day: 'numeric', month: 'long', year: 'numeric' }) : "-"}
                    </span>
                  </div>
                  <div className="info-row">
                    <span className="info-lbl">สถานะบัญชี:</span>
                    <span className={`info-val status-${statusClass(viewUserModal.user.status)}`}>
                      {statusLabel(viewUserModal.user.status)}
                    </span>
                  </div>
                  {viewUserModal.user.status === "suspended" && viewUserModal.user.suspended_reason && (
                    <div className="info-row">
                      <span className="info-lbl">เหตุผลการระงับ:</span>
                      <span className="info-val">{viewUserModal.user.suspended_reason}</span>
                    </div>
                  )}
                </div>

                {/* หากมีบทบาทเป็น Writer และมีรายละเอียดประวัตินักเขียน */}
                {viewUserModal.user.role === "writer" && viewUserModal.user.writer_details && (
                  <div className="writer-application-section-trigger">
                    <div className="trigger-left">
                      <Award size={18} color="#db2777" />
                      <span>
                        {viewUserModal.user.writer_application_status === "pending"
                          ? "มีใบสมัครนักเขียนรอการตรวจสอบ"
                          : "มีประวัติใบสมัครนักเขียนในระบบ"}
                      </span>
                    </div>
                    <button
                      type="button"
                      className="view-app-btn-trigger"
                      onClick={() => {
                        setViewApplicationModal({ isOpen: true, user: viewUserModal.user });
                        setViewUserModal({ isOpen: false, user: null });
                      }}
                    >
                      📄 ดูใบสมัครนักเขียน
                    </button>
                  </div>
                )}
              </div>

              <div className="modal-footer-sec">
                {viewUserModal.user.role === "writer" && (() => {
                  const writerId = viewUserModal.user.writer_details?.writer_id || viewUserModal.user.writer_id || viewUserModal.user.writer_details?.id || viewUserModal.user.id;
                  return (
                    <a
                      href={`/writer/profile/${writerId}`}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="admin-modal-btn view-writer-profile-btn"
                    >
                      <ExternalLink size={15} />
                      <span>ดูโปรไฟล์นักเขียน</span>
                    </a>
                  );
                })()}
                <button type="button" className="admin-modal-btn cancel-btn" onClick={() => setViewUserModal({ isOpen: false, user: null })}>
                  ปิด
                </button>
              </div>
            </div>
          </div>
        )}

        {/* ── 2. Modal ดูใบสมัครนักเขียน (เลียนแบบหน้าอนุมัติคำขอ) ── */}
        {viewApplicationModal.isOpen && viewApplicationModal.user && (
          <div className="admin-modal-overlay" onClick={() => setViewApplicationModal({ isOpen: false, user: null })}>
            <div className="admin-modal-content modal-content-lg" onClick={e => e.stopPropagation()}>
              <div className="modal-header-sec">
                <h2>ข้อมูลใบสมัครนักเขียน: {viewApplicationModal.user.username}</h2>
                <button
                  className="close-modal-x"
                  onClick={() => {
                    setViewUserModal({ isOpen: true, user: viewApplicationModal.user });
                    setViewApplicationModal({ isOpen: false, user: null });
                  }}
                >
                  ×
                </button>
              </div>

              <div className="modal-body-content">
                <div className="application-details-box">
                  <div className="details-group-box">
                    <h4>ข้อมูลผู้สมัคร</h4>
                    <div className="detail-field">
                      <span className="field-lbl">ชื่อ - นามสกุล:</span>
                      <span className="field-val">{viewApplicationModal.user.writer_details?.name_lastname || "-"}</span>
                    </div>
                    <div className="detail-field">
                      <span className="field-lbl">นามปากกา:</span>
                      <span className="field-val">{viewApplicationModal.user.writer_details?.pen_name || "-"}</span>
                    </div>
                    <div className="detail-field">
                      <span className="field-lbl">อีเมลติดต่อนักเขียน:</span>
                      <span className="field-val">{viewApplicationModal.user.email}</span>
                    </div>
                  </div>

                  <div className="details-group-box">
                    <h4>แนะนำตัว & แฟ้มผลงาน</h4>
                    <div className="details-bio-content">
                      {(() => {
                        const rawBio = viewApplicationModal.user.writer_details?.bio || viewApplicationModal.user.bio || "";
                        const cleanBio = rawBio.replace(/<[^>]*>/g, "").trim();
                        return cleanBio || "ไม่มีการระบุประวัติหรือแนะนำตัว";
                      })()}
                    </div>
                  </div>

                  <div className="details-group-box">
                    <h4>ประเภทนิยายที่เขียนหลัก</h4>
                    <div className="genres-chips-list">
                      {viewApplicationModal.user.writer_details?.genres?.map((g, index) => (
                        <span key={index} className="genre-chip">{g}</span>
                      )) || <span className="genre-chip">ทั่วไป</span>}
                    </div>
                  </div>

                  <div className="details-group-box">
                    <h4>ช่องทางการติดต่อ</h4>
                    {(() => {
                      const wd = viewApplicationModal.user.writer_details || {};
                      const renderContact = (value) => {
                        if (!value) return "-";
                        return value.startsWith("http") ? (
                          <a href={value} target="_blank" rel="noopener noreferrer">{value}</a>
                        ) : (
                          value
                        );
                      };
                      return (
                        <>
                          <div className="detail-field">
                            <span className="field-lbl">ช่องทางหลัก:</span>
                            <span className="field-val highlight-link">{renderContact(wd.primary_contact)}</span>
                          </div>
                          <div className="detail-field">
                            <span className="field-lbl">ช่องทางรอง:</span>
                            <span className="field-val highlight-link">{renderContact(wd.secondary_contact)}</span>
                          </div>
                        </>
                      );
                    })()}
                  </div>

                  {viewApplicationModal.user.writer_application_status === "pending" && (
                    <div className="writer-application-section-trigger">
                      <div className="trigger-left">
                        <Award size={18} color="#db2777" />
                        <span>คำขอนี้ยังรอการอนุมัติ</span>
                      </div>
                      <a className="view-app-btn-trigger view-app-btn-trigger--link" href="/admin/writers">
                        ไปตรวจสอบที่หน้า Writers
                      </a>
                    </div>
                  )}
                </div>
              </div>

              <div className="modal-footer-sec">
                <button
                  type="button"
                  className="admin-modal-btn cancel-btn"
                  onClick={() => {
                    setViewUserModal({ isOpen: true, user: viewApplicationModal.user });
                    setViewApplicationModal({ isOpen: false, user: null });
                  }}
                >
                  ย้อนกลับ
                </button>
              </div>
            </div>
          </div>
        )}

        {/* ── 3. Modal แก้ไขบทบาทและสถานะ ── */}
        {editUserModal.isOpen && editUserModal.user && (
          <div className="admin-modal-overlay" onClick={() => setEditUserModal({ isOpen: false, user: null, username: "", role: "reader", status: "active", reason: "" })}>
            <div className="admin-modal-content" onClick={e => e.stopPropagation()}>
              <div className="modal-header-sec">
                <h2>แก้ไขบัญชีผู้ใช้งาน: {editUserModal.user.username}</h2>
                {/* หมายเหตุ: หัวข้อ modal ยึดชื่อเดิมของบัญชีไว้ ไม่เปลี่ยนตามที่พิมพ์ใน input ด้านล่าง เพื่อไม่ให้สับสนว่ากำลังแก้ไขบัญชีไหน */}
                <button className="close-modal-x" onClick={() => setEditUserModal({ isOpen: false, user: null, username: "", role: "reader", status: "active", reason: "" })}>×</button>
              </div>

              <div className="modal-body-content">
                <div className="edit-form-group">
                  <label className="form-lbl">ชื่อผู้ใช้ (Username)</label>
                  <input
                    type="text"
                    className="admin-form-select"
                    value={editUserModal.username}
                    onChange={(e) => setEditUserModal(prev => ({ ...prev, username: e.target.value }))}
                    placeholder="กรอกชื่อผู้ใช้ใหม่"
                    maxLength={50}
                  />
                </div>

                <div className="edit-form-group">
                  <label className="form-lbl">บทบาท</label>

                    {/* กฎสำคัญ: หน้านี้ไม่เปิดให้มอบสิทธิ์ writer ใหม่
                      ยกเว้นการคืนสิทธิ์ให้ reader ที่มีประวัติ revoked เท่านั้น */}
                  {editUserModal.user.role === "writer" ? (
                    <select
                      className="admin-form-select"
                      value={editUserModal.role}
                      onChange={(e) => setEditUserModal(prev => ({ ...prev, role: e.target.value }))}
                    >
                      <option value="writer">นักเขียน (ไม่เปลี่ยนแปลง)</option>
                      <option value="reader">เลื่อนลง → นักอ่าน (ถอดสิทธิ์นักเขียน)</option>
                    </select>
                  ) : editUserModal.user.role === "reader" && editUserModal.user.had_writer_history ? (
                    <select
                      className="admin-form-select"
                      value={editUserModal.role}
                      onChange={(e) => setEditUserModal(prev => ({ ...prev, role: e.target.value }))}
                    >
                      <option value="reader">นักอ่าน (ไม่เปลี่ยนแปลง)</option>
                      <option value="writer">คืนสิทธิ์นักเขียนจากประวัติเดิม</option>
                    </select>
                  ) : (
                    <div className="admin-form-select admin-form-select--readonly">
                      {roleLabel(editUserModal.user.role)} (ไม่สามารถเปลี่ยนบทบาทจากหน้านี้ได้)
                    </div>
                  )}
                </div>

                <div className="edit-form-group">
                  <label className="form-lbl">สถานะบัญชี</label>
                  <select
                    className="admin-form-select"
                    value={editUserModal.status}
                    onChange={(e) => setEditUserModal(prev => ({ ...prev, status: e.target.value }))}
                  >
                    <option value="active">ปกติ</option>
                    <option value="suspended">ระงับแล้ว</option>
                  </select>
                </div>

                {editUserModal.status === "suspended" && (
                  <div className="edit-form-group">
                    <label className="form-lbl">เหตุผลการระงับ (ไม่บังคับ)</label>
                    <textarea
                      className="admin-form-select admin-form-textarea"
                      placeholder="เช่น สแปม, โพสต์เนื้อหาไม่เหมาะสม, ถูกรายงานหลายครั้ง..."
                      value={editUserModal.reason}
                      onChange={(e) => setEditUserModal(prev => ({ ...prev, reason: e.target.value }))}
                    />
                  </div>
                )}
              </div>

              <div className="modal-footer-sec">
                <button
                  type="button"
                  className="admin-modal-btn cancel-btn"
                  onClick={() => setEditUserModal({ isOpen: false, user: null, username: "", role: "reader", status: "active", reason: "" })}
                  disabled={isUpdating}
                >
                  ยกเลิก
                </button>
                <button
                  type="button"
                  className="admin-modal-btn save-btn"
                  onClick={handleUpdateUser}
                  disabled={isUpdating}
                >
                  {isUpdating ? "กำลังบันทึก..." : "บันทึก"}
                </button>
              </div>
            </div>
          </div>
        )}

        {/* ── 4. Modal ยืนยันการลบผู้ใช้ (ปรับให้กระชับและแยก Reader/Writer) ── */}
        {deleteConfirmModal.isOpen && deleteConfirmModal.user && (
          <div className="admin-modal-overlay" onClick={() => setDeleteConfirmModal({ isOpen: false, user: null })}>
            <div className="admin-modal-content modal-content-sm modal-delete-compact" onClick={e => e.stopPropagation()}>
              <div className="modal-header-sec">
                <h2>ยืนยันการลบบัญชี</h2>
                <button className="close-modal-x" onClick={() => setDeleteConfirmModal({ isOpen: false, user: null })}>×</button>
              </div>

              <div className="modal-body-content modal-body-delete">
                <p className="delete-confirm-question">
                  ต้องการลบบัญชี “<span className="delete-warning-username">{deleteConfirmModal.user.username}</span>” อย่างถาวรหรือไม่?
                </p>

                <p className="delete-critical-warning">
                  ⚠️ การลบบัญชีนี้ไม่สามารถยกเลิกภายหลังได้
                </p>

                {/* หมายเหตุสำหรับนักเขียน (แสดงเฉพาะนักเขียนเท่านั้น นักอ่านจะไม่เห็น) */}
                {deleteConfirmModal.user.role === "writer" && (
                  <div className="writer-delete-note-box">
                    <span className="writer-note-title">หมายเหตุสำหรับนักเขียน</span>
                    <p className="writer-note-text">นิยายที่สร้างไว้จะยังคงอยู่ในระบบตามเงื่อนไขของระบบ</p>
                  </div>
                )}
              </div>

              <div className="modal-footer-sec">
                <button
                  type="button"
                  className="admin-modal-btn cancel-btn"
                  onClick={() => setDeleteConfirmModal({ isOpen: false, user: null })}
                >
                  ยกเลิก
                </button>
                <button
                  type="button"
                  className="admin-modal-btn danger-btn"
                  onClick={handleDeleteUser}
                >
                  ยืนยันลบถาวร
                </button>
              </div>
            </div>
          </div>
        )}

      </div>
    </div>
  );
};

export default Manageusers;

import React, { useState, useEffect, useMemo } from 'react';
import {
  Search,
  X,
  User,
  Mail,
  Check,
  FileText,
  Loader2,
  AlertTriangle,
  Inbox,
  Clock,
  ShieldCheck,
  ChevronLeft,
  ChevronRight,
  Table,
  LayoutGrid,
  Ban,
} from 'lucide-react';
import './WriterRequestsPage.css';

const API_BASE_URL = (import.meta.env.VITE_API_BASE_URL || '').replace(/\/$/, '');

// ป้ายกำกับแท็บกรอง
const FILTER_TABS = [
  { key: 'all', label: 'ทั้งหมด' },
  { key: 'pending', label: 'รอตรวจสอบ' },
  { key: 'approved', label: 'อนุมัติแล้ว' },
  { key: 'rejected', label: 'ปฏิเสธแล้ว' },
];

// ข้อความ + คลาส badge ตามสถานะจริงของคำขอ (เดิมโค้ดเก่า hardcode เป็น "pending" เสมอ)
const STATUS_INFO = {
  pending: { label: 'รอตรวจสอบ', className: 'wr-badge-pending' },
  approved: { label: 'อนุมัติแล้ว', className: 'wr-badge-approved' },
  rejected: { label: 'ปฏิเสธแล้ว', className: 'wr-badge-rejected' },
};

const EMPTY_MESSAGE = {
  all: 'ยังไม่มีคำขอสมัครนักเขียนในระบบ',
  pending: 'ไม่มีคำขอที่รอตรวจสอบในตอนนี้',
  approved: 'ไม่มีคำขอที่อนุมัติแล้ว',
  rejected: 'ไม่มีคำขอที่ถูกปฏิเสธ',
};

// ⚠️ Safety-net: bio ที่กรอกผ่านฟอร์ม rich-text อาจมี HTML/สคริปต์ติดมาได้
// เดิมหน้านี้ใช้ dangerouslySetInnerHTML แสดง bio ตรง ๆ ซึ่งเสี่ยง XSS
// จึงตัด tag ออกก่อนแสดงผลเสมอ เหมือนที่ทำในหน้ารายงาน
const stripHtml = (text) => {
  if (!text) return text;
  return text.replace(/<[^>]*>/g, '').trim();
};

const parseContactInfo = (raw) => {
  if (!raw) return {};
  if (typeof raw === 'object' && !Array.isArray(raw)) return raw;
  if (typeof raw !== 'string') return {};
  const s = raw.trim();
  if (!s) return {};
  if (s.startsWith('{') || s.startsWith('[')) {
    try { return JSON.parse(s); } catch (_) {}
  }
  return { contact_required: s, primary_contact: s };
};

// ป้ายกำกับภาษาไทยสำหรับ key ที่พบบ่อย ถ้าไม่รู้จัก key ไหนก็ใช้ชื่อ key เดิมแทน
const CONTACT_KEY_LABELS = {
  primary_contact: 'ช่องทางหลัก',
  secondary_contact: 'ช่องทางรอง',
  contact_required: 'ช่องทางหลัก',
  contact_optional: 'ช่องทางรอง',
  twitter: 'Twitter / X',
  facebook: 'Facebook',
  website: 'เว็บไซต์',
  line: 'Line',
  discord: 'Discord',
  instagram: 'Instagram',
};

const contactKeyLabel = (key) => CONTACT_KEY_LABELS[key] || key;
const getInitial = (name) => {
  const trimmed = (name || '').trim();
  return trimmed ? trimmed.charAt(0).toUpperCase() : '?';
};

// แสดงรูปโปรไฟล์จริงถ้า backend ส่ง url มาให้ (เผื่อไว้สำหรับตอนที่ backend เพิ่ม field นี้)
// ถ้าไม่มี url หรือโหลดรูปไม่สำเร็จ จะ fallback กลับไปเป็นวงกลมตัวอักษรย่อเหมือนเดิมทุกอย่าง
const UserAvatar = ({ src, name, className }) => {
  const [broken, setBroken] = useState(false);
  if (src && !broken) {
    return (
      <img
        src={src}
        alt={displayName(name)}
        className={className}
        onError={() => setBroken(true)}
      />
    );
  }
  return <div className={className}>{getInitial(name)}</div>;
};

const displayName = (name) => name || 'ไม่ทราบชื่อผู้ใช้';

// ─────────────────────────────────────────────
//  โมดัลยืนยันการอนุมัติ / ปฏิเสธ
// ─────────────────────────────────────────────
const ActionConfirmModal = ({ isOpen, action, userName, reason, onReasonChange, busy, error, onConfirm, onCancel }) => {
  if (!isOpen) return null;

  const isApprove = action === 'approve';

  return (
    <div className="wr-modal-overlay" onClick={() => !busy && onCancel()}>
      <div className="wr-modal" onClick={(e) => e.stopPropagation()}>
        <div className="wr-modal__header">
          <div>
            <div className="wr-modal__eyebrow">ยืนยันการดำเนินการ</div>
            <div className="wr-modal__heading">
              {isApprove ? 'ยืนยันการอนุมัติเป็นนักเขียน' : 'ยืนยันการปฏิเสธคำขอ'}
            </div>
          </div>
          <button className="wr-modal__close" onClick={onCancel} disabled={busy} aria-label="ปิดหน้าต่าง">
            <X size={16} />
          </button>
        </div>

        <div className="wr-confirm-body">
          {isApprove ? (
            <>คุณแน่ใจหรือไม่ว่าต้องการอนุมัติ <strong>"{userName}"</strong> ให้เป็นนักเขียนในระบบ ผู้ใช้จะได้รับสิทธิ์เขียนนิยายทันที</>
          ) : (
            <>คุณแน่ใจหรือไม่ว่าต้องการปฏิเสธคำขอสมัครของ <strong>"{userName}"</strong> การดำเนินการนี้ไม่สามารถย้อนกลับได้</>
          )}
        </div>

        {!isApprove && (
          <div className="wr-confirm-body" style={{ paddingTop: 0 }}>
            <label className="wr-modal__info-label" htmlFor="rejection-reason" style={{ display: 'block', marginBottom: 6, fontWeight: 700 }}>
              เหตุผลที่ปฏิเสธ <span style={{ color: '#dc2626' }}>*</span>
            </label>
            <textarea
              id="rejection-reason"
              className="wr-search-input"
              style={{ width: '100%', borderRadius: 10, minHeight: 72, resize: 'vertical', padding: 10 }}
              placeholder="เช่น ข้อมูลไม่ครบถ้วน, แนะนำตัวไม่ชัดเจน, ..."
              value={reason}
              onChange={(e) => onReasonChange(e.target.value)}
              disabled={busy}
            />
          </div>
        )}

        <div className="wr-modal__body">
          {error && (
            <div className="wr-modal__error">
              <AlertTriangle size={14} /> {error}
            </div>
          )}

          <div className="wr-modal__actions">
            <button
              type="button"
              className="wr-modal__action-btn wr-btn-action--cancel"
              onClick={onCancel}
              disabled={busy}
            >
              <span>ยกเลิก</span>
            </button>
            <button
              type="button"
              className={`wr-modal__action-btn ${isApprove ? 'wr-btn-action--approve' : 'wr-btn-action--confirm-reject'}`}
              onClick={onConfirm}
              disabled={busy}
            >
              {busy ? (
                <Loader2 size={15} className="spin" />
              ) : isApprove ? (
                <Check size={15} />
              ) : (
                <Ban size={15} />
              )}
              <span>{isApprove ? 'ยืนยันอนุมัติ' : 'ยืนยันปฏิเสธ'}</span>
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

// ─────────────────────────────────────────────
//  โมดัลดูรายละเอียดใบสมัคร
// ─────────────────────────────────────────────
const RequestDetailModal = ({ isOpen, user, onCancel, onApprove, onReject }) => {
  if (!isOpen || !user) return null;

  const contactInfo = parseContactInfo(user.contact_info);
  // แสดงทุก key ที่มีค่าจริงใน contact_info แทนการเดาชื่อ key เจาะจง
  // เพราะข้อมูลเก่าในระบบใช้ชื่อ key ไม่ตรงกันเลย (primary_contact, contact_required, twitter, ...)
  const contactEntries = Object.entries(contactInfo || {}).filter(
    ([key, value]) => key !== 'genres' && value !== null && value !== undefined && String(value).trim() !== ''
  );
  const writerData = {
    fullName: user.name_lastname || 'ไม่ระบุ',
    penName: user.pen_name || displayName(user.username),
    email: user.email_writer || displayName(user.username),
    bio: stripHtml(user.bio) || 'ผู้สมัครยังไม่ได้กรอกข้อมูลแนะนำตัว',
    genres: user.genres || contactInfo.genres || [],
  };

  const previousApplication = user.previous_application;
  const previousContactInfo = parseContactInfo(previousApplication?.contact_info);
  const formatContactInfo = (info) => Object.entries(info || {})
    .filter(([key, value]) => key !== 'genres' && value !== null && value !== undefined && String(value).trim() !== '')
    .map(([key, value]) => `${contactKeyLabel(key)}: ${String(value)}`)
    .join(' | ');
  const currentContactSummary = formatContactInfo(contactInfo);
  const previousContactSummary = formatContactInfo(previousContactInfo);
  const currentGenres = (writerData.genres || []).map(String).sort().join(', ');
  const previousGenres = (previousApplication?.genres || previousContactInfo.genres || []).map(String).sort().join(', ');
  const changedFields = previousApplication ? [
    ['ชื่อ - นามสกุล', previousApplication.name_lastname, writerData.fullName],
    ['นามปากกา', previousApplication.pen_name, writerData.penName],
    ['อีเมลที่ใช้สมัคร', previousApplication.email_writer, writerData.email],
    ['แนะนำตัว', stripHtml(previousApplication.bio), writerData.bio],
    ['ประเภทนิยายที่สนใจเขียน', previousGenres, currentGenres],
    ['ช่องทางติดต่อ', previousContactSummary, currentContactSummary],
  ].filter(([, previousValue, currentValue]) => String(previousValue || '').trim() !== String(currentValue || '').trim()) : [];

  const statusInfo = STATUS_INFO[user.status] || STATUS_INFO.pending;
  const isPending = user.status === 'pending' || !user.status;

  return (
    <div className="wr-modal-overlay" onClick={onCancel}>
      <div className="wr-modal wr-modal--lg" onClick={(e) => e.stopPropagation()}>
        <div className="wr-modal__header">
          <div>
            <div className="wr-modal__eyebrow">ใบสมัครนักเขียน · {displayName(user.username)}</div>
            <div className="wr-modal__heading">รายละเอียดคำขอ</div>
          </div>
          <button className="wr-modal__close" onClick={onCancel} aria-label="ปิดหน้าต่าง">
            <X size={16} />
          </button>
        </div>

        <div className="wr-modal__body">
          {user.previous_attempt_count > 0 && (
            <div className="wr-reapply-notice">
              <AlertTriangle size={22} className="wr-notice-icon" />
              <div className="wr-reapply-notice__content">
                <div className="wr-reapply-notice__title">
                  สมัครซ้ำครั้งที่ {user.previous_attempt_count + 1} — เคยถูกปฏิเสธมาก่อน
                </div>
                {user.previous_rejection_reason && (
                  <div className="wr-reapply-notice__reason">
                    <strong>เหตุผลที่เคยถูกปฏิเสธ:</strong> {user.previous_rejection_reason}
                  </div>
                )}
              </div>
            </div>
          )}

          {changedFields.length > 0 && (
            <div className="wr-reapply-changes">
              <div className="wr-reapply-changes__title">สิ่งที่แก้ไขจากใบสมัครครั้งก่อน</div>
              {changedFields.map(([label, previousValue, currentValue]) => (
                <div className="wr-reapply-change" key={label}>
                  <div className="wr-reapply-change__label">{label}</div>
                  <div className="wr-reapply-change__values">
                    <div><span>เดิม:</span> {String(previousValue || 'ไม่ได้ระบุ')}</div>
                    <div><span>ปัจจุบัน:</span> {String(currentValue || 'ไม่ได้ระบุ')}</div>
                  </div>
                </div>
              ))}
            </div>
          )}

          <div className="wr-modal__profile-row">
            <UserAvatar
              src={user.avatar_url || user.pic_profile}
              name={user.username}
              className="wr-modal__avatar"
            />
            <div>
              <div className="wr-modal__profile-name">{writerData.penName}</div>
              <div className="wr-modal__profile-sub">ชื่อผู้ใช้: {displayName(user.username)}</div>
            </div>
            <span className={`status-badge status-badge--lg status-${user.status === 'approved' ? 'active' : user.status === 'rejected' ? 'suspended' : 'pending'}`} style={{ marginLeft: 'auto' }}>
              <span className="status-dot"></span>
              {statusInfo.label}
            </span>
          </div>

          <div>
            <div className="wr-modal__section-title">ข้อมูลนักเขียน</div>
            <div className="wr-modal__info-row">
              <span className="wr-modal__info-label">ชื่อ - นามสกุล</span>
              <span className="wr-modal__info-value">{writerData.fullName}</span>
            </div>
            <div className="wr-modal__info-row">
              <span className="wr-modal__info-label">นามปากกา</span>
              <span className="wr-modal__info-value">{writerData.penName}</span>
            </div>
            <div className="wr-modal__info-row">
              <span className="wr-modal__info-label">อีเมลที่ใช้สมัคร</span>
              <span className="wr-modal__info-value">{writerData.email}</span>
            </div>
          </div>

          <div>
            <div className="wr-modal__section-title">แนะนำตัว</div>
            <div className="wr-modal__bio">{writerData.bio}</div>
          </div>

          <div>
            <div className="wr-modal__section-title">ประเภทนิยายที่สนใจเขียน</div>
            {writerData.genres.length > 0 ? (
              <div className="wr-modal__genres">
                {writerData.genres.map((genre, idx) => (
                  <span key={idx} className="category-badge-unified">{genre}</span>
                ))}
              </div>
            ) : (
              <div className="wr-modal__empty-note">ผู้สมัครยังไม่ได้ระบุประเภทนิยาย</div>
            )}
          </div>

          <div>
            <div className="wr-modal__section-title">ช่องทางติดต่อ</div>
            {contactEntries.length > 0 ? (
              contactEntries.map(([key, value]) => (
                <div className="wr-modal__info-row" key={key}>
                  <span className="wr-modal__info-label">{contactKeyLabel(key)}</span>
                  <span className="wr-modal__info-value">
                    {String(value).startsWith('http') ? (
                      <a href={value} target="_blank" rel="noopener noreferrer">{value}</a>
                    ) : (
                      String(value)
                    )}
                  </span>
                </div>
              ))
            ) : (
              <div className="wr-modal__empty-note">ผู้สมัครยังไม่ได้ระบุช่องทางติดต่อ</div>
            )}
          </div>

          {!isPending && (
            <div>
              <div className="wr-modal__section-title">ประวัติการตัดสินใจ</div>
              <div className="wr-modal__info-row">
                <span className="wr-modal__info-label">ผลการตัดสินใจ</span>
                <span className="wr-modal__info-value">
                  <span className={`status-badge status-badge--lg status-${user.status === 'approved' ? 'active' : user.status === 'rejected' ? 'suspended' : 'pending'}`}>
                    <span className="status-dot"></span>
                    {statusInfo.label}
                  </span>
                </span>
              </div>
              <div className="wr-modal__info-row">
                <span className="wr-modal__info-label">
                  {user.status === 'approved' ? 'อนุมัติเมื่อ' : 'ปฏิเสธเมื่อ'}
                </span>
                <span className="wr-modal__info-value">
                  {(() => {
                    const at = user.status === 'approved' ? user.approved_at : user.rejected_at;
                    return at ? new Date(at).toLocaleString('th-TH') : 'ไม่มีข้อมูล (คำขอเก่าก่อนระบบเก็บ log)';
                  })()}
                </span>
              </div>
              <div className="wr-modal__info-row">
                <span className="wr-modal__info-label">ดำเนินการโดย</span>
                <span className="wr-modal__info-value">
                  {user.acted_by_admin_username || (user.acted_by_admin_id ? `แอดมิน ID: ${user.acted_by_admin_id}` : 'ไม่มีข้อมูล')}
                </span>
              </div>
              {user.status === 'rejected' && (
                <div className="wr-modal__info-row">
                  <span className="wr-modal__info-label">เหตุผลที่ปฏิเสธ</span>
                  <span className="wr-modal__info-value" style={{ color: '#dc2626' }}>{stripHtml(user.rejection_reason) || 'ไม่ได้ระบุเหตุผล'}</span>
                </div>
              )}
            </div>
          )}

          {isPending ? (
            <div className="wr-modal__actions">
              <button
                className="wr-modal__action-btn wr-btn-action--reject"
                onClick={() => onReject(user)}
              >
                <X size={14} /> ปฏิเสธคำขอ
              </button>
              <button
                className="wr-modal__action-btn wr-btn-action--approve"
                onClick={() => onApprove(user)}
              >
                <Check size={14} /> อนุมัติเป็นนักเขียน
              </button>
            </div>
          ) : (
            <div className="wr-modal__empty-note">คำขอนี้ถูกตรวจสอบและตัดสินใจไปแล้ว</div>
          )}
        </div>
      </div>
    </div>
  );
};

// ─────────────────────────────────────────────
//  Main Component
// ─────────────────────────────────────────────

const WriterRequestsPage = () => {
  const [requests, setRequests] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);

  const [filterTab, setFilterTab] = useState('pending');
  const [searchTerm, setSearchTerm] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage, setItemsPerPage] = useState(10);
  const [viewMode, setViewMode] = useState('table'); // 'table' | 'card'

  // รองรับทั้ง response แบบเก่า (array ตรงๆ) และแบบใหม่ ({data, total, counts})
  // เผื่อ backend ยังทำ pagination จริงไม่เสร็จ จะได้ไม่พังระหว่างนี้
  const [serverPaginated, setServerPaginated] = useState(false);
  const [totalCount, setTotalCount] = useState(0);
  const [counts, setCounts] = useState({ pending: 0, approved: 0, rejected: 0 });

  const [detailModal, setDetailModal] = useState({ isOpen: false, user: null });
  const [confirmModal, setConfirmModal] = useState({
    isOpen: false,
    writerId: null,
    action: '',
    userName: '',
    reason: '',
    busy: false,
    error: '',
  });

  // 🎯 ดึง "จำนวนรวมทุกสถานะ" แยกต่างหาก ไม่ผูกกับ filterTab ที่กำลังดูอยู่
  // จาก network response จริงที่เห็น: backend คืนค่าเป็น array ตรงๆ เสมอ ไม่เคยมี field `counts`
  // แนบมาด้วยเลย ฉะนั้นวิธีที่แม่นยำและไม่ต้องเดาโครงสร้าง backend คือ ขอข้อมูลแบบไม่กรอง status
  // มาทั้งหมดครั้งเดียว แล้วนับเองฝั่ง client ตรงๆ จากลิสต์จริงที่ได้มา
  const fetchCounts = async () => {
    try {
      const token = localStorage.getItem('token');
      const params = new URLSearchParams();
      params.set('limit', '1000'); // ขอมาทั้งหมดเพื่อนับเองให้ครบทุกสถานะ ไม่พึ่ง field counts ที่ backend ไม่ได้ส่งมา

      const res = await fetch(`${API_BASE_URL}/api/admin/writers/requests?${params.toString()}`, {
        method: 'GET',
        headers: {
          Authorization: `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
      });
      if (!res.ok) return;
      const data = await res.json().catch(() => null);

      // รองรับทั้งกรณี backend คืน array ตรงๆ (ตามที่เห็นจริง) และกรณีในอนาคตที่อาจห่อเป็น {data:[...]}
      const list = Array.isArray(data) ? data : Array.isArray(data?.data) ? data.data : [];

      setCounts({
        pending: list.filter((r) => !r.status || r.status === 'pending').length,
        approved: list.filter((r) => r.status === 'approved').length,
        rejected: list.filter((r) => r.status === 'rejected').length,
      });
    } catch (err) {
      console.warn('Failed to load writer request counts:', err);
    }
  };

  const fetchRequests = async (page = currentPage, attempt = 0) => {
    setIsLoading(true);
    setError(null);
    try {
      const token = localStorage.getItem('token');
      const term = searchTerm.trim();
      const params = new URLSearchParams();

      // ถ้ากำลังค้นหาอยู่ ยังไม่มี search param ฝั่ง backend รองรับ
      // เลยขอมาเยอะๆ ครั้งเดียวแล้วกรอง/แบ่งหน้าเองฝั่ง client แทน (ยอมรับ trade-off นี้ไปก่อน)
      if (term || filterTab === 'all') {
        params.set('limit', '1000');
      } else {
        params.set('status', filterTab);
        // Backend ยังตอบกลับเป็น array ตรงๆ ไม่มี total/page metadata
        // จึงโหลดรายการของสถานะนั้นครบก่อน แล้วแบ่งหน้าใน frontend
        params.set('limit', '1000');
      }

      const res = await fetch(`${API_BASE_URL}/api/admin/writers/requests?${params.toString()}`, {
        method: 'GET',
        headers: {
          Authorization: `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
      });
      if (!res.ok) throw new Error('ไม่สามารถดึงคำขอได้');
      const data = await res.json().catch(() => null);

      if (data === null || data === undefined) {
        // 🩹 backend คืนค่า "null" ตรงๆ ตอนลิสต์ที่กรองอยู่ว่างเปล่า (เช่น ไม่มีคำขอ pending เลย)
        // ค่านี้หมายถึง "รายการที่กำลังดูอยู่ว่าง" เท่านั้น ไม่ได้แปลว่านับรวมทุกสถานะเป็น 0
        // จึงรีเซ็ตแค่ requests/total ของ "มุมมองปัจจุบัน" แต่ไม่แตะ counts รวม (ให้ fetchCounts ดูแลแยก)
        //
        // สำคัญ: serverPaginated ต้องคำนวณแบบเดียวกับ branch ปกติ (!term) ห้าม hardcode เป็น false
        // เพราะถ้า false การ์ดสถิติ (pendingCount/approvedCount/rejectedCount) จะสลับไปคำนวณจาก
        // requests.filter(...) ซึ่งตอนนี้เป็น [] แทนที่จะใช้ counts ที่ถูกต้อง — นี่คือสาเหตุที่พอกด
        // tab ที่ว่างเปล่า การ์ดอื่นๆ ก็เห็นเป็น 0 ไปด้วยทั้งที่ fetchCounts ตั้งค่าไว้ถูกต้องแล้ว
        setRequests([]);
        setTotalCount(0);
        setServerPaginated(!term);
      } else if (Array.isArray(data)) {
        // Backend เวอร์ชันเก่า (ยังไม่ทำ pagination จริง) — ใช้วิธีเดิม โหลดหมดมากรอง/แบ่งหน้าเอง
        setRequests(data);
        setServerPaginated(false);
      } else {
        setRequests(data.data || []);
        setTotalCount(data.total || 0);
        // หมายเหตุ: ไม่ setCounts จากตรงนี้ เพราะ response นี้ถูกกรองด้วย status filter ของ tab ปัจจุบัน
        // ถ้า backend คำนวณ counts จาก query ที่กรองแล้ว จะได้ตัวเลขที่ไม่ใช่ยอดรวมจริงของสถานะอื่น
        // (เช่น ดู tab "ปฏิเสธ" แล้ว counts.approved กลายเป็น 0) ตัวเลขบนการ์ดสถิติจึงใช้ fetchCounts()
        // ซึ่งยิงแบบไม่กรอง status เป็นแหล่งความจริงเดียวแทน
        // ตอนค้นหาอยู่ ถือว่าไม่ใช่ server-paginated แล้ว (เพราะขอข้อมูลมาเยอะๆ ครั้งเดียว)
        setServerPaginated(!term);
      }
      setIsLoading(false);
    } catch (err) {
      console.error(`Failed to load writer requests (attempt ${attempt + 1}):`, err);

      // 🩹 บั๊กที่เจอ: ตอนเพิ่งเข้าหน้านี้ครั้งแรก บางทีคำขอแรกจะพลาดแบบชั่วคราว
      // (เช่น token ใน localStorage ยังตั้งไม่เสร็จ / เครือข่ายสะดุดจังหวะแรก)
      // แล้วหน้าก็ค้างอยู่ที่ error เดิมพร้อมตัวเลข 0 ไปตลอด จนกว่าจะมีอะไรมาสั่ง fetch ใหม่เอง
      // (เช่นกดการ์ดสถิติ) ซึ่งพอลองใหม่มันก็ผ่านปกติ — ของจริงไม่ได้หายไปไหน แค่ไม่มีการลองซ้ำอัตโนมัติ
      // จึงเพิ่ม retry อัตโนมัติสั้นๆ ก่อน ค่อย fallback เป็นข้อความ error ให้ผู้ใช้กดลองเองทีหลัง
      if (attempt < 2) {
        setTimeout(() => fetchRequests(page, attempt + 1), 700 * (attempt + 1));
        return;
      }

      setError('ไม่สามารถโหลดคำขอสมัครนักเขียนได้ในขณะนี้ กรุณาลองใหม่อีกครั้ง');
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchRequests(currentPage);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [filterTab, currentPage, searchTerm]);

  // ดึง counts รวมครั้งเดียวตอนเข้าเพจ ไม่ต้องรันซ้ำตอนสลับ tab (fetchRequests ที่มี counts มาด้วยจะช่วยอัปเดตให้เองอยู่แล้ว)
  useEffect(() => {
    fetchCounts();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const runAction = async (writerId, action, reason) => {
    if (action === 'reject' && !reason.trim()) {
      setConfirmModal((prev) => ({
        ...prev,
        busy: false,
        error: 'กรุณาระบุเหตุผลในการปฏิเสธคำขอ เพื่อให้ผู้สมัครรับทราบและนำไปแก้ไข',
      }));
      return;
    }
    setConfirmModal((prev) => ({ ...prev, busy: true, error: '' }));
    try {
      const token = localStorage.getItem('token');
      const endpoint = action === 'approve' ? 'approve' : 'reject';
      const res = await fetch(`${API_BASE_URL}/api/admin/writers/${endpoint}?writer_id=${writerId}`, {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
        body: action === 'reject' ? JSON.stringify({ rejection_reason: reason || '' }) : undefined,
      });
      if (!res.ok) {
        const errData = await res.json().catch(() => null);
        throw new Error(errData?.error?.message || errData?.message || (action === 'approve' ? 'ไม่สามารถอนุมัติคำขอได้' : 'ไม่สามารถปฏิเสธคำขอได้'));
      }
      setConfirmModal({ isOpen: false, writerId: null, action: '', userName: '', reason: '', busy: false, error: '' });
      setDetailModal({ isOpen: false, user: null });
      await fetchRequests();
      await fetchCounts();
    } catch (err) {
      console.error(`${action} writer failed:`, err);
      setConfirmModal((prev) => ({
        ...prev,
        busy: false,
        error: err.message || 'เกิดข้อผิดพลาด กรุณาลองใหม่อีกครั้ง',
      }));
    }
  };

  const openConfirm = (user, action) => {
    setDetailModal({ isOpen: false, user: null });
    setConfirmModal({
      isOpen: true,
      writerId: user.writer_id,
      action,
      userName: user.pen_name || displayName(user.username),
      reason: '',
      busy: false,
      error: '',
    });
  };

  // การ์ดสถิติใช้ counts ที่ fetchCounts คำนวณจากลิสต์เต็มเสมอ (ไม่ขึ้นกับ tab/หน้าที่กำลังดูอยู่)
  // ไม่สลับไปนับจาก requests อีกต่อไป เพราะ requests คือแค่ข้อมูลของ "หน้าที่กำลังดู" เท่านั้น
  const pendingCount = counts.pending;
  const approvedCount = counts.approved;
  const rejectedCount = counts.rejected;

  const filteredRequests = useMemo(() => {
    // server-paginated แล้ว: requests ที่ได้มาคือหน้าปัจจุบันที่ backend กรอง/ตัดมาให้แล้ว ใช้ตรงๆ ได้เลย
    if (serverPaginated) return requests;

    let list = requests;
    if (filterTab === 'pending') list = list.filter((r) => !r.status || r.status === 'pending');
    else if (filterTab === 'approved') list = list.filter((r) => r.status === 'approved');
    else if (filterTab === 'rejected') list = list.filter((r) => r.status === 'rejected');

    const term = searchTerm.trim().toLowerCase();
    if (term) {
      list = list.filter((r) =>
        (r.username || '').toLowerCase().includes(term) ||
        (r.pen_name || '').toLowerCase().includes(term) ||
        (r.email_writer || '').toLowerCase().includes(term)
      );
    }
    return list;
  }, [requests, filterTab, searchTerm, serverPaginated]);

  const changeFilterTab = (key) => {
    setFilterTab(key);
    setCurrentPage(1);
  };

  const changeSearchTerm = (value) => {
    setSearchTerm(value);
    setCurrentPage(1);
  };

  const totalPages = serverPaginated
    ? Math.max(1, Math.ceil(totalCount / itemsPerPage))
    : Math.max(1, Math.ceil(filteredRequests.length / itemsPerPage));

  const paginatedRequests = useMemo(() => {
    // server-paginated แล้ว: ไม่ต้องตัดซ้ำฝั่ง client อีก backend ตัดมาให้แล้ว
    if (serverPaginated) return filteredRequests;
    const start = (currentPage - 1) * itemsPerPage;
    return filteredRequests.slice(start, start + itemsPerPage);
  }, [filteredRequests, currentPage, serverPaginated]);

  return (
    <div className="wr-container">
      <div className="wr-content">
        <div className="wr-header">
          <h1 className="wr-title">อนุมัตินักเขียน</h1>
          <p className="wr-subtitle">ตรวจสอบและจัดการคำขอสมัครเป็นนักเขียน</p>
          <svg className="header-branch-accent" viewBox="0 0 200 16" preserveAspectRatio="none" aria-hidden="true">
            <path d="M0 8 H70 M70 8 C 78 8, 78 2, 86 2 H130 M70 8 C 78 8, 78 14, 86 14 H130 M130 2 H200 M130 14 H160" />
          </svg>
        </div>

        {error && (
          <div className="wr-page-error">
            <AlertTriangle size={18} />
            <span>{error}</span>
            <button
              type="button"
              className="wr-page-error-retry"
              onClick={() => fetchRequests(currentPage)}
            >
              ลองใหม่
            </button>
          </div>
        )}

        {/* การ์ดสรุปสถิติ — กดเพื่อกรองตารางตามสถานะนั้นได้เลย */}
        <div className="wr-stats-grid">
          <button
            type="button"
            className={`wr-stat-card wr-stat-card--pending ${filterTab === 'pending' ? 'wr-stat-card--active' : ''}`}
            onClick={() => changeFilterTab('pending')}
            aria-pressed={filterTab === 'pending'}
          >
            <div className="wr-stat-card-icon"><Clock size={20} /></div>
            <div>
              <div className="wr-stat-label">รอตรวจสอบ</div>
              <div className="wr-stat-value">{pendingCount.toLocaleString()}</div>
            </div>
          </button>
          <button
            type="button"
            className={`wr-stat-card wr-stat-card--approved ${filterTab === 'approved' ? 'wr-stat-card--active' : ''}`}
            onClick={() => changeFilterTab('approved')}
            aria-pressed={filterTab === 'approved'}
          >
            <div className="wr-stat-card-icon"><ShieldCheck size={20} /></div>
            <div>
              <div className="wr-stat-label">อนุมัติแล้ว</div>
              <div className="wr-stat-value">{approvedCount.toLocaleString()}</div>
            </div>
          </button>
          <button
            type="button"
            className={`wr-stat-card wr-stat-card--rejected ${filterTab === 'rejected' ? 'wr-stat-card--active' : ''}`}
            onClick={() => changeFilterTab('rejected')}
            aria-pressed={filterTab === 'rejected'}
          >
            <div className="wr-stat-card-icon"><X size={20} /></div>
            <div>
              <div className="wr-stat-label">ปฏิเสธแล้ว</div>
              <div className="wr-stat-value">{rejectedCount.toLocaleString()}</div>
            </div>
          </button>
        </div>

        {/* แท็บกรอง + ค้นหา */}
        <div className="wr-toolbar">
          <div className="wr-filter-tabs" role="tablist" aria-label="กรองรายการตามสถานะ">
            {FILTER_TABS.map((tab) => (
              <button
                key={tab.key}
                role="tab"
                aria-selected={filterTab === tab.key}
                className={`wr-filter-tab-btn ${filterTab === tab.key ? 'active' : ''}`}
                onClick={() => changeFilterTab(tab.key)}
              >
                {tab.label}
              </button>
            ))}
          </div>

          <div className="wr-search-and-clear">
            <div className="wr-search-box">
              <Search size={15} />
              <input
                type="text"
                className="wr-search-input"
                placeholder="ค้นหาชื่อผู้ใช้ นามปากกา หรืออีเมล..."
                value={searchTerm}
                onChange={(e) => changeSearchTerm(e.target.value)}
              />
            </div>

            {/* ปุ่มปรับมุมมอง (ตารางเลื่อนข้าง / การ์ดข้อมูล) */}
            <div className="wr-view-toggle" role="group" aria-label="ปรับมุมมองการแสดงผล">
              <button
                type="button"
                className={`wr-view-btn ${viewMode === 'table' ? 'active' : ''}`}
                onClick={() => setViewMode('table')}
                title="แสดงผลแบบตารางเลื่อนข้าง (Scrollable Table)"
              >
                <Table size={15} />
                <span>ตาราง</span>
              </button>
              <button
                type="button"
                className={`wr-view-btn ${viewMode === 'card' ? 'active' : ''}`}
                onClick={() => setViewMode('card')}
                title="แสดงผลแบบการ์ดข้อมูล (Mobile Cards)"
              >
                <LayoutGrid size={15} />
                <span>การ์ด</span>
              </button>
            </div>
          </div>
        </div>

        {/* ตารางรายการ */}
        <div className="wr-table-card">
          {isLoading ? (
            <div className="wr-table-loading">
              <Loader2 size={20} className="spin" />
              <span>กำลังโหลดคำขอ...</span>
            </div>
          ) : filteredRequests.length === 0 ? (
            <div className="wr-table-empty">
              <Inbox size={26} />
              <strong>{searchTerm ? 'ไม่พบผลลัพธ์ที่ตรงกับการค้นหา' : 'ไม่มีคำขอ'}</strong>
              <span>{searchTerm ? `ลองค้นหาด้วยคำอื่น หรือล้างช่องค้นหา` : EMPTY_MESSAGE[filterTab]}</span>
            </div>
          ) : (
            <>
              {viewMode === 'table' ? (
                /* Scrollable Table View */
                <div className="wr-table-responsive">
              <table className="wr-table">
                <thead>
                  <tr>
                    <th className="text-center" style={{ width: "5%", minWidth: "45px" }}>#</th>
                    <th style={{ width: "22%", minWidth: "190px" }}>ผู้สมัคร</th>
                    <th style={{ width: "15%", minWidth: "130px" }}>นามปากกา</th>
                    <th style={{ width: "20%", minWidth: "175px" }}>อีเมลที่ใช้สมัคร</th>
                    <th className="text-center" style={{ width: "12%", minWidth: "110px" }}>สถานะ</th>
                    <th className="text-center" style={{ width: "26%", minWidth: "290px" }}>การจัดการ</th>
                  </tr>
                </thead>
                <tbody>
                  {paginatedRequests.map((req, index) => {
                    const statusInfo = STATUS_INFO[req.status] || STATUS_INFO.pending;
                    const isPending = !req.status || req.status === 'pending';
                    const statusType = req.status === 'approved' ? 'active' : req.status === 'rejected' ? 'suspended' : 'pending';
                    return (
                      <tr key={req.writer_id}>
                        <td className="wr-row-num">{(currentPage - 1) * itemsPerPage + index + 1}</td>
                        <td>
                          <div className="wr-user-info-cell">
                            <UserAvatar
                              src={req.pic_profile || req.avatar_url}
                              name={req.username}
                              className="wr-user-avatar-small"
                            />
                            <span className="wr-username-text">{displayName(req.username)}</span>
                            {req.previous_attempt_count > 0 && (
                              <span className="wr-reapply-badge" title="เคยยื่นสมัครมาก่อนหน้านี้">
                                สมัครครั้งที่ {req.previous_attempt_count + 1}
                              </span>
                            )}
                          </div>
                        </td>
                        <td>{req.pen_name || <span className="wr-subtext">ไม่ระบุ</span>}</td>
                        <td>
                          {req.email_writer ? (
                            <span>{req.email_writer}</span>
                          ) : (
                            <span className="wr-subtext">ไม่ระบุ</span>
                          )}
                        </td>
                        <td className="text-center">
                          <span className={`status-badge status-${statusType}`}>
                            <span className="status-dot"></span>
                            {statusInfo.label}
                          </span>
                        </td>
                        <td className="actions-cell text-center">
                          <div className="wr-btn-group action-cell-content">
                            <button
                              className="btn-icon-action btn-detail"
                              onClick={() => setDetailModal({ isOpen: true, user: req })}
                              title="ดูรายละเอียดใบสมัคร"
                            >
                              <FileText size={14} />
                              <span>ดูรายละเอียด</span>
                            </button>

                            {isPending && (
                              <>
                                <button
                                  className="btn-icon-action btn-approve"
                                  onClick={() => openConfirm(req, 'approve')}
                                  title="อนุมัติเป็นนักเขียน"
                                >
                                  <Check size={14} />
                                  <span>อนุมัติ</span>
                                </button>

                                <button
                                  className="btn-icon-action btn-reject"
                                  onClick={() => openConfirm(req, 'reject')}
                                  title="ปฏิเสธคำขอ"
                                >
                                  <X size={14} />
                                  <span>ปฏิเสธ</span>
                                </button>
                              </>
                            )}
                          </div>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          ) : (
            /* Mobile Cards View */
            <div className="wr-cards-mobile wr-cards-active-view">
                {paginatedRequests.map((req, index) => {
                  const statusInfo = STATUS_INFO[req.status] || STATUS_INFO.pending;
                  const isPending = !req.status || req.status === 'pending';
                  const statusType = req.status === 'approved' ? 'active' : req.status === 'rejected' ? 'suspended' : 'pending';
                  return (
                    <div key={req.writer_id} className="wr-card-mobile">
                      <div className="wr-card-mobile__header">
                        <UserAvatar
                          src={req.pic_profile || req.avatar_url}
                          name={req.username}
                          className="wr-user-avatar-small"
                        />
                        <div className="wr-card-mobile__user-details">
                          <div className="wr-card-mobile__name">{displayName(req.username)}</div>
                          <div className="wr-card-mobile__pen-name">นามปากกา: <strong>{req.pen_name || 'ไม่ระบุ'}</strong></div>
                        </div>
                        <span className={`status-badge status-${statusType}`}>
                          <span className="status-dot"></span>
                          {statusInfo.label}
                        </span>
                      </div>

                      {req.previous_attempt_count > 0 && (
                        <div className="wr-card-mobile__reapply">
                          <span className="wr-reapply-badge">
                            สมัครครั้งที่ {req.previous_attempt_count + 1} — เคยถูกปฏิเสธมาก่อน
                          </span>
                        </div>
                      )}

                      <div className="wr-card-mobile__info">
                        <div><strong>อีเมล:</strong> {req.email_writer || 'ไม่ระบุ'}</div>
                      </div>

                      <div className="wr-card-mobile__actions">
                        <button
                          className="btn-icon-action btn-detail"
                          onClick={() => setDetailModal({ isOpen: true, user: req })}
                        >
                          <FileText size={14} />
                          <span>ดูรายละเอียด</span>
                        </button>

                        {isPending && (
                          <>
                            <button
                              className="btn-icon-action btn-approve"
                              onClick={() => openConfirm(req, 'approve')}
                            >
                              <Check size={14} />
                              <span>อนุมัติ</span>
                            </button>

                            <button
                              className="btn-icon-action btn-reject"
                              onClick={() => openConfirm(req, 'reject')}
                            >
                              <X size={14} />
                              <span>ปฏิเสธ</span>
                            </button>
                          </>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>
              )}

              {/* Footer Pagination Template (Image 2 style) */}
              <div className="admin-table-footer">
                <div className="admin-table-footer-left">
                  <span className="admin-table-info-text">
                    แสดง <strong>{filteredRequests.length === 0 ? 0 : (currentPage - 1) * itemsPerPage + 1} – {Math.min(currentPage * itemsPerPage, filteredRequests.length)}</strong> จาก <strong>{filteredRequests.length}</strong> รายการ
                  </span>

                  <div className="admin-table-per-page">
                    <span>แสดงต่อหน้า</span>
                    <select
                      className="admin-per-page-select"
                      value={itemsPerPage}
                      onChange={(e) => {
                        setItemsPerPage(Number(e.target.value));
                        setCurrentPage(1);
                      }}
                    >
                      <option value={10}>10</option>
                      <option value={20}>20</option>
                      <option value={50}>50</option>
                    </select>
                  </div>
                </div>

                <div className="admin-pagination-img2">
                  <button
                    type="button"
                    className="page-btn-box"
                    onClick={() => setCurrentPage(prev => Math.max(1, prev - 1))}
                    disabled={currentPage === 1}
                  >
                    <ChevronLeft size={16} />
                    <span>ก่อนหน้า</span>
                  </button>

                  <span className="page-indicator-text">
                    หน้า <strong>{currentPage}</strong> จาก <strong>{totalPages}</strong>
                  </span>

                  <button
                    type="button"
                    className="page-btn-box"
                    onClick={() => setCurrentPage(prev => Math.min(totalPages, prev + 1))}
                    disabled={currentPage === totalPages}
                  >
                    <span>ถัดไป</span>
                    <ChevronRight size={16} />
                  </button>
                </div>
              </div>
            </>
          )}
        </div>

        {/* Modals */}
        <RequestDetailModal
          isOpen={detailModal.isOpen}
          user={detailModal.user}
          onCancel={() => setDetailModal({ isOpen: false, user: null })}
          onApprove={(user) => openConfirm(user, 'approve')}
          onReject={(user) => openConfirm(user, 'reject')}
        />

        <ActionConfirmModal
          isOpen={confirmModal.isOpen}
          action={confirmModal.action}
          userName={confirmModal.userName}
          reason={confirmModal.reason}
          onReasonChange={(value) => setConfirmModal((prev) => ({ ...prev, reason: value }))}
          busy={confirmModal.busy}
          error={confirmModal.error}
          onConfirm={() => runAction(confirmModal.writerId, confirmModal.action, confirmModal.reason)}
          onCancel={() =>
            !confirmModal.busy &&
            setConfirmModal({ isOpen: false, writerId: null, action: '', userName: '', reason: '', busy: false, error: '' })
          }
        />
      </div>
    </div>
  );
};

