import React, { useEffect, useMemo, useRef, useState } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import { NovelCardGridSkeleton, ButtonSpinner } from "../../../components/Skeleton";
import "./BookshelfPage.css";
import {
    ArrowLeft,
    Trash2,
    BookOpen,
    Play,
    RotateCw,
    Pencil,
    Clock,
    Eye,
    Heart,
    Bookmark,
    Map,
    X,
} from "lucide-react";

const API_BASE_URL = import.meta.env.VITE_API_BASE_URL || "http://localhost:8080";

const formatNumber = (num) => {
    if (!num) return 0;
    if (num >= 1000000) return (num / 1000000).toFixed(1) + "M+";
    if (num >= 1000) return (num / 1000).toFixed(1) + "k+";
    return num;
};

const THAI_MONTHS_SHORT = [
    "ม.ค.", "ก.พ.", "มี.ค.", "เม.ย.", "พ.ค.", "มิ.ย.",
    "ก.ค.", "ส.ค.", "ก.ย.", "ต.ค.", "พ.ย.", "ธ.ค."
];

const formatThaiDate = (iso) => {
    if (!iso) return "";
    const d = new Date(iso);
    if (isNaN(d.getTime())) return "";
    const day = d.getDate();
    const month = THAI_MONTHS_SHORT[d.getMonth()];
    const year = d.getFullYear() + 543;
    return `${day} ${month} ${year}`;
};

const formatThaiDateTime = (iso) => {
    if (!iso) return "";
    const d = new Date(iso);
    if (isNaN(d.getTime())) return "";
    const day = d.getDate();
    const month = THAI_MONTHS_SHORT[d.getMonth()];
    const year = d.getFullYear() + 543;
    const hours = String(d.getHours()).padStart(2, "0");
    const minutes = String(d.getMinutes()).padStart(2, "0");
    return `${day} ${month} ${year} เวลา ${hours}:${minutes} น.`;
};

const formatLastReadInfo = (book) => {
    if (book.reading_status === "want_to_read") {
        return "";
    }
    if (book.lastReadAt) {
        const dateTimeStr = formatThaiDateTime(book.lastReadAt);
        if (dateTimeStr) return `อ่านล่าสุด ${dateTimeStr}`;
    }
    return "";
};

const FILTER_OPTIONS = [
    { value: "all", label: "ทั้งหมด" },
    { value: "want_to_read", label: "ยังไม่อ่าน" },
    { value: "reading", label: "กำลังอ่าน" },
    { value: "finished", label: "อ่านจบแล้ว" },
];

const formatMinioUrl = (url) => {
    if (!url) return "https://via.placeholder.com/320x420";
    return url.replace("http://minio:9000", "http://localhost:9000");
};

const getBookshelfApiUrl = (userId) => {
    const base = `${API_BASE_URL}/bookshelves`;
    return userId ? `${base}?user_id=${userId}` : base;
};

const extractBookshelfList = (payload) => {
    if (!payload) return [];
    if (Array.isArray(payload)) return payload;

    // Check top-level properties
    if (Array.isArray(payload.bookshelf)) return payload.bookshelf;
    if (Array.isArray(payload.bookshelves)) return payload.bookshelves;
    if (Array.isArray(payload.books)) return payload.books;
    if (Array.isArray(payload.novels)) return payload.novels;
    if (Array.isArray(payload.items)) return payload.items;
    if (Array.isArray(payload.data)) return payload.data;
    if (Array.isArray(payload.results)) return payload.results;

    // Check nested payload.data properties (e.g. { data: { bookshelf: [...] } })
    if (payload.data && typeof payload.data === "object") {
        if (Array.isArray(payload.data.bookshelf)) return payload.data.bookshelf;
        if (Array.isArray(payload.data.bookshelves)) return payload.data.bookshelves;
        if (Array.isArray(payload.data.books)) return payload.data.books;
        if (Array.isArray(payload.data.novels)) return payload.data.novels;
        if (Array.isArray(payload.data.items)) return payload.data.items;
        if (Array.isArray(payload.data.data)) return payload.data.data;
        if (Array.isArray(payload.data.results)) return payload.data.results;
    }

    return [];
};

const normalizeCategoryName = (cat) => {
    if (!cat) return "";
    if (typeof cat === "string") return cat.trim();
    if (typeof cat === "number") return String(cat);
    return String(cat.name || cat.Name || cat.title || cat.label || cat.label_th || "").trim();
};

const stripHtml = (html = "") => {
    if (!html) return "";
    const div = document.createElement("div");
    div.innerHTML = html;
    return (div.textContent || "").trim();
};

const getBookId = (item = {}) => {
    return item.novel_id || item.id || item._id || item.novel?.id || 0;
};

// นิยายจะถือว่า "จบ" ก็ต่อเมื่อตัวนิยายเองถูกทำเครื่องหมายว่าจบแล้วโดยผู้เขียน/ระบบ
// เช่น "completed" / "finished" / "จบแล้ว" เท่านั้น การอ่านถึงฉากล่าสุดที่มีอยู่
// ไม่ได้แปลว่านิยายจบ (นิยายอาจจะยังเขียนไม่จบ หรือฉากล่าสุดไม่ใช่ฉากจบเรื่องจริงๆ)
const NOVEL_COMPLETED_VALUES = new Set([
    "completed",
    "complete",
    "finished",
    "end",
    "completed-published",
    "completed-draft",
    "จบแล้ว",
]);

const isNovelCompleted = (novelStatus) =>
    NOVEL_COMPLETED_VALUES.has(String(novelStatus || "").trim().toLowerCase());

/**
 * สถานะการอ่านของ "ผู้ใช้" ต้องแยกออกจากสถานะของ "นิยาย" ให้ชัดเจน:
 *  - explicitStatus: สถานะการอ่านของผู้ใช้ที่ backend ส่งมาตรงๆ (ถ้ามี ให้เชื่อค่านี้เป็นหลัก)
 *  - novelStatus: สถานะของตัวนิยายเอง (จบแล้ว/ยังเขียนอยู่) — ใช้ตัดสินร่วมกับ reachedEnding เท่านั้น
 *  - reachedEnding: ผู้ใช้อ่านไปถึง "ฉากจบ" ของเส้นทางใดเส้นทางหนึ่งจริงๆ หรือไม่
 *    (ไม่ใช่แค่ "มีฉากล่าสุดที่ยังไม่ได้อ่านต่อ" หรือ "นิยายมี ending อยู่บ้าง")
 *
 * ถ้า backend ยังไม่มี field บอก reachedEnding ตรงๆ ให้ทีม backend เพิ่ม field นี้มาด้วย
 * (เช่น is_ending บน scene ปัจจุบัน) ไม่ควรเดาจาก ending_count ของทั้งเรื่อง เพราะนั่นคือ
 * จำนวน ending ทั้งหมดที่นิยายมี ไม่ใช่ว่าผู้ใช้คนนี้อ่านถึงหรือยัง
 */
const normalizeReadingStatus = ({ explicitStatus, novelStatus, reachedEnding, currentSceneId }) => {
    const raw = String(explicitStatus || "").trim().toLowerCase();
    if (raw === "want_to_read" || raw === "reading" || raw === "finished") {
        return raw;
    }

    if (isNovelCompleted(novelStatus) && reachedEnding) {
        return "finished";
    }

    if (currentSceneId > 0) return "reading";
    return "want_to_read";
};

const normalizeBook = (item) => {
    // สถานะของ "ตัวนิยาย" เอง (จบแล้ว/ยังเขียนอยู่) แยกจากสถานะการอ่านของผู้ใช้
    const novelStatus = item.status || item.novel_status || item.novel?.status || item.novel_completion_status;
    const novelCompleted = item.is_completed === true || item.novel?.is_completed === true || isNovelCompleted(novelStatus);

    // ผู้ใช้อ่านไปถึงฉากจบจริงๆ หรือไม่ (ต้องเป็นสัญญาณเฉพาะผู้ใช้ ไม่ใช่สถิติรวมของนิยาย)
    const reachedEnding = Boolean(
        item.reached_ending ??
        item.is_ending ??
        item.ending_reached ??
        item.current_scene?.is_ending ??
        item.currentScene?.isEnding ??
        false
    );

    const currentSceneId =
        item.current_scene_id ??
        item.currentSceneId ??
        item.novel?.current_scene_id ??
        item.novel?.CurrentSceneID ??
        0;

    return {
        id: getBookId(item),

        title:
            item.title ||
            item.novel?.title ||
            "ไม่มีชื่อเรื่อง",

        author:
            item.pen_name ||
            item.penName ||
            item.author_pen_name ||
            item.author_penName ||
            item.author_name ||
            item.authorName ||
            item.author?.name ||
            item.novel?.pen_name ||
            item.novel?.author_name ||
            "ไม่ทราบผู้แต่ง",

        // คำโปรยของนิยาย — backend ส่งมาเป็น "captions" (เผื่อ endpoint อื่นใช้ชื่ออื่น จึงเก็บ fallback เดิมไว้ด้วย)
        description: stripHtml(
            item.captions ||
            item.novel?.captions ||
            item.description ||
            item.synopsis ||
            item.blurb ||
            item.novel?.description ||
            item.novel?.synopsis ||
            ""
        ),

        categories: (() => {
            const cats =
                item.categories ??
                item.Categories ??
                item.CategoryIDs ??
                item.category_ids ??
                item.novel?.categories ??
                item.novel?.Categories ??
                item.novel?.category_ids ??
                item.novel?.CategoryIDs ??
                [];

            if (!Array.isArray(cats) || cats.length === 0) return ["ทั่วไป"];

            const cleanCats = cats.map(normalizeCategoryName).filter(Boolean);
            const uniqueCats = Array.from(new Set(cleanCats));
            return uniqueCats.length > 0 ? uniqueCats : ["ทั่วไป"];
        })(),

        coverImage: formatMinioUrl(
            item.cover_image ||
            item.coverImage ||
            item.novel?.cover_image
        ),

        reading_status: normalizeReadingStatus({
            explicitStatus: item.reading_status || item.status,
            novelStatus,
            reachedEnding,
            currentSceneId,
        }),
        novelCompleted,

        latestChapter:
            item.latest_chapter ||
            item.latestChapter ||
            item.last_chapter ||
            item.chapter_title ||
            "ยังไม่มีตอน",

        lastReadAt:
            item.last_read_at ||
            item.lastReadAt ||
            item.updated_at ||
            item.updatedAt ||
            null,

        savedAt:
            item.created_at ||
            item.createdAt ||
            item.saved_at ||
            null,

        lastReadSceneTitle:
            item.last_read_scene_title ||
            item.lastReadSceneTitle ||
            "ยังไม่มีประวัติการอ่าน",

        startSceneId:
            item.start_scene_id ||
            item.startSceneId ||
            item.first_scene_id ||
            item.firstSceneId ||
            0,

        currentSceneId,

        // ---------- Statistics ----------

        // จำนวนครั้งที่นิยายเรื่องนี้ถูกเพิ่มเข้าชั้นหนังสือ (ของนิยาย ไม่ใช่ของผู้ใช้คนเดียว)
        bookshelfCount:
            item.bookshelf_count ||
            item.bookshelfCount ||
            item.shelf_count ||
            item.saved_count ||
            item.added_count ||
            item.novel?.bookshelf_count ||
            item.novel?.bookshelfCount ||
            item.novel?.shelf_count ||
            item.novel?.saved_count ||
            0,

        visitedCount:
            item.visited_count ||
            item.VisitedCount ||
            item.novel?.visited_count ||
            0,

        endingCount:
            item.ending_count ||
            item.endingCount ||
            item.novel?.ending_count ||
            0,

        totalScenes:
            item.total_scenes ||
            item.totalScenes ||
            item.scene_count ||
            item.novel?.total_scenes ||
            item.novel?.totalScenes ||
            0,

        views:
            item.views ||
            item.view_count ||
            item.novel?.views ||
            item.novel?.view_count ||
            0,

        likes:
            item.like_count ||
            item.likeCount ||
            item.likes ||
            item.novel?.like_count ||
            item.novel?.likes ||
            0,
    };
};

const statusLabels = {
    all: "ทั้งหมด",
    want_to_read: "ยังไม่อ่าน",
    reading: "กำลังอ่าน",
    finished: "อ่านจบแล้ว",
};

const BookshelfPage = () => {
    const navigate = useNavigate();
    const [filter, setFilter] = useState("all");
    const [books, setBooks] = useState([]);
    const [loading, setLoading] = useState(true);
    const [deleteTarget, setDeleteTarget] = useState(null); // book object
    const [deleting, setDeleting] = useState(false);
    const [deleteError, setDeleteError] = useState(null);
    const deleteModalCloseRef = useRef(null);

    useEffect(() => {
        if (!deleteTarget) return undefined;

        deleteModalCloseRef.current?.focus();
        const handleModalKeyDown = (event) => {
            if (event.key === "Escape" && !deleting) handleCancelDelete();
        };
        document.addEventListener("keydown", handleModalKeyDown);
        return () => document.removeEventListener("keydown", handleModalKeyDown);
    }, [deleteTarget, deleting]);

    const getStoredUser = () => {
        const raw = localStorage.getItem("user");
        if (!raw) return null;
        try {
            return JSON.parse(raw);
        } catch {
            return null;
        }
    };

    const isTokenExpired = (token) => {
        if (!token) return true;
        try {
            const [, payloadBase64] = token.split(".");
            if (!payloadBase64) return true;
            const payload = JSON.parse(atob(payloadBase64));
            if (!payload.exp) return false;
            return payload.exp < Math.floor(Date.now() / 1000);
        } catch {
            return true;
        }
    };

    useEffect(() => {
        let isMounted = true;

        const fetchBookshelf = async () => {
            const token = localStorage.getItem("token");
            if (!token || isTokenExpired(token)) {
                if (isMounted) setLoading(false);
                return;
            }

            const storedUser = getStoredUser();
            const userId = storedUser?.id || storedUser?.user_id;

            try {
                const headers = {};
                if (token) headers.Authorization = `Bearer ${token}`;

                const response = await axios.get(getBookshelfApiUrl(userId), {
                    headers,
                });

                const rawItems = extractBookshelfList(response.data);
                const mapped = rawItems.map(normalizeBook);

                if (isMounted) {
                    setBooks(mapped);
                }
            } catch (err) {
                console.error("Bookshelf fetch error:", err);
                if (err.response?.status === 401) {
                    localStorage.removeItem("token");
                }
            } finally {
                if (isMounted) setLoading(false);
            }
        };

        fetchBookshelf();

        const handleSync = () => {
            fetchBookshelf();
        };

        window.addEventListener("bookshelf-updated", handleSync);
        window.addEventListener("reading-history-updated", handleSync);
        window.addEventListener("focus", handleSync);

        return () => {
            isMounted = false;
            window.removeEventListener("bookshelf-updated", handleSync);
            window.removeEventListener("reading-history-updated", handleSync);
            window.removeEventListener("focus", handleSync);
        };
    }, []);

    const filteredBooks = useMemo(() => {
        if (filter === "all") return books;
        return books.filter((book) => book.reading_status === filter);
    }, [books, filter]);

    const statusCounts = useMemo(() => {
        const counts = { all: books.length, want_to_read: 0, reading: 0, finished: 0 };
        books.forEach((book) => {
            counts[book.reading_status] = (counts[book.reading_status] ?? 0) + 1;
        });
        return counts;
    }, [books]);

    const filterOptions = useMemo(
        () => [
            { value: "all", label: "ทั้งหมด", count: statusCounts.all },
            { value: "want_to_read", label: "ยังไม่อ่าน", count: statusCounts.want_to_read },
            { value: "reading", label: "กำลังอ่าน", count: statusCounts.reading },
            { value: "finished", label: "อ่านจบแล้ว", count: statusCounts.finished },
        ],
        [statusCounts]
    );

    const handleRequestDelete = (book) => {
        setDeleteError(null);
        setDeleteTarget(book);
    };

    const handleCancelDelete = () => {
        if (deleting) return;
        setDeleteTarget(null);
        setDeleteError(null);
    };

    const handleConfirmDelete = async () => {
        if (!deleteTarget) return;
        setDeleting(true);
        setDeleteError(null);
        try {
            const token = localStorage.getItem("token");
            const headers = { "Content-Type": "application/json" };
            if (token) headers.Authorization = `Bearer ${token}`;

            const bookId = deleteTarget.id;
            await axios.delete(`${API_BASE_URL}/bookshelves`, {
                headers,
                data: { novel_id: bookId },
            });

            setBooks((prev) => prev.filter((b) => b.id !== bookId));
            setDeleteTarget(null);
        } catch (err) {
            console.error("Remove from bookshelf error:", err);
            setDeleteError("ไม่สามารถนำนิยายออกจากชั้นหนังสือได้ในขณะนี้ กรุณาลองใหม่อีกครั้ง");
        } finally {
            setDeleting(false);
        }
    };

    return (
        <div className="bookshelf-page">
            <div className="bookshelf-page__sticky-header">
                <div className="bookshelf-page__top">
                    <div className="bookshelf-page__heading">
                        <button className="bookshelf-page__back-btn" onClick={() => navigate(-1)} aria-label="ย้อนกลับ">
                            <ArrowLeft size={18} />
                        </button>
                        <div className="bookshelf-page__labels">
                            <div className="bookshelf-page__eyebrow">ชั้นหนังสือของฉัน</div>
                            <div className="bookshelf-page__title">นิยายที่บันทึกไว้</div>
                        </div>
                    </div>
                    <div className="bookshelf-page__top-actions">
                        <div className="bookshelf-page__count">ทั้งหมด {books.length} เรื่อง</div>
                    </div>
                </div>
            </div>

            <div className="bookshelf-page__container">
                <div className="bookshelf-page__filters" role="tablist" aria-label="กรองสถานะการอ่าน">
                    {filterOptions.map((option) => (
                        <button
                            key={option.value}
                            type="button"
                            role="tab"
                            aria-selected={filter === option.value}
                            className={`bookshelf-page__filter-button ${filter === option.value ? "active" : ""}`}
                            onClick={() => setFilter(option.value)}
                        >
                            {option.label}
                            <span className="bookshelf-page__filter-count"> ({option.count})</span>
                        </button>
                    ))}
                </div>

                {loading && books.length === 0 ? (
                    <NovelCardGridSkeleton count={6} />
                ) : (
                    <>
                        {filteredBooks.length === 0 ? (
                            <div className="bookshelf-page__empty">
                                <BookOpen size={28} strokeWidth={1.5} />
                                <p>ยังไม่มีนิยายในสถานะนี้ ลองเลือกสถานะอื่น หรือเพิ่มนิยายเข้าชั้นหนังสือของคุณ</p>
                            </div>
                        ) : (
                            <div className="bookshelf-page__grid">
                                {filteredBooks.map((book) => {
                                    const isFinished = book.reading_status === "finished";
                                    const isReading = book.reading_status === "reading";
                                    const isWantToRead = book.reading_status === "want_to_read";

                                    const handleRead = () => {
                                        if (isWantToRead) {
                                            if (book.startSceneId) {
                                                navigate(`/reading/${book.id}/${book.startSceneId}`);
                                                return;
                                            }
                                            window.alert("นิยายเรื่องนี้ยังไม่มีฉากเริ่มต้นให้เปิดอ่านได้ในตอนนี้");
                                            navigate(`/novel/${book.id}`);
                                            return;
                                        }

                                        if (isReading) {
                                            if (book.currentSceneId) {
                                                navigate(`/reading/${book.id}/${book.currentSceneId}`);
                                                return;
                                            }
                                            navigate(`/reading/${book.id}`);
                                            return;
                                        }

                                        if (isFinished) {
                                            if (book.startSceneId) {
                                                navigate(`/reading/${book.id}/${book.startSceneId}`);
                                                return;
                                            }
                                            navigate(`/novel/${book.id}`);
                                        }
                                    };

                                    return (
                                        <article
                                            key={book.id}
                                            className="bookshelf-card"
                                        >
                                            <button
                                                type="button"
                                                className="bookshelf-card__remove-btn"
                                                onClick={(e) => {
                                                    e.stopPropagation();
                                                    handleRequestDelete(book);
                                                }}
                                                title="นำออกจากชั้นหนังสือ"
                                                aria-label={`นำ ${book.title} ออกจากชั้นหนังสือ`}
                                            >
                                                <Trash2 size={14} />
                                            </button>

                                            <div className="bookshelf-card__main-content">
                                                {/* Left: Cover Image with Status Badge */}
                                                <div className="bookshelf-card__cover-wrap">
                                                    <div
                                                        className="bookshelf-card__cover"
                                                        onClick={() => navigate(`/novel/${book.id}`)}
                                                    >
                                                        <img src={book.coverImage} alt={`${book.title} ปกนิยาย`} />
                                                        <span className={`bookshelf-card__status bookshelf-card__status--${book.reading_status}`}>
                                                            {statusLabels[book.reading_status] || "ไม่ระบุสถานะ"}
                                                        </span>
                                                        {book.novelCompleted && (
                                                            <span className="bookshelf-card__novel-status">จบแล้ว</span>
                                                        )}
                                                    </div>
                                                </div>

                                                {/* Right: Info details */}
                                                <div className="bookshelf-card__info-col">
                                                    <div className="bookshelf-card__info-top">
                                                        <h3
                                                            className="bookshelf-card__title"
                                                            onClick={() => navigate(`/novel/${book.id}`)}
                                                            title={book.title}
                                                        >
                                                            {book.title}
                                                        </h3>

                                                        <div className="bookshelf-card__author">
                                                            <Pencil size={12} className="bookshelf-card__author-icon" />
                                                            <span>{book.author}</span>
                                                        </div>

                                                        <div className="bookshelf-card__categories">
                                                            {book.categories.slice(0, 2).map((category, index) => (
                                                                <span
                                                                    key={`${book.id}-${category}-${index}`}
                                                                    className="bookshelf-card__tag"
                                                                >
                                                                    {category}
                                                                </span>
                                                            ))}
                                                            {book.categories.length > 2 && (
                                                                <span className="bookshelf-card__extra-categories">
                                                                    +{book.categories.length - 2}
                                                                </span>
                                                            )}
                                                        </div>

                                                        <p className="bookshelf-card__description" title={book.description || ""}>
                                                            {book.description || ""}
                                                        </p>
                                                    </div>

                                                    <div className="bookshelf-card__info-bottom">
                                                        {formatLastReadInfo(book) ? (
                                                            <div className="bookshelf-card__time-meta">
                                                                <Clock size={12} className="bookshelf-card__time-icon" />
                                                                <span>{formatLastReadInfo(book)}</span>
                                                            </div>
                                                        ) : null}

                                                        <div className="bookshelf-card__stats">
                                                            <div className="bookshelf-card__stat" title="ยอดวิว">
                                                                <Eye size={13} />
                                                                <span>{formatNumber(book.views)}</span>
                                                            </div>
                                                            <div className="bookshelf-card__stat" title="ยอดถูกใจ">
                                                                <Heart size={13} />
                                                                <span>{formatNumber(book.likes)}</span>
                                                            </div>
                                                            <div className="bookshelf-card__stat" title="เพิ่มเข้าชั้น">
                                                                <Bookmark size={13} />
                                                                <span>{formatNumber(book.bookshelfCount)}</span>
                                                            </div>
                                                        </div>
                                                    </div>
                                                </div>
                                            </div>

                                            {/* Bottom: Action Buttons (Read + Story Tree / Map) */}
                                            <div className="bookshelf-card__actions">
                                                <button
                                                    type="button"
                                                    className={`bookshelf-card__read-btn bookshelf-card__read-btn--${
                                                        isReading ? "continue" : isFinished ? "reread" : "start"
                                                    }`}
                                                    onClick={(e) => {
                                                        e.stopPropagation();
                                                        handleRead();
                                                    }}
                                                >
                                                    {isReading ? (
                                                        <>
                                                            <Play size={14} fill="currentColor" />
                                                            <span>อ่านต่อ</span>
                                                        </>
                                                    ) : isFinished ? (
                                                        <>
                                                            <RotateCw size={14} />
                                                            <span>อ่านอีกครั้ง</span>
                                                        </>
                                                    ) : (
                                                        <>
                                                            <Play size={14} fill="currentColor" />
                                                            <span>อ่านเลย</span>
                                                        </>
                                                    )}
                                                </button>

                                                <button
                                                    type="button"
                                                    className="bookshelf-card__map-btn"
                                                    onClick={(e) => {
                                                        e.stopPropagation();
                                                        navigate(`/storytree/${book.id}`);
                                                    }}
                                                    title="ดูแผนผังการอ่าน"
                                                >
                                                    <Map size={14} />
                                                    <span>แผนผัง</span>
                                                </button>
                                            </div>
                                        </article>
                                    );
                                })}
                            </div>
                        )}
                    </>
                )}
            </div>

            {deleteTarget && (
                <div className="bookshelf-delete-modal__overlay" onClick={handleCancelDelete}>
                    <div
                        className="bookshelf-delete-modal"
                        role="dialog"
                        aria-modal="true"
                        aria-labelledby="bookshelf-delete-modal-title"
                        onClick={(e) => e.stopPropagation()}
                    >
                        <button
                            type="button"
                            className="bookshelf-delete-modal__close"
                            ref={deleteModalCloseRef}
                            onClick={handleCancelDelete}
                            aria-label="ปิด"
                            disabled={deleting}
                        >
                            <X size={18} />
                        </button>

                        <div className="bookshelf-delete-modal__icon">
                            <Trash2 size={22} />
                        </div>

                        <div id="bookshelf-delete-modal-title" className="bookshelf-delete-modal__title">
                            นำออกจากชั้นหนังสือ?
                        </div>
                        <div className="bookshelf-delete-modal__body">
                            ต้องการนำนิยาย "{deleteTarget.title}" ออกจากชั้นหนังสือใช่หรือไม่
                        </div>

                        {deleteError && <div className="bookshelf-delete-modal__error">{deleteError}</div>}

                        <div className="bookshelf-delete-modal__actions">
                            <button
                                type="button"
                                className="bookshelf-delete-modal__cancel-btn"
                                onClick={handleCancelDelete}
                                disabled={deleting}
                            >
                                ยกเลิก
                            </button>
                            <button
                                type="button"
                                className="bookshelf-delete-modal__confirm-btn"
                                onClick={handleConfirmDelete}
                                disabled={deleting}
                            >
                                {deleting ? "กำลังนำออก..." : "นำออก"}
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default BookshelfPage;

import React, { useEffect, useMemo, useState, useCallback } from "react";
import axios from "axios";
import { useNavigate, useLocation } from "react-router-dom";
import { getNovelStatusInfo } from "../../../utils/novelStatus";
import { Eye, Heart, Bookmark, Pencil } from "lucide-react";
import { NovelCardGridSkeleton, DataLoadError } from "../../../components/Skeleton";
import "./CategoriesPage.css";

const API_BASE_URL = import.meta.env.VITE_API_BASE_URL || "http://localhost:8080";

const formatNumber = (num) => {
  if (!num) return 0;
  if (num >= 1000000) return (num / 1000000).toFixed(1) + "M+";
  if (num >= 1000) return (num / 1000).toFixed(1) + "k+";
  return num;
};

// เดิม hardcode "http://minio:9000" -> "http://localhost:9000" ไว้ตรงๆ ในโค้ด
// (พังทันทีถ้า deploy จริงหรือเปลี่ยน infra) ย้ายมาตั้งผ่าน env แทน — ค่า default ยังเหมือนเดิมทุกอย่าง
const MEDIA_INTERNAL_HOST = import.meta.env.VITE_MEDIA_INTERNAL_HOST || "http://minio:9000";
const MEDIA_PUBLIC_HOST = import.meta.env.VITE_MEDIA_PUBLIC_HOST || "http://localhost:9000";

function resolveCoverUrl(url) {
  if (!url) return null;
  return url.replace(MEDIA_INTERNAL_HOST, MEDIA_PUBLIC_HOST);
}



const normalizeNovel = (data) => {
  const rawCats = data.categories ?? data.Categories ?? data.category_ids ?? data.CategoryIDs ?? [];
  const statusInfo = getNovelStatusInfo(data);

  const cleanCategories = Array.isArray(rawCats) 
    ? rawCats.map(c => {
        if (!c) return "";
        if (typeof c === "string") return c.trim();
        return String(c.name || c.Title || c.title || c.label || "").trim();
      }).filter(Boolean) 
    : [];
    
  const uniqueCategories = [...new Set(cleanCategories)];

  return {
    id: data.id || data.novel_id,
    title: data.title || "ไม่มีชื่อเรื่อง",
    categories: uniqueCategories,
    coverImage: data.cover_image || data.coverImage || null,
    synopsis: data.captions || data.introduction || data.description || "",
    author: data.pen_name || data.penName || data.author_pen_name || data.author_penName || data.author_name || data.authorName || "ไม่ทราบผู้แต่ง",
    stats: {
      views: data.views || data.view_count || 0,
      likes: data.like_count || data.likes || 0,
      chaptersCount: data.chapters_count ?? data.chaptersCount ?? (data.chapters ? data.chapters.length : 0),
      bookshelfCount: data.bookshelf_count || data.bookshelfCount || data.saved_count || data.added_count || 0,
    },
    status: data.status || "draft",
    // isPublished = เผยแพร่ให้อ่านได้หรือยัง, isCompleted = แต่งจบเรื่องหรือยัง — คนละแกนกัน ห้ามใช้แทนกัน
    isPublished: statusInfo.isPublished,
    isCompleted: statusInfo.isCompleted,
  };
};

const CategoriesPage = () => {
  const navigate = useNavigate();
  const location = useLocation();

  // ดึงคำค้นหาเริ่มต้นจาก URL Query (?search=...)
  const getSearchFromUrl = useCallback(() => {
    const params = new URLSearchParams(location.search);
    return params.get("search") || "";
  }, [location.search]);

  const [categories, setCategories] = useState([]);
  const [novels, setNovels] = useState([]);
  const [selectedCategories, setSelectedCategories] = useState([]);
  const [searchQuery, setSearchQuery] = useState(getSearchFromUrl());
  
  // ตัวกรองสถานะนิยายและตัวกรองข้อมูล
  const [statusFilter, setStatusFilter] = useState("all"); 
  const [sortBy, setSortBy] = useState("popular"); 
  const [viewMode, setViewMode] = useState("grid"); 
  
  // การแบ่งหน้า
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 12;

  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // เปลี่ยนแปลงคำค้นหาตาม URL
  useEffect(() => {
    setSearchQuery(getSearchFromUrl());
  }, [location.search, getSearchFromUrl]);

  // จัดการฟัง Event การค้นหาเรียลไทม์
  useEffect(() => {
    const handleSearchChange = (e) => {
      if (e.detail !== undefined) {
        setSearchQuery(e.detail);
        setCurrentPage(1);
      }
    };
    window.addEventListener("search-change", handleSearchChange);
    return () => window.removeEventListener("search-change", handleSearchChange);
  }, []);

  const loadData = async () => {
    setLoading(true);
    setError(null);
    try {
      const [catRes, novelRes] = await Promise.all([
        axios.get(`${API_BASE_URL}/categories`),
        axios.get(`${API_BASE_URL}/novels`),
      ]);

      const catData = catRes.data?.data || catRes.data || [];
      const novelData = novelRes.data?.data?.novels
                     || novelRes.data?.novels
                     || novelRes.data?.data
                     || novelRes.data
                     || [];

      const allNovels = Array.isArray(novelData) ? novelData.map(normalizeNovel) : [];
      const publishedNovels = allNovels.filter(n => n.isPublished);

      const dbCats = Array.isArray(catData)
        ? catData.map(c => ({ id: c.category_id || c.id, name: String(c.name || c.title || "").trim() }))
        : [];

      // คำนวณนิยายต่อนั้นๆ
      const counts = {};
      publishedNovels.forEach(novel => {
        novel.categories.forEach(name => {
          counts[name] = (counts[name] || 0) + 1;
        });
      });

      const mergedCats = dbCats.map(c => ({
        ...c,
        count: counts[c.name] || 0
      }));

      setNovels(publishedNovels);
      setCategories(mergedCats);
    } catch (err) {
      console.error(err);
      setError("ไม่สามารถโหลดข้อมูลนิยายได้ในขณะนี้");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  // การกรองหมวดหมู่หลายตัวเลือก
  const handleCategorySelect = (name) => {
    setSelectedCategories(prev => {
      const next = prev.includes(name)
        ? prev.filter(c => c !== name)
        : [...prev, name];
      setCurrentPage(1);
      return next;
    });
  };

  const handleResetFilters = () => {
    setSelectedCategories([]);
    setCurrentPage(1);
  };

  // กรองและเรียงลำดับนิยาย
  const filteredAndSortedNovels = useMemo(() => {
    let result = [...novels];

    // 1. กรองคำค้นหา
    if (searchQuery.trim()) {
      const q = searchQuery.toLowerCase().trim();
      result = result.filter(n => 
        n.title.toLowerCase().includes(q) ||
        n.author.toLowerCase().includes(q) ||
        n.synopsis.toLowerCase().includes(q)
      );
    }

    // 2. กรองด้วยหมวดหมู่ (แบบ OR)
    if (selectedCategories.length > 0) {
      result = result.filter(n => 
        n.categories.some(cat => selectedCategories.includes(cat))
      );
    }

    // 3. กรองประเภทสถานะ (จบแล้ว vs ยังไม่จบ)
    if (statusFilter === "finished") {
      result = result.filter(n => n.isCompleted);
    } else if (statusFilter === "ongoing" || statusFilter === "writing") {
      result = result.filter(n => !n.isCompleted);
    }

    // 4. เรียงลำดับ
    if (sortBy === "popular") {
      result.sort((a, b) => b.stats.views - a.stats.views);
    } else if (sortBy === "latest") {
      result.sort((a, b) => (b.id || 0) - (a.id || 0));
    } else if (sortBy === "thai") {
      result.sort((a, b) => a.title.localeCompare(b.title, 'th'));
    }

    return result;
  }, [novels, searchQuery, selectedCategories, statusFilter, sortBy]);

  // ระบบ pagination
  const totalPages = Math.ceil(filteredAndSortedNovels.length / itemsPerPage);
  const paginatedNovels = useMemo(() => {
    const startIdx = (currentPage - 1) * itemsPerPage;
    return filteredAndSortedNovels.slice(startIdx, startIdx + itemsPerPage);
  }, [filteredAndSortedNovels, currentPage]);

  const handlePageChange = (page) => {
    if (page >= 1 && page <= totalPages) {
      setCurrentPage(page);
      window.scrollTo({ top: 380, behavior: "smooth" });
    }
  };

  return (
    <div className="search-page">
      <div className="search-page-container">
        
        {/* 1. แบนเนอร์ด้านบน */}
        <header className="category-hero-banner">
          <span className="banner-eyebrow">สำรวจทุกแนวนิยาย</span>
          <h1 className="banner-title">อ่านเรื่องที่ <span className="highlight-text">ใช่</span> สำหรับคุณ</h1>
          <p className="banner-desc">เลือกหมวดหมู่ที่สนใจ แล้วก้าวเข้าสู่โลกแห่งนิยายทางเลือกที่ไม่มีวันสิ้นสุด</p>
        </header>

        {/* 2. ส่วนเลือกหมวดหมู่ที่สนใจ */}
        <section className="categories-selection-sec">
          <div className="selection-header">
            <h2 className="selection-title">เลือกหมวดหมู่ <span className="pink-text">ที่สนใจ</span></h2>
            {selectedCategories.length > 0 && (
              <button type="button" className="reset-filter-btn" onClick={handleResetFilters}>
                🗘 รีเซ็ต
              </button>
            )}
          </div>

          <div className="categories-theme-grid">
            {categories.map((cat) => {
              const isSelected = selectedCategories.includes(cat.name);

              return (
                <div
                  key={cat.id}
                  className={`theme-card ${isSelected ? "selected" : ""}`}
                  onClick={() => handleCategorySelect(cat.name)}
                  role="button"
                  tabIndex={0}
                  aria-pressed={isSelected}
                  onKeyDown={(event) => {
                    if (event.key === "Enter" || event.key === " ") {
                      event.preventDefault();
                      handleCategorySelect(cat.name);
                    }
                  }}
                >
                  {isSelected && <span className="card-check-badge">✓</span>}
                  <div className="theme-card-info">
                    <span className="theme-name">{cat.name}</span>
                    <span className="theme-count">{cat.count.toLocaleString()} เรื่อง</span>
                  </div>
                </div>
              );
            })}
          </div>
        </section>

        {/* 3. แถบเครื่องมือจัดการ Toolbar */}
        <div className="toolbar-bar">
          <div className="toolbar-left-group">
            <span className="toolbar-label">⚙️ กรอง</span>
            <div className="status-tabs-group">
              <button 
                type="button" 
                className={`status-tab-btn ${statusFilter === "all" ? "active" : ""}`}
                aria-pressed={statusFilter === "all"}
                onClick={() => { setStatusFilter("all"); setCurrentPage(1); }}
              >
                ทั้งหมด
              </button>
              <button 
                type="button" 
                className={`status-tab-btn ${statusFilter === "ongoing" || statusFilter === "writing" ? "active" : ""}`}
                aria-pressed={statusFilter === "ongoing" || statusFilter === "writing"}
                onClick={() => { setStatusFilter("ongoing"); setCurrentPage(1); }}
              >
                ยังไม่จบ
              </button>
              <button 
                type="button" 
                className={`status-tab-btn ${statusFilter === "finished" ? "active" : ""}`}
                aria-pressed={statusFilter === "finished"}
                onClick={() => { setStatusFilter("finished"); setCurrentPage(1); }}
              >
                จบแล้ว
              </button>
            </div>

            <div className="toolbar-result-count">
              แสดง {filteredAndSortedNovels.length} เรื่อง
            </div>
          </div>

          <div className="toolbar-right-group">
            <div className="sort-dropdown-wrapper">
              <select 
                className="toolbar-select" 
                value={sortBy} 
                onChange={(e) => { setSortBy(e.target.value); setCurrentPage(1); }}
              >
                <option value="popular">ยอดนิยม</option>
                <option value="latest">อัปเดตล่าสุด</option>
                <option value="thai">ก-ฮ</option>
              </select>
            </div>

            <div className="view-mode-toggle">
              <button 
                type="button" 
                className={`view-btn ${viewMode === "grid" ? "active" : ""}`}
                aria-label="มุมมองตาราง"
                aria-pressed={viewMode === "grid"}
                onClick={() => setViewMode("grid")}
                title="มุมมองตาราง"
              >
                ⊞
              </button>
              <button 
                type="button" 
                className={`view-btn ${viewMode === "list" ? "active" : ""}`}
                aria-label="มุมมองรายการ"
                aria-pressed={viewMode === "list"}
                onClick={() => setViewMode("list")}
                title="มุมมองรายการ"
              >
                ☰
              </button>
            </div>
          </div>
        </div>

        {/* 4. แสดงผลการ์ดนิยาย */}
        {loading && novels.length === 0 ? (
          <NovelCardGridSkeleton count={8} />
        ) : error && novels.length === 0 ? (
          <DataLoadError title="ไม่สามารถโหลดข้อมูลนิยายได้" message={error} onRetry={loadData} />
        ) : paginatedNovels.length === 0 ? (
          <div className="search-empty-state">
            <div className="empty-icon">🔍</div>
            <h3>ยังไม่มีนิยายที่ตรงกับตัวเลือกนี้</h3>
            <p>ลองเปลี่ยนหมวดหมู่หรือสถานะการแสดงผล เพื่อค้นพบเรื่องใหม่ ๆ ที่น่าสนใจ</p>
          </div>
        ) : viewMode === "grid" ? (
          /* 📌 Grid View */
          <div className="novel-grid-layout">
            {paginatedNovels.map((novel) => {
              const isFinished = novel.isCompleted;

              return (
                <div 
                  key={novel.id} 
                  className="novel-grid-card"
                  onClick={() => navigate(`/novel/${novel.id}`)}
                  onKeyDown={(event) => {
                    if (event.key === "Enter" || event.key === " ") {
                      event.preventDefault();
                      navigate(`/novel/${novel.id}`);
                    }
                  }}
                  role="link"
                  tabIndex={0}
                >
                  <div className="novel-grid-cover">
                    {novel.coverImage ? (
                      <img 
                        src={resolveCoverUrl(novel.coverImage)} 
                        alt={novel.title} 
                        loading="lazy"
                      />
                    ) : (
                      <div className="grid-cover-placeholder">📘</div>
                    )}
                    {isFinished && (
                      <span className="card-status-tag finished">
                        จบแล้ว
                      </span>
                    )}
                  </div>

                  <div className="novel-grid-body">
                    <div className="novel-grid-tags">
                      {novel.categories.slice(0, 2).map((cat, cIdx) => (
                        <span key={cIdx} className="grid-tag-item">{cat}</span>
                      ))}
                      {novel.categories.length > 2 && (
                        <span className="grid-tag-item grid-tag-overflow">+{novel.categories.length - 2}</span>
                      )}
                    </div>

                    <h3 className="novel-grid-title" title={novel.title}>{novel.title}</h3>
                    
                    <div className="novel-grid-author">
                      <Pencil size={12} className="novel-author-icon" /> <span>{novel.author}</span>
                    </div>

                    <p className="novel-grid-synopsis" title={novel.synopsis || ""}>
                      {novel.synopsis || ""}
                    </p>

                    <div className="novel-grid-stats">
                      <div className="novel-grid-stat-item" title="เพิ่มเข้าชั้น">
                        <Bookmark size={13} />
                        <span>{formatNumber(novel.stats.bookshelfCount)}</span>
                      </div>
                      <div className="novel-grid-stat-item" title="ยอดเข้าชม">
                        <Eye size={13} />
                        <span>{formatNumber(novel.stats.views)}</span>
                      </div>
                      <div className="novel-grid-stat-item" title="ยอดถูกใจ">
                        <Heart size={13} />
                        <span>{formatNumber(novel.stats.likes)}</span>
                      </div>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        ) : (
          /* 📌 List View */
          <div className="novel-list-vertical">
            {paginatedNovels.map((novel) => {
              const isFinished = novel.isCompleted;

              return (
                <article 
                  key={novel.id} 
                  className="novel-horiz-card"
                  onClick={() => navigate(`/novel/${novel.id}`)}
                  onKeyDown={(event) => {
                    if (event.key === "Enter" || event.key === " ") {
                      event.preventDefault();
                      navigate(`/novel/${novel.id}`);
                    }
                  }}
                  role="link"
                  tabIndex={0}
                >
                  <div className="novel-horiz-cover">
                    {novel.coverImage ? (
                      <img 
                        src={resolveCoverUrl(novel.coverImage)} 
                        alt={novel.title} 
                        loading="lazy"
                      />
                    ) : (
                      <div className="novel-cover-placeholder">📘</div>
                    )}
                    {isFinished && (
                      <span className="card-status-tag finished">
                        จบแล้ว
                      </span>
                    )}
                  </div>

                  <div className="novel-horiz-details">
                    <div className="novel-grid-tags">
                      {novel.categories.slice(0, 2).map((cat, cIdx) => (
                        <span key={cIdx} className="grid-tag-item">{cat}</span>
                      ))}
                      {novel.categories.length > 2 && (
                        <span className="grid-tag-item grid-tag-overflow">+{novel.categories.length - 2}</span>
                      )}
                    </div>

                    <h3 className="novel-horiz-title" title={novel.title}>{novel.title}</h3>

                    <div className="novel-horiz-author">
                      <Pencil size={12} className="novel-author-icon" /> <span>{novel.author}</span>
                    </div>

                    <p className="novel-horiz-synopsis" title={novel.synopsis || ""}>
                      {novel.synopsis || ""}
                    </p>

                    <div className="novel-horiz-footer">
                      <div className="novel-meta-info">
                        <div className="novel-horiz-stat-item" title="เพิ่มเข้าชั้น">
                          <Bookmark size={13} />
                          <span>{formatNumber(novel.stats.bookshelfCount)}</span>
                        </div>
                        <div className="novel-horiz-stat-item" title="ยอดเข้าชม">
                          <Eye size={13} />
                          <span>{formatNumber(novel.stats.views)}</span>
                        </div>
                        <div className="novel-horiz-stat-item" title="ยอดถูกใจ">
                          <Heart size={13} />
                          <span>{formatNumber(novel.stats.likes)}</span>
                        </div>
                      </div>
                    </div>
                  </div>
                </article>
              );
            })}
          </div>
        )}

        {/* 5. Pagination */}
        {totalPages > 1 && (
          <div className="pagination-wrapper">
            <button 
              type="button" 
              className="page-nav-btn"
              onClick={() => handlePageChange(currentPage - 1)}
              disabled={currentPage === 1}
            >
              &lt;
            </button>
            
            {Array.from({ length: totalPages }).map((_, idx) => {
              const pageNum = idx + 1;
              return (
                <button
                  key={pageNum}
                  type="button"
                  className={`page-num-btn ${currentPage === pageNum ? "active" : ""}`}
                  onClick={() => handlePageChange(pageNum)}
                >
                  {pageNum}
                </button>
              );
            })}

            <button 
              type="button" 
              className="page-nav-btn"
              onClick={() => handlePageChange(currentPage + 1)}
              disabled={currentPage === totalPages}
            >
              &gt;
            </button>
          </div>
        )}

      </div>
    </div>
  );
};

export default CategoriesPage;

import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { Search, X, ArrowUpDown, ArrowLeft, AlertTriangle, Feather } from "lucide-react";
import WriterCard from "../../../components/WriterCard/WriterCard";
import { Skeleton, DataLoadError } from "../../../components/Skeleton";
import "./FollowingWriters.css";

const API_BASE_URL = import.meta.env.VITE_API_BASE_URL || "http://localhost:8080";

function stripHTML(value) {
  if (!value || typeof value !== "string") return null;
  return value.replace(/<[^>]*>/g, "").trim();
}

function formatThaiDate(value) {
  if (!value) return null;

  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) return null;

  const datePart = new Intl.DateTimeFormat("th-TH", {
    day: "2-digit",
    month: "short",
    year: "numeric",
    timeZone: "Asia/Bangkok",
  }).format(date);

  const timePart = new Intl.DateTimeFormat("th-TH", {
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
    timeZone: "Asia/Bangkok",
  }).format(date);

  return `${datePart.replace(/,/, "")} เวลา ${timePart} น.`;
}

function normalizeLatestUpdate(rawUpdate) {
  if (!rawUpdate) return null;

  if (typeof rawUpdate === "string" || rawUpdate instanceof Date || typeof rawUpdate === "number") {
    const formattedTime = formatThaiDate(rawUpdate);
    return {
      title: "อัปเดตล่าสุด",
      detail: null,
      time: formattedTime,
      timestamp: new Date(rawUpdate).getTime(),
    };
  }

  if (typeof rawUpdate === "object") {
    const timestampValue = rawUpdate.timestamp ?? rawUpdate.updated_at ?? rawUpdate.updatedAt ?? rawUpdate.created_at ?? rawUpdate.createdAt ?? rawUpdate.date ?? rawUpdate.datetime ?? rawUpdate.time ?? null;
    const parsedTimestamp = timestampValue ? new Date(timestampValue) : null;
    const formattedTime = parsedTimestamp && !Number.isNaN(parsedTimestamp.getTime())
      ? formatThaiDate(parsedTimestamp)
      : formatThaiDate(rawUpdate.time || rawUpdate.formattedTime || rawUpdate.formatted_time || null);

    return {
      title: rawUpdate.title || rawUpdate.name || "อัปเดตล่าสุด",
      detail: rawUpdate.detail || rawUpdate.description || rawUpdate.message || rawUpdate.summary || null,
      time: formattedTime || rawUpdate.time || rawUpdate.formattedTime || rawUpdate.formatted_time || null,
      timestamp: parsedTimestamp && !Number.isNaN(parsedTimestamp.getTime()) ? parsedTimestamp.getTime() : null,
    };
  }

  return null;
}

const formatMinioUrl = (url) => {
  if (!url) return null;
  return url.replace('http://minio:9000', 'http://localhost:9000');
};

function normalizeNovel(novel) {
  if (!novel || typeof novel !== "object") return null;
  return {
    id: novel.novel_id ?? novel.id ?? novel.novelId,
    title: novel.title || novel.name || "ไม่ทราบชื่อเรื่อง",
    status: novel.status || novel.state || "ongoing",
    cover: formatMinioUrl(novel.cover || novel.cover_image || novel.coverImage || novel.thumbnail) || null,
    chapterCount: novel.chapter_count ?? novel.chapterCount ?? 0,
  };
}

function mapWriter(writer) {
  const rawBio = writer.bio || writer.description || writer.bio_html || writer.bioHtml || null;
  const plainBio = stripHTML(rawBio);
  const novels = Array.isArray(writer.novels)
    ? writer.novels.map(normalizeNovel).filter(Boolean)
    : [];
  const latestUpdate = normalizeLatestUpdate(writer.latest_update || writer.latestUpdate || null);

  const rawAvatar =
    writer.avatar_url ||
    writer.avatar ||
    writer.avatarUrl ||
    writer.pic_profile ||
    writer.author_avatar ||
    writer.user_avatar ||
    writer.profile_picture;

  const resolvedAvatar = formatMinioUrl(rawAvatar) || null;

  const followerCount =
    writer.follower_count ??
    writer.followers_count ??
    writer.total_followers ??
    writer.total_like_count ??
    writer.followers ??
    0;

  const novelCount =
    writer.novel_count ??
    writer.total_novels ??
    writer.novels_count ??
    writer.novelCount ??
    novels.length;

  return {
    id: writer.writer_id ?? writer.id,
    name: writer.pen_name || writer.name || writer.name_lastname || "นักเขียน",
    bio: plainBio || null,
    avatar: resolvedAvatar,
    color: writer.color || ["#6D28D9", "#E91E8C", "#0F766E", "#0EA5E9"][Math.abs((writer.writer_id ?? writer.id ?? 0) % 4)],
    followers: followerCount,
    novelCount: novelCount,
    hasUnreadUpdate: Boolean(writer.has_unread_update || writer.hasUnreadUpdate),
    novels,
    latestUpdate,
    latestUpdateTimestamp: latestUpdate?.timestamp ?? null,
  };
}

export default function FollowingWriters() {
  const navigate = useNavigate();
  const [writers, setWriters] = useState([]);
  const [search, setSearch] = useState("");
  const [sort, setSort] = useState("recent");
  const [showSort, setShowSort] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const SORT_OPTIONS = {
    recent:    "อัปเดตล่าสุด",
    followers: "ผู้ติดตามมากสุด",
    name:      "ตามชื่อ",
  };

  useEffect(() => {
    const fetchFollowingWriters = async () => {
      const token = localStorage.getItem("token");
      
      // อ่านข้อมูลจาก LocalStorage เสมอเพื่อเตรียมไว้สำหรับ Fallback/Merge
      let localWriters = [];
      try {
        const localSaved = localStorage.getItem("local_following_writers");
        const list = localSaved ? JSON.parse(localSaved) : [];
        localWriters = Array.isArray(list) ? list.map(mapWriter) : [];
      } catch (e) {
        console.warn("Failed to read local following writers:", e);
      }

      if (!token) {
        // หากไม่มี token ให้ใช้เฉพาะข้อมูลจาก LocalStorage เพื่อให้ใช้งานหน้าหลักซิงค์มาหน้าติดตามได้
        setWriters(localWriters);
        setLoading(false);
        return;
      }

      try {
        const response = await fetch(`${API_BASE_URL}/api/users/following-writers`, {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });

        if (!response.ok) {
          const errorData = await response.json().catch(() => ({}));
          throw new Error(errorData.message || "โหลดรายการนักเขียนที่ติดตามไม่สำเร็จ");
        }

        const payload = await response.json().catch(() => null) || {};
        const body = payload?.data ?? payload ?? {};
        const followedArray = Array.isArray(body) ? body : (body.following || body.writers || []);
        const followedWriters = Array.isArray(followedArray) ? followedArray.map(mapWriter) : [];
        
        // ผนวกรวมข้อมูลจาก API และ LocalStorage โดยไม่ให้ไอดีทับซ้อนกัน
        const mergedList = [...followedWriters];
        localWriters.forEach(lw => {
          if (!mergedList.some(w => Number(w.id) === Number(lw.id))) {
            mergedList.push(lw);
          }
        });

        // 🟢 ดึงข้อมูลสถิติที่แท้จริง (จำนวนผู้ติดตาม + นิยายที่เผยแพร่ทั้งหมด) จาก /writer/:id และ /novels
        let enrichedList = [...mergedList];
        try {
          enrichedList = await Promise.all(
            mergedList.map(async (writer) => {
              const wId = writer.id;
              if (!wId) return writer;

              try {
                const res = await fetch(`${API_BASE_URL}/writer/${wId}`, {
                  headers: token ? { Authorization: `Bearer ${token}` } : {},
                });
                if (res.ok) {
                  const resJson = await res.json().catch(() => null);
                  const wData = resJson?.data || resJson?.writer || resJson || {};
                  if (wData) {
                    let rawNovels = Array.isArray(wData.novels) ? wData.novels : [];

                    // ถ้า wData.novels ไม่มีหรือโล่ง ให้ดึงรายการนิยายทั้งหมดจาก /novels
                    if (rawNovels.length === 0) {
                      try {
                        const nRes = await fetch(`${API_BASE_URL}/novels`, {
                          headers: token ? { Authorization: `Bearer ${token}` } : {},
                        });
                        if (nRes.ok) {
                          const nJson = await nRes.json().catch(() => null);
                          const rawAll = nJson?.novels || nJson?.data?.novels || nJson?.data || (Array.isArray(nJson) ? nJson : []);
                          rawNovels = (Array.isArray(rawAll) ? rawAll : []).filter(
                            n => String(n.author_id || n.authorId || n.user_id || n.userId || n.writer_id) === String(wId)
                          );
                        }
                      } catch (_) {}
                    }

                    const normalizedNovels = rawNovels.map(normalizeNovel).filter(Boolean);
                    const finalNovels = normalizedNovels.length > 0 ? normalizedNovels : writer.novels;

                    const followerCount =
                      wData.follower_count ??
                      wData.followers_count ??
                      wData.followers ??
                      wData.total_followers ??
                      writer.followers ??
                      0;

                    const novelCount =
                      wData.novel_count ??
                      wData.total_novels ??
                      wData.novels_count ??
                      finalNovels.length ??
                      writer.novelCount ??
                      0;

                    return {
                      ...writer,
                      name: wData.pen_name || wData.name || writer.name,
                      bio: stripHTML(wData.bio || writer.bio),
                      avatar: formatMinioUrl(wData.avatar_url || wData.avatar || wData.pic_profile || writer.avatar) || writer.avatar,
                      followers: followerCount,
                      novelCount: Math.max(novelCount, finalNovels.length),
                      novels: finalNovels,
                      latestUpdate: normalizeLatestUpdate(wData.latest_update || wData.latestUpdate || writer.latestUpdate),
                    };
                  }
                }
              } catch (e) {
                console.warn("Failed to fetch full stats for writer", wId, e);
              }
              return writer;
            })
          );
        } catch (e) {
          enrichedList = mergedList;
        }

        setWriters(enrichedList);
        setError("");
      } catch (err) {
        console.error("โหลดรายการนักเขียนที่ติดตามล้มเหลว:", err);
        // หาก API ล้มเหลว ให้ใช้ข้อมูลจาก LocalStorage แทนเพื่อไม่ให้หน้าว่างเปล่า
        setWriters(localWriters);
        setError("");
      } finally {
        setLoading(false);
      }
    };

    fetchFollowingWriters();
  }, []);

  const handleUnfollow = async (id) => {
    const confirmed = window.confirm("คุณต้องการเลิกติดตามนักเขียนคนนี้ใช่หรือไม่?");
    if (!confirmed) return;

    const removedWriter = writers.find((writer) => Number(writer.id) === Number(id));
    const savedFollowingWriters = localStorage.getItem("local_following_writers");

    // อัปเดต UI ทันที แล้วคืนรายการถ้า backend ปฏิเสธคำขอ
    setWriters((previous) => previous.filter((writer) => writer.id !== id));

    // 2. อัปเดตและซิงค์ลบออกจาก LocalStorage
    try {
      const saved = localStorage.getItem("local_following_writers");
      let list = saved ? JSON.parse(saved) : [];
      list = list.filter(w => Number(w.id) !== Number(id));
      localStorage.setItem("local_following_writers", JSON.stringify(list));
    } catch (e) {
      console.warn("Failed to remove from local_following_writers:", e);
    }

    // 3. เรียก API ลบออกจากระบบ Backend จริง (ถ้ามี Token)
    const token = localStorage.getItem("token");
    if (token) {
      try {
        const response = await fetch(`${API_BASE_URL}/api/writers/${id}/unfollow`, {
          method: "POST",
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json"
          }
        });
        if (!response.ok) throw new Error(`unfollow failed: ${response.status}`);
      } catch (e) {
        console.warn("API unfollow request warning:", e.message);
        if (removedWriter) setWriters((previous) => [removedWriter, ...previous]);
        if (savedFollowingWriters !== null) {
          localStorage.setItem("local_following_writers", savedFollowingWriters);
        }
        alert("ไม่สามารถเลิกติดตามนักเขียนได้ กรุณาลองใหม่อีกครั้ง");
      }
    }
  };

  let visible = writers.filter(w => {
    const q = search.toLowerCase();
    return (
      w.name.toLowerCase().includes(q) ||
      w.novels.some(n => n.title.toLowerCase().includes(q))
    );
  });
  if (sort === "followers") visible = [...visible].sort((a,b) => b.followers - a.followers);
  if (sort === "name") visible = [...visible].sort((a,b) => a.name.localeCompare(b.name));
  if (sort === "recent") visible = [...visible].sort((a,b) => (b.latestUpdateTimestamp ?? 0) - (a.latestUpdateTimestamp ?? 0));

  if (loading) {
    return (
      <div className="following-page">
        <div className="following-page__sticky-header">
          <div className="following-page__top">
            <div className="following-page__heading">
              <button className="backBtn" onClick={() => navigate(-1)} aria-label="ย้อนกลับ">
                <ArrowLeft size={18} />
              </button>
              <div className="following-page__labels">
                <div className="following-page__eyebrow">นักเขียนของฉัน</div>
                <div className="following-page__title">นักเขียนที่ติดตาม</div>
              </div>
            </div>
            <div className="following-page__count">กำลังโหลด...</div>
          </div>
        </div>
        <div className="following-page__container" style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: '20px', padding: '24px 0' }}>
          {Array.from({ length: 6 }).map((_, idx) => (
            <div key={idx} style={{ background: '#fff', borderRadius: '16px', padding: '20px', border: '1px solid #f0eef4', display: 'flex', gap: '16px', alignItems: 'center' }}>
              <Skeleton variant="circular" width="56px" height="56px" />
              <div style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: '8px' }}>
                <Skeleton width="60%" height="18px" />
                <Skeleton width="40%" height="13px" />
              </div>
            </div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="following-page">
      <div className="following-page__sticky-header">
        <div className="following-page__top">
          <div className="following-page__heading">
            <button className="backBtn" onClick={() => navigate(-1)} aria-label="ย้อนกลับ">
              <ArrowLeft size={18} />
            </button>
            <div className="following-page__labels">
              <div className="following-page__eyebrow">นักเขียนของฉัน</div>
              <div className="following-page__title">นักเขียนที่ติดตาม</div>
            </div>
          </div>

          <div className="following-page__count">ทั้งหมด {writers.length} คน</div>
        </div>
      </div>

      <div className="following-page__container">
        <div className="filterRow">
          <div className="searchBar">
            <span className="searchIcon"><Search size={16} /></span>
            <input
              value={search}
              onChange={e => setSearch(e.target.value)}
              placeholder="ค้นหาชื่อนักเขียนหรือนิยาย..."
              className="searchInput"
            />
            {search && (
              <button onClick={() => setSearch("")} className="clearBtn" aria-label="ล้างคำค้นหา">
                <X size={14} />
              </button>
            )}
          </div>

          <div className="sortWrapper">
              <button
                type="button"
                onClick={() => setShowSort(p => !p)}
                className="sortTrigger"
                aria-expanded={showSort}
                aria-haspopup="menu"
              >
              <ArrowUpDown size={14} /> <span className="sortLabel">{SORT_OPTIONS[sort]}</span>
            </button>
            
            {showSort && (
              <>
                <div onClick={() => setShowSort(false)} className="backdrop" />
                <div className="dropdownMenu">
                  {Object.entries(SORT_OPTIONS).map(([k, v]) => (
                    <button 
                      key={k} 
                      onClick={() => { setSort(k); setShowSort(false); }} 
                      className={`dropdownItem ${sort === k ? "dropdownItemActive" : ""}`}
                    >
                      {v}
                    </button>
                  ))}
                </div>
              </>
            )}
          </div>
        </div>

        {error && (
          <div className="emptyState">
            <div className="emptyIcon"><AlertTriangle size={40} /></div>
            <div className="emptyTitle">ไม่สามารถโหลดข้อมูลได้</div>
            <div className="emptyText">{error}</div>
          </div>
        )}

        {!error && visible.length === 0 ? (
          <div className="emptyState">
            <div className="emptyIcon">
              {search ? <Search size={40} /> : <Feather size={40} />}
            </div>
            <div className="emptyTitle">
              {search ? "ไม่พบนักเขียนที่ค้นหา" : "ยังไม่ได้ติดตามนักเขียนคนไหน"}
            </div>
            <div className="emptyText">
              {search ? "ลองเปลี่ยนคำค้นหาดูนะ" : "ไปค้นหานักเขียนที่ชอบแล้วกดติดตามได้เลย"}
            </div>
          </div>
        ) : (
          <div className="listGrid">
            {visible.map(w => (
              <WriterCard key={w.id} writer={w} onUnfollow={handleUnfollow} isFollowing={true} />
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

