            fontSize: "0.78rem",
            borderRadius: "999px",
            border: sceneFilter === "published" ? "1px solid #fbcfe8" : "1px solid #e2e8f0",
            cursor: "pointer",
            transition: "all 0.2s ease-in-out",
            backgroundColor: sceneFilter === "published" ? "#fff0f5" : "#ffffff",
