                    if (node.data?.visitors >= (node.data?.midMax || 800)) return VISITOR_SHADES.MEDIUM.border;
                    return VISITOR_SHADES.LOW.border;
                  }}
                  maskColor="rgba(250, 249, 246, 0.6)"
                />
              </ReactFlow>
