// Modal overlay ที่ใช้ร่วมกันสำหรับ popup ทั้งหมดในหน้านี้ (เพิ่ม/ลบฉาก, จัดการทางเลือก, ยืนยันต่างๆ)
// เดิมแต่ละ popup ก็อปวางสไตล์ overlay/กล่องซ้ำกันทั้ง 5 จุด จึงรวมมาไว้ที่เดียว
const WstModalOverlay = ({
