      : "#38BDF8";

  const typeBgColor = type === "start" || type === "starting" ? "#DCFCE7"
    : type === "ending" || type === "end" ? "#FEE2E2"
      : "#E0F2FE";

  const typeIcon = type === "start" || type === "starting" ? "▶"
    : type === "ending" || type === "end" ? "🏆"
